window.SIGE_TEMPLATES = {
  "painel-aluno/aluno-notas": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ALUNO | As Minhas Notas & Boletim Oficial -->\n<!-- Página independente do módulo: aluno-notas.html -->\n<!-- 3 Possibilidades de Visualização / Publicação: I, II, III Trimestres e Todos -->\n<!-- ===================================================================== -->\n      <section id=\"view-aluno-notas\" class=\"modulo-view\" style=\"display: none;\">\n        <!-- Banner de Notas Totalmente Bloqueadas/Suspensas -->\n        <div id=\"bannerNotasBloqueadas\" class=\"alert alert-warning d-none mb-3 shadow-sm\">\n          <i class=\"bi bi-lock-fill me-2 fs-5\"></i>\n          <strong>Visualização Temporariamente Suspensa:</strong> A Direcção da Escola suspendeu a exibição de notas no portal para consolidação de pautas e conselhos pedagógicos. Os seus dados de matrícula, pagamentos e declarações continuam disponíveis.\n        </div>\n\n        <!-- Banner de Trimestre Específico Ainda Não Publicado -->\n        <div id=\"bannerTrimestreNaoPublicado\" class=\"alert alert-info d-none mb-3 shadow-sm\">\n          <i class=\"bi bi-info-circle-fill me-2 fs-5\"></i>\n          <strong>Trimestre em Consolidação:</strong> As notas deste trimestre ainda não foram homologadas nem publicadas pela Direcção Pedagógica da Escola.\n        </div>\n\n        <div id=\"cardNotasAluno\" class=\"card p-4 shadow-sm\">\n          <!-- Cabeçalho Principal -->\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-3 mb-3 border-bottom pb-3\">\n            <div>\n              <h5 class=\"fw-bold mb-1\"><i class=\"bi bi-card-checklist text-success me-2\"></i>O Meu Histórico de Notas & Avaliações</h5>\n              <small class=\"text-muted\">Classificações: 0 a 9.4 a Vermelho (Negativa), 9.5 a 20 a Preto (Positiva).</small>\n            </div>\n            <div class=\"d-flex align-items-center flex-wrap gap-2\">\n              <span class=\"badge bg-light text-dark border p-2\">Média: <strong id=\"alunoMediaGeral\" class=\"text-primary fs-6\">--</strong></span>\n              <span id=\"alunoSituacaoBadge\" class=\"badge bg-secondary p-2\">A Ponderar</span>\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarBoletimAlunoPdf()\" title=\"Descarregar boletim em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarBoletimAlunoExcel()\" title=\"Descarregar notas em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarBoletimAlunoWord()\" title=\"Descarregar notas em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-outline-danger btn-sm fw-bold\" onclick=\"fazerLogout(event)\" title=\"Terminar Sessão\">\n                <i class=\"bi bi-box-arrow-right me-1\"></i> Sair\n              </button>\n            </div>\n          </div>\n\n          <!-- Barra de Seleção das 3 Possibilidades de Trimestres e Todos -->\n          <div class=\"d-flex flex-wrap align-items-center justify-content-between gap-3 p-3 mb-3 rounded-3 bg-light border\">\n            <div class=\"d-flex align-items-center flex-wrap gap-2\">\n              <span class=\"fw-bold small text-secondary\"><i class=\"bi bi-funnel-fill me-1\"></i> Visualização:</span>\n              <div class=\"btn-group btn-group-sm\" role=\"group\" id=\"grupoBotoesTrimestreAluno\">\n                <button type=\"button\" class=\"btn btn-outline-primary active\" id=\"btnAlunoTrimestreTodos\" onclick=\"alternarTrimestreAluno('TODOS')\">\n                  <i class=\"bi bi-collection-fill me-1\"></i> Todos (I, II e III)\n                </button>\n                <button type=\"button\" class=\"btn btn-outline-primary\" id=\"btnAlunoTrimestre1\" onclick=\"alternarTrimestreAluno('1_TRIMESTRE')\">\n                  <i class=\"bi bi-1-circle me-1\"></i> I Trimestre\n                </button>\n                <button type=\"button\" class=\"btn btn-outline-primary\" id=\"btnAlunoTrimestre2\" onclick=\"alternarTrimestreAluno('2_TRIMESTRE')\">\n                  <i class=\"bi bi-2-circle me-1\"></i> II Trimestre\n                </button>\n                <button type=\"button\" class=\"btn btn-outline-primary\" id=\"btnAlunoTrimestre3\" onclick=\"alternarTrimestreAluno('3_TRIMESTRE')\">\n                  <i class=\"bi bi-3-circle me-1\"></i> III Trimestre\n                </button>\n              </div>\n            </div>\n            <div class=\"d-flex align-items-center gap-2\">\n              <span class=\"small text-muted\" id=\"statusPublicacaoEscolaBadge\">\n                <i class=\"bi bi-broadcast text-success me-1\"></i> Publicação Oficial: <strong id=\"lblPublicacaoEscola\" class=\"text-dark\">A carregar...</strong>\n              </span>\n            </div>\n          </div>\n\n          <!-- Tabela de Avaliações -->\n          <div class=\"table-responsive\">\n            <table class=\"table table-bordered table-hover text-center align-middle mb-0\" id=\"tabelaAlunoNotas\">\n              <thead class=\"table-light\" id=\"tabelaAlunoNotasCabecalho\">\n                <tr>\n                  <th class=\"text-start\">Disciplina</th>\n                  <th>1º Trimestre</th>\n                  <th>2º Trimestre</th>\n                  <th>3º Trimestre</th>\n                  <th>Média Final (MFD)</th>\n                  <th>Faltas</th>\n                  <th>Situação</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaAlunoNotasCorpo\">\n                <tr><td colspan=\"7\" class=\"text-center py-4\">A carregar notas do aluno...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-aluno/aluno-pagamentos": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ALUNO | As Minhas Propinas & Mensalidades -->\n<!-- Página independente do módulo: aluno-pagamentos.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-aluno-pagamentos\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-3 mb-4\">\n          <div class=\"col-md-4\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Total Liquidado</span>\n                <h4 id=\"alunoTotalPagoCard\" class=\"fw-bold mb-0 text-success\">0 <span class=\"moeda-sufixo\">MZN</span></h4>\n              </div>\n              <div class=\"stat-icon bg-success bg-opacity-10 text-success\"><i class=\"bi bi-check-circle-fill\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-4\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Propinas Pendentes</span>\n                <h4 id=\"alunoTotalPendenteCard\" class=\"fw-bold mb-0 text-warning\">0 <span class=\"moeda-sufixo\">MZN</span></h4>\n              </div>\n              <div class=\"stat-icon bg-warning bg-opacity-10 text-warning\"><i class=\"bi bi-clock-history\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-4\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Situação das Propinas</span>\n                <h4 id=\"alunoSituacaoPropinaCard\" class=\"fw-bold mb-0 text-primary\">Regular</h4>\n              </div>\n              <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\"><i class=\"bi bi-wallet2\"></i></div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card p-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3\">\n            <div>\n              <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-cash-stack text-success me-2\"></i>As Minhas Mensalidades & Propinas</h5>\n              <small class=\"text-muted\">Consulte os pagamentos efectuados e descarregue os seus recibos oficiais em PDF.</small>\n            </div>\n            <div class=\"d-flex gap-2 align-items-center\">\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarExtratoAlunoPdf()\" title=\"Descarregar extrato em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarExtratoAlunoExcel()\" title=\"Descarregar extrato em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarExtratoAlunoWord()\" title=\"Descarregar extrato em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-outline-primary btn-sm\" onclick=\"carregarAlunoPagamentos()\">\n                <i class=\"bi bi-arrow-clockwise me-1\"></i> Actualizar\n              </button>\n            </div>\n          </div>\n\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Descrição</th>\n                  <th>Mês Ref.</th>\n                  <th>Valor (MZN)</th>\n                  <th>Vencimento</th>\n                  <th>Estado</th>\n                  <th class=\"text-end\">Comprovativo / Recibo</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaAlunoPagamentosCorpo\">\n                <tr><td colspan=\"6\" class=\"text-center py-4\">A carregar pagamentos...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-aluno/aluno-perfil": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ALUNO | O Meu Perfil & Filiação -->\n<!-- Página independente do módulo: aluno-perfil.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-aluno-perfil\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-4\">\n          <div class=\"col-lg-6\">\n            <div class=\"card p-4\">\n              <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3\">\n                <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-person-vcard text-primary me-2\"></i>Os Meus Dados Pessoais</h5>\n                <div class=\"d-flex gap-2\">\n                  <button class=\"btn btn-outline-primary btn-sm fw-semibold\" onclick=\"modalRedefinirMinhaSenha()\">\n                    <i class=\"bi bi-key-fill me-1\"></i> Alterar a Minha Senha\n                  </button>\n                  <button class=\"btn btn-outline-danger btn-sm fw-bold\" onclick=\"fazerLogout(event)\">\n                    <i class=\"bi bi-box-arrow-right me-1\"></i> Sair do Sistema\n                  </button>\n                </div>\n              </div>\n              <div class=\"table-responsive\">\n                <table class=\"table table-bordered table-sm mb-4\">\n                  <tr><th class=\"bg-light w-40\">Nome Completo:</th><td id=\"alunoPerfilNome\"></td></tr>\n                  <tr><th class=\"bg-light\">Apelido:</th><td id=\"alunoPerfilApelido\"></td></tr>\n                  <tr><th class=\"bg-light\">Data de Nascimento:</th><td id=\"alunoPerfilDataNasc\">-</td></tr>\n                  <tr><th class=\"bg-light\">Código do Aluno (Matrícula):</th><td id=\"alunoPerfilMatricula\" class=\"font-monospace fw-bold text-primary\"></td></tr>\n                  <tr><th class=\"bg-light\">Turma & Grau:</th><td id=\"alunoPerfilTurma\"></td></tr>\n                  <tr><th class=\"bg-light\">Documento (BI/DIRE):</th><td id=\"alunoPerfilDoc\"></td></tr>\n                  <tr><th class=\"bg-light\">NUIT:</th><td id=\"alunoPerfilNUIT\"></td></tr>\n                  <tr><th class=\"bg-light\">Província / Distrito:</th><td id=\"alunoPerfilLocal\"></td></tr>\n                </table>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-lg-6\">\n            <div class=\"card p-4\">\n              <h5 class=\"fw-bold mb-3\"><i class=\"bi bi-people text-primary me-2\"></i>Filiação & Encarregado de Educação</h5>\n              <div class=\"table-responsive\">\n                <table class=\"table table-bordered table-sm mb-3\">\n                  <tr><th class=\"bg-light w-40\">Nome do Pai:</th><td id=\"alunoPerfilPai\">-</td></tr>\n                  <tr><th class=\"bg-light\">Nome da Mãe:</th><td id=\"alunoPerfilMae\">-</td></tr>\n                  <tr><th class=\"bg-light\">Encarregado de Educação:</th><td id=\"alunoPerfilResp\">-</td></tr>\n                  <tr><th class=\"bg-light\">Contacto do Encarregado:</th><td id=\"alunoPerfilTelResp\">-</td></tr>\n                  <tr><th class=\"bg-light\">E-mail do Encarregado:</th><td id=\"alunoPerfilEmailResp\">-</td></tr>\n                </table>\n              </div>\n              <div class=\"alert alert-info py-2 px-3 small mb-0\">\n                <i class=\"bi bi-info-circle me-1\"></i> Visualização estritamente de consulta. Para qualquer actualização dos seus dados pessoais ou de filiação, dirija-se à Secretaria da Escola.\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n",
  "painel-aluno/material-escolar": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ALUNO | Material Escolar da Minha Classe -->\n<!-- Página independente do módulo: material-escolar.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-material-escolar\" class=\"modulo-view\" style=\"display: none;\">\n        <!-- Cabeçalho do Painel com Ações -->\n        <div class=\"card p-4 mb-4 border-0 shadow-sm text-white\" style=\"background: linear-gradient(135deg, #1e3a8a 0%, #2563eb 100%);\">\n          <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3\">\n            <div>\n              <h4 class=\"fw-bold mb-1\"><i class=\"bi bi-book-half me-2\"></i>Material Escolar & Recursos Didáticos</h4>\n              <p class=\"mb-0 text-white-50 small\">\n                Navegue pelas classes de 1ª a 12ª Classe, consulte, descarregue manuais oficiais ou carregue novos ficheiros e livros da instituição.\n              </p>\n            </div>\n            <div class=\"d-flex gap-2\">\n              <button class=\"btn btn-light fw-bold text-primary shadow-sm\" onclick=\"modalCarregarMaterialEscolar()\" id=\"btnCarregarMaterial\">\n                <i class=\"bi bi-cloud-arrow-up-fill me-1\"></i> Carregar / Importar Material\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- Barra Unificada de Filtros de Materiais Escolares (Sem excesso de botões) -->\n        <div class=\"card p-3 mb-4 shadow-sm border-0\">\n          <div class=\"row g-2 align-items-end\">\n            <div class=\"col-md-3 col-sm-6\">\n              <label class=\"form-label small fw-bold text-muted mb-1\">\n                <i class=\"bi bi-mortarboard-fill me-1 text-primary\"></i> 1. Classe / Grau:\n              </label>\n              <select id=\"filtroMaterialClasseSelect\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"selecionarClasseMaterial(this.value)\">\n                <option value=\"TODAS\">Todas as Classes / Níveis</option>\n              </select>\n            </div>\n            <div class=\"col-md-3 col-sm-6\">\n              <label class=\"form-label small fw-bold text-muted mb-1\">\n                <i class=\"bi bi-tag me-1 text-info\"></i> 2. Tipo de Material:\n              </label>\n              <select id=\"filtroMaterialTipo\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"filtrarMateriaisEscolares()\">\n                <option value=\"\">Todos os Tipos (Manuais, Fichas...)</option>\n                <option value=\"MANUAL\">Livros / Manuais Oficiais</option>\n                <option value=\"FICHA\">Fichas de Exercícios / Avaliação</option>\n                <option value=\"GUIA\">Guias de Correcção / Apoio</option>\n                <option value=\"APOSTILA\">Apostilas & Resumos</option>\n                <option value=\"OUTRO\">Outros Materiais</option>\n              </select>\n            </div>\n            <div class=\"col-md-4 col-sm-8\">\n              <label class=\"form-label small fw-bold text-muted mb-1\">\n                <i class=\"bi bi-search me-1 text-secondary\"></i> 3. Pesquisa:\n              </label>\n              <div class=\"input-group input-group-sm\">\n                <span class=\"input-group-text bg-white\"><i class=\"bi bi-search\"></i></span>\n                <input type=\"text\" id=\"filtroMaterialBusca\" class=\"form-control form-control-sm bg-white\" placeholder=\"Título, disciplina ou descrição...\" oninput=\"filtrarMateriaisEscolares()\">\n                <button class=\"btn btn-outline-secondary\" type=\"button\" onclick=\"document.getElementById('filtroMaterialBusca').value=''; filtrarMateriaisEscolares();\" title=\"Limpar pesquisa\">&times;</button>\n              </div>\n            </div>\n            <div class=\"col-md-2 col-sm-4 text-end\">\n              <div id=\"containerBotoesClassesMateriais\" style=\"display: none;\"></div>\n              <span class=\"badge bg-primary-subtle text-primary fw-semibold d-block text-truncate mb-1\" id=\"badgeClasseAtiva\">Todas as Classes</span>\n              <small class=\"text-muted d-block\" id=\"contadorMateriaisEncontrados\">0 materiais</small>\n            </div>\n          </div>\n        </div>\n\n        <!-- Lista / Grelha de Materiais da Classe -->\n        <div class=\"row g-4\" id=\"grelhaMateriaisEscolares\">\n          <div class=\"col-12 text-center py-5 text-muted\">\n            <i class=\"bi bi-folder2-open display-4 d-block mb-3 opacity-50\"></i>\n            A carregar materiais da classe...\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/acessos": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Auditoria de Acessos da Escola -->\n<!-- Página independente do módulo: acessos.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-acessos\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2\">\n            <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-shield-check me-2\"></i>Auditoria de Acessos e Logs de Segurança</h5>\n            <div class=\"btn-group btn-group-sm\">\n              <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarAcessosPdf()\" title=\"Exportar logs em PDF\">\n                <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n              </button>\n              <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarAcessosExcel()\" title=\"Exportar logs em Excel\">\n                <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n              </button>\n              <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarAcessosWord()\" title=\"Exportar logs em Word\">\n                <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n              </button>\n            </div>\n          </div>\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Data/Hora</th>\n                  <th>Utilizador</th>\n                  <th>Endereço IP</th>\n                  <th>Navegador / Dispositivo</th>\n                  <th>Evento de Segurança</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaLogsAcesso\">\n                <tr><td colspan=\"5\" class=\"text-center py-4\">A carregar logs...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/alunos": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Alunos & Matrículas -->\n<!-- Página independente do módulo: alunos.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-alunos\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-3 mb-4\">\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Total de Alunos</span>\n                <h4 id=\"alunoTotalCard\" class=\"fw-bold mb-0\">0</h4>\n              </div>\n              <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\"><i class=\"bi bi-people\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Taxa de Retenção</span>\n                <h4 id=\"alunoRetencaoCard\" class=\"fw-bold mb-0 text-success\">100%</h4>\n              </div>\n              <div class=\"stat-icon bg-success bg-opacity-10 text-success\"><i class=\"bi bi-check2-all\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Taxa de Evasão</span>\n                <h4 id=\"alunoEvasaoCard\" class=\"fw-bold mb-0 text-danger\">0%</h4>\n              </div>\n              <div class=\"stat-icon bg-danger bg-opacity-10 text-danger\"><i class=\"bi bi-door-open-fill\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Masculino / Feminino</span>\n                <h4 id=\"alunoGeneroRatioCard\" class=\"fw-bold mb-0 text-info\">0 / 0</h4>\n              </div>\n              <div class=\"stat-icon bg-info bg-opacity-10 text-info\"><i class=\"bi bi-gender-ambiguous\"></i></div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card p-4 mb-3 border-0 shadow-sm\">\n          <!-- Cabeçalho com Título e Botão Novo Aluno -->\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3\">\n            <div>\n              <h5 class=\"fw-bold text-primary mb-1\"><i class=\"bi bi-diagram-3-fill me-2\"></i>Gestão de Alunos & Matrículas Oficiais</h5>\n              <p class=\"text-muted small mb-0\">Selecione os filtros: <strong>Classe</strong> &rarr; <strong>Secção / Área</strong> &rarr; <strong>Turma</strong> para listar os alunos</p>\n            </div>\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\n              <div class=\"sige-seletor-ano-box d-flex align-items-center\" title=\"Filtrar dados pelo Ano Lectivo (actual ou findos)\">\n                <select id=\"filtroAnoAlunos\" class=\"form-select form-select-sm sige-select-ano-lectivo\" onchange=\"aoClicarBuscarAlunosPorAno()\">\n                  <option value=\"\">-- Escolha ano Lectivo --</option>\n                </select>\n                <button type=\"button\" class=\"btn btn-sm btn-sige-buscar-ano\" onclick=\"aoClicarBuscarAlunosPorAno()\">\n                  Buscar <i class=\"bi bi-search ms-1\"></i>\n                </button>\n              </div>\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarAlunosPdf()\" title=\"Exportar lista de alunos em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarAlunosExcel()\" title=\"Exportar lista de alunos em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarAlunosWord()\" title=\"Exportar lista de alunos em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-outline-primary btn-sm\" onclick=\"carregarAlunos()\"><i class=\"bi bi-arrow-clockwise me-1\"></i> Actualizar</button>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"modalNovoAluno()\"><i class=\"bi bi-plus-lg me-1\"></i> Matricular Aluno</button>\n            </div>\n          </div>\n\n          <!-- Barra de Filtros Hierárquicos Compacta, Moderna e Sem Excesso de Botões -->\n          <div class=\"p-3 bg-light rounded-3 border\">\n            <div class=\"row g-2 align-items-end\">\n              <!-- Filtro 1: Classe -->\n              <div class=\"col-lg-3 col-md-6\">\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\n                  <span><i class=\"bi bi-mortarboard-fill me-1 text-primary\"></i> 1. Classe / Grau:</span>\n                  <span id=\"contagemClassesAlunos\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\n                </label>\n                <select id=\"selectFiltroAlunoClasse\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"aoMudarSelectClasseAlunos(this.value)\">\n                  <option value=\"TODAS\">Todas as Classes</option>\n                </select>\n              </div>\n\n              <!-- Filtro 2: Secção / Área -->\n              <div class=\"col-lg-3 col-md-6\">\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\n                  <span><i class=\"bi bi-diagram-2-fill me-1\" style=\"color: #7c3aed;\"></i> 2. Secção / Área:</span>\n                  <span id=\"contagemAreasClasse\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\n                </label>\n                <select id=\"selectFiltroAlunoArea\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"aoMudarSelectAreaAlunos(this.value)\">\n                  <option value=\"TODAS\">Todas as Secções / Áreas</option>\n                </select>\n              </div>\n\n              <!-- Filtro 3: Turma da Secção -->\n              <div class=\"col-lg-3 col-md-6\">\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\n                  <span><i class=\"bi bi-collection-fill me-1 text-info\"></i> 3. Turma da Secção:</span>\n                  <span id=\"contagemTurmasClasse\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\n                </label>\n                <select id=\"selectFiltroAlunoTurma\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"aoMudarSelectTurmaAlunos(this.value)\">\n                  <option value=\"TODAS\">Todas as Turmas da Área</option>\n                </select>\n              </div>\n\n              <!-- Filtro 4: Pesquisa Rápida -->\n              <div class=\"col-lg-3 col-md-6\">\n                <label class=\"form-label small fw-bold text-muted mb-1\">\n                  <i class=\"bi bi-search me-1 text-secondary\"></i> Pesquisa Rápida:\n                </label>\n                <div class=\"input-group input-group-sm\">\n                  <input type=\"search\" id=\"pesquisaAlunosHierarquia\" class=\"form-control form-control-sm bg-white\" placeholder=\"Nome, apelido ou matrícula...\" oninput=\"filtrarAlunosHierarquia()\">\n                  <button class=\"btn btn-outline-secondary\" type=\"button\" onclick=\"document.getElementById('pesquisaAlunosHierarquia').value=''; filtrarAlunosHierarquia();\" title=\"Limpar pesquisa\">&times;</button>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Barra de Informação da Selecção Activa -->\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 mt-3 pt-2 border-top\">\n            <div class=\"d-flex align-items-center gap-2 flex-wrap\">\n              <span class=\"badge bg-primary fs-6 px-3 py-2 shadow-sm\" id=\"badgeCaminhoHierarquia\">\n                <i class=\"bi bi-people-fill me-1\"></i> Todos os Alunos\n              </span>\n              <span id=\"contagemAlunosExibidos\" class=\"text-muted small fw-semibold\"></span>\n            </div>\n            <div class=\"small text-muted d-flex align-items-center gap-2\">\n              <button class=\"btn btn-link btn-sm text-decoration-none text-muted p-0\" onclick=\"limparFiltrosAlunos()\"><i class=\"bi bi-x-circle me-1\"></i> Repor Filtros</button>\n            </div>\n          </div>\n        </div>\n\n        <!-- Tabela de Alunos da Turma Selecionada -->\n        <div class=\"card p-3 border-0 shadow-sm\">\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle mb-0\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th style=\"width: 50px;\">Nº</th>\n                  <th>Matrícula</th>\n                  <th>Nome Completo & Apelido</th>\n                  <th>Classe / Grau</th>\n                  <th>Secção / Área</th>\n                  <th>Turma</th>\n                  <th>Documento</th>\n                  <th>Género</th>\n                  <th>Contacto Encarregado</th>\n                  <th>Estado</th>\n                  <th class=\"text-end\">Acções</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaAlunos\">\n                <tr><td colspan=\"11\" class=\"text-center py-4 text-muted\">A carregar dados...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/caderneta": "<!-- ===================================================================== -->\r\n<!-- SIGE - PAINEL-ESCOLA | Caderneta do Professor -->\r\n<!-- Página independente do módulo: caderneta.html -->\r\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\r\n<!-- ===================================================================== -->\r\n      <section id=\"view-caderneta\" class=\"modulo-view\" style=\"display: none;\">\r\n        <!-- Card de Navegação Sequencial: Classe -> Secção/Área -> Caderneta -->\r\n        <div class=\"card p-4 mb-3 no-print border-0 shadow-sm\">\r\n          <!-- Cabeçalho com Título, Seletor de Professor (para Admins) e Botões de Exportação -->\r\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3\">\r\n            <div>\r\n              <div class=\"d-flex align-items-center gap-2 mb-1\">\r\n                <span class=\"badge bg-primary-subtle text-primary border border-primary-subtle px-2 py-1\"><i class=\"bi bi-journal-bookmark-fill me-1\"></i> Registo de Avaliações Oficiais</span>\r\n                <span id=\"cadernetaBadgePerfil\" class=\"badge bg-light text-dark border\">Caderneta Oficial MEC</span>\r\n              </div>\r\n              <h5 class=\"fw-bold text-dark mb-0\"><i class=\"bi bi-book-half me-2 text-primary\"></i>Caderneta Escolar & Mapa de Avaliação Contínua</h5>\r\n              <p class=\"text-muted small mb-0\">Navegue sequencialmente: <strong>Classe</strong> &rarr; <strong>Secção / Área</strong> &rarr; <strong>Turma da Secção</strong></p>\r\n            </div>\r\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\r\n              <!-- Filtro de Professor visível APENAS para Admins / Direcção -->\r\n              <div id=\"wrapperFiltroProfessorCaderneta\" style=\"display: none;\">\r\n                <div class=\"input-group input-group-sm\" style=\"width: 250px;\">\r\n                  <span class=\"input-group-text bg-light text-muted small\"><i class=\"bi bi-person-badge\"></i></span>\r\n                  <select id=\"cadernetaFiltroProfessor\" class=\"form-select form-select-sm\" onchange=\"aoMudarFiltroProfessorCaderneta(this.value)\">\r\n                    <option value=\"TODOS\">Todos os Professores</option>\r\n                  </select>\r\n                </div>\r\n              </div>\r\n              <button class=\"btn btn-primary btn-sm fw-bold shadow-sm\" onclick=\"modalSalvarNotaCaderneta()\" title=\"Lançar notas de alunos\">\r\n                <i class=\"bi bi-pencil-square me-1\"></i> Lançar Avaliações\r\n              </button>\r\n              <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarCadernetaExcel()\" title=\"Descarregar ficheiro XLSX\">\r\n                <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\r\n              </button>\r\n              <button class=\"btn btn-outline-danger btn-sm\" onclick=\"descarregarCadernetaPdf()\" title=\"Descarregar documento em PDF\">\r\n                <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\r\n              </button>\r\n              <button class=\"btn btn-outline-secondary btn-sm\" onclick=\"imprimirCadernetaOficial()\" title=\"Imprimir em A4 horizontal\">\r\n                <i class=\"bi bi-printer\"></i>\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Barra Unificada de Filtros Inteligentes da Caderneta (Sem excesso de botões) -->\r\n          <div class=\"p-3 bg-light rounded-3 border mb-3\">\r\n            <div class=\"row g-2 align-items-end\">\r\n              <!-- Filtro 1: Classe -->\r\n              <div class=\"col-lg-3 col-md-6\">\r\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\r\n                  <span><i class=\"bi bi-mortarboard-fill me-1 text-primary\"></i> 1. Classe / Grau:</span>\r\n                  <span id=\"contagemClassesCaderneta\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\r\n                </label>\r\n                <select id=\"selectCadernetaClasse\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"aoMudarSelectClasseCaderneta(this.value)\">\r\n                  <!-- Opções de Classes geradas via JS -->\r\n                </select>\r\n              </div>\r\n\r\n              <!-- Filtro 2: Secção / Área -->\r\n              <div class=\"col-lg-3 col-md-6\">\r\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\r\n                  <span><i class=\"bi bi-diagram-2-fill me-1\" style=\"color: #7c3aed;\"></i> 2. Secção / Área:</span>\r\n                  <span id=\"contagemAreasCaderneta\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\r\n                </label>\r\n                <select id=\"selectCadernetaArea\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"aoMudarSelectAreaCaderneta(this.value)\">\r\n                  <!-- Opções de Áreas geradas via JS -->\r\n                </select>\r\n              </div>\r\n\r\n              <!-- Filtro 3: Turma da Secção (Caderneta) -->\r\n              <div class=\"col-lg-3 col-md-6\">\r\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\r\n                  <span><i class=\"bi bi-collection-fill me-1 text-success\"></i> 3. Turma da Secção:</span>\r\n                  <span id=\"contagemTurmasCaderneta\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\r\n                </label>\r\n                <select id=\"selectCadernetaAlocacao\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"aoMudarSelectAlocacaoCaderneta(this.value)\">\r\n                  <!-- Opções de Turmas / Cadernetas geradas via JS -->\r\n                </select>\r\n              </div>\r\n\r\n              <!-- Filtro 4: Trimestre -->\r\n              <div class=\"col-lg-3 col-md-6\">\r\n                <label class=\"form-label small fw-bold text-muted mb-1\">\r\n                  <i class=\"bi bi-calendar3 me-1 text-secondary\"></i> 4. Trimestre:\r\n                </label>\r\n                <select id=\"cadernetaPeriodoSelect\" class=\"form-select form-select-sm bg-white fw-semibold shadow-sm\" onchange=\"destacarTrimestreTabelaCaderneta(this.value)\">\r\n                  <option value=\"TODOS\">Todos os 3 Trimestres</option>\r\n                  <option value=\"1_TRIMESTRE\">1º Trimestre</option>\r\n                  <option value=\"2_TRIMESTRE\">2º Trimestre</option>\r\n                  <option value=\"3_TRIMESTRE\">3º Trimestre</option>\r\n                </select>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Lista Visual de Turmas da Secção: turma por turma para abrir ou visualizar a caderneta ao clicar -->\r\n            <div id=\"containerBotoesTurmasCadernetaWrapper\" class=\"mt-2 pt-2 border-top d-flex align-items-center flex-wrap gap-2\" style=\"display: none !important;\">\r\n              <span class=\"small fw-bold text-muted me-1\"><i class=\"bi bi-collection-play me-1 text-primary\"></i>Turmas da Secção:</span>\r\n              <div id=\"containerBotoesTurmasCaderneta\" class=\"d-inline-flex flex-wrap gap-2\"></div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Barra de Pesquisa Rápida na Caderneta Aberta -->\r\n          <div class=\"row g-2 align-items-center pt-1 border-top\">\r\n            <div class=\"col-md-7\">\r\n              <div class=\"input-group input-group-sm\">\r\n                <span class=\"input-group-text py-1 px-2 bg-white\"><i class=\"bi bi-search\"></i></span>\r\n                <input type=\"search\" id=\"cadernetaPesquisaAluno\" class=\"form-control\" placeholder=\"Pesquisar aluno por nome ou número nesta caderneta...\" oninput=\"filtrarAlunosCaderneta()\">\r\n                <button class=\"btn btn-outline-secondary\" type=\"button\" onclick=\"document.getElementById('cadernetaPesquisaAluno').value=''; filtrarAlunosCaderneta();\">&times;</button>\r\n              </div>\r\n            </div>\r\n            <div class=\"col-md-5 text-end\">\r\n              <!-- Selectors e containers ocultos para retrocompatibilidade com scripts legados -->\r\n              <div id=\"containerCadernetaClasses\" style=\"display: none;\"></div>\r\n              <div id=\"seccaoAreasCaderneta\" style=\"display: none;\"><div id=\"containerCadernetaAreas\"></div><span id=\"cadernetaNomeClasseSelecionada\"></span></div>\r\n              <div id=\"seccaoCadernetasDisponiveis\" style=\"display: none;\"><div id=\"containerCadernetasBotoes\"></div><span id=\"cadernetaNomeAreaSelecionada\"></span></div>\r\n              <select id=\"cadernetaAlocacaoSelect\" style=\"display: none;\"></select>\r\n              <select id=\"cadernetaClasseFilter\" style=\"display: none;\"></select>\r\n              <small class=\"text-muted fw-semibold\" id=\"cadernetaInfoResumo\"></small>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Aviso de Bloqueio do Trimestre -->\r\n          <div id=\"avisoTrimestreBloqueado\" class=\"alert alert-warning mt-3 mb-0 d-none\" role=\"alert\">\r\n            <i class=\"bi bi-lock-fill me-2\"></i>\r\n            <strong>Trimestre Encerrado:</strong> Este trimestre lectivo encontra-se fechado para edição directa. Contacte a Direcção da Escola ou DAP para solicitar autorização de desbloqueio.\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"card p-4 printable-document\" id=\"cadernetaPrintContainer\">\r\n          <!-- Cabeçalho Institucional Oficial (Imagem 2) -->\r\n          <div class=\"border p-3 rounded mb-3 bg-white\" id=\"cadernetaCabecalhoOficial\">\r\n            <div class=\"text-center mb-3\">\r\n              <h6 class=\"fw-bold mb-0 text-uppercase\" id=\"cadHeaderEscola\">REPÚBLICA DE MOÇAMBIQUE</h6>\r\n              <small class=\"text-muted d-block\" id=\"cadHeaderSub\">PROVÍNCIA DE MAPUTO | DISTRITO DE CIDADE DE MAPUTO</small>\r\n              <h5 class=\"fw-bold text-primary mt-1 mb-0\">Mapa de Registo de Avaliações — <span id=\"cadHeaderAno\">2026</span></h5>\r\n            </div>\r\n            <div class=\"row g-2 text-center\" style=\"font-size: 0.8rem;\">\r\n              <div class=\"col-md-3\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Disciplina Lecionada</span>\r\n                  <strong id=\"cadBoxDisciplina\" class=\"text-primary\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-3\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Nome do Professor</span>\r\n                  <strong id=\"cadBoxProfessor\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-3\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Contacto(s) do Prof.</span>\r\n                  <strong id=\"cadBoxContacto\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-3\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Área de Formação</span>\r\n                  <strong id=\"cadBoxArea\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-4\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Turma & Director de Turma</span>\r\n                  <strong id=\"cadBoxTurmaDirector\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-4\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Classe & Turno</span>\r\n                  <strong id=\"cadBoxClasseTurno\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-4\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Efectivo de Alunos</span>\r\n                  <strong id=\"cadBoxEfectivo\" class=\"text-success\">H: 0 | M: 0 | Total: 0</strong>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Tabela Completa da Caderneta com 3 Trimestres e Estatísticas por Coluna (Imagem 2) -->\r\n          <div class=\"table-responsive\">\r\n            <table class=\"table table-bordered table-hover align-middle text-center small caderneta-tabela\" style=\"min-width: 1300px;\">\r\n              <thead class=\"table-light\">\r\n                <tr>\r\n                  <th rowspan=\"2\" class=\"align-middle\" style=\"width: 35px;\">Nº</th>\r\n                  <th rowspan=\"2\" class=\"align-middle text-start\" style=\"min-width: 140px;\">Nome do Aluno</th>\r\n                  <th rowspan=\"2\" class=\"align-middle text-start\" style=\"min-width: 80px;\">Apelido</th>\r\n                  <th rowspan=\"2\" class=\"align-middle\" style=\"width: 35px;\">Gên</th>\r\n                  <th colspan=\"9\" class=\"bg-primary bg-opacity-10 text-primary fw-bold\">1º TRIMESTRE</th>\r\n                  <th colspan=\"9\" class=\"bg-info bg-opacity-10 text-info fw-bold\">2º TRIMESTRE</th>\r\n                  <th colspan=\"9\" class=\"bg-warning bg-opacity-10 text-dark fw-bold\">3º TRIMESTRE</th>\r\n                  <th rowspan=\"2\" class=\"align-middle bg-success bg-opacity-10 text-success fw-bold\" style=\"width: 55px;\">MFD</th>\r\n                </tr>\r\n                <tr>\r\n                  <!-- 1º Trimestre -->\r\n                  <th style=\"font-size: 0.68rem;\">1ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">2ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">3ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAP</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAS</th>\r\n                  <th style=\"font-size: 0.68rem;\">AT</th>\r\n                  <th style=\"font-size: 0.68rem;\" class=\"bg-light fw-bold\">MT</th>\r\n                  <th style=\"font-size: 0.68rem;\">COM</th>\r\n                  <th style=\"font-size: 0.68rem;\">Obs</th>\r\n                  <!-- 2º Trimestre -->\r\n                  <th style=\"font-size: 0.68rem;\">1ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">2ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">3ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAP</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAS</th>\r\n                  <th style=\"font-size: 0.68rem;\">AT</th>\r\n                  <th style=\"font-size: 0.68rem;\" class=\"bg-light fw-bold\">MT</th>\r\n                  <th style=\"font-size: 0.68rem;\">COM</th>\r\n                  <th style=\"font-size: 0.68rem;\">Obs</th>\r\n                  <!-- 3º Trimestre -->\r\n                  <th style=\"font-size: 0.68rem;\">1ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">2ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">3ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAP</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAS</th>\r\n                  <th style=\"font-size: 0.68rem;\">AT</th>\r\n                  <th style=\"font-size: 0.68rem;\" class=\"bg-light fw-bold\">MT</th>\r\n                  <th style=\"font-size: 0.68rem;\">COM</th>\r\n                  <th style=\"font-size: 0.68rem;\">Obs</th>\r\n                </tr>\r\n              </thead>\r\n              <tbody id=\"tabelaCadernetaCorpo\">\r\n                <tr><td colspan=\"32\" class=\"text-center py-4\">Selecione uma turma e disciplina para visualizar a Caderneta Oficial.</td></tr>\r\n              </tbody>\r\n              <tfoot id=\"tabelaCadernetaRodape\" class=\"table-light fw-semibold\" style=\"font-size: 0.72rem;\">\r\n                <!-- Linhas calculadas dinamicamente com estatística por coluna -->\r\n              </tfoot>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </section>\r\n",
  "painel-escola/certificados": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Certificados Oficiais com QR Code -->\n<!-- Página independente do módulo: certificados.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-certificados\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4 mb-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3\">\n            <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-award me-2\"></i>Emissão de Certificados com Autenticação Digital QR Code</h5>\n            <button class=\"btn btn-primary btn-sm\" onclick=\"modalEmitirCertificado()\"><i class=\"bi bi-patch-check me-1\"></i> Emitir Novo Certificado</button>\n          </div>\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Código de Autenticidade</th>\n                  <th>Aluno</th>\n                  <th>Tipo de Certificado</th>\n                  <th>Data de Emissão</th>\n                  <th>QR Code</th>\n                  <th class=\"text-end\">Validação Pública</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaCertificados\">\n                <tr><td colspan=\"6\" class=\"text-center py-4\">A carregar certificados...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/dashboard": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Painel Principal da Escola -->\n<!-- Página independente do módulo: dashboard.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-dashboard\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-3 mb-4\">\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Total de Alunos</span>\n                <h3 id=\"statTotalAlunos\" class=\"fw-bold mb-0 text-dark\">0</h3>\n                <small class=\"text-success fw-medium\"><span id=\"statAlunosAtivos\">0</span> matriculados</small>\n              </div>\n              <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\">\n                <i class=\"bi bi-people-fill\"></i>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Corpo Docente</span>\n                <h3 id=\"statTotalProfessores\" class=\"fw-bold mb-0 text-dark\">0</h3>\n                <small class=\"text-muted\">Professores activos</small>\n              </div>\n              <div class=\"stat-icon bg-info bg-opacity-10 text-info\">\n                <i class=\"bi bi-person-badge-fill\"></i>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Receita Arrecadada</span>\n                <h3 id=\"statReceitaTotal\" class=\"fw-bold mb-0 text-success\">0 <span class=\"moeda-sufixo\">MZN</span></h3>\n                <small class=\"text-danger fw-medium\"><span id=\"statReceitaPendente\">0 <span class=\"moeda-sufixo\">MZN</span></span> pendente</small>\n              </div>\n              <div class=\"stat-icon bg-success bg-opacity-10 text-success\">\n                <i class=\"bi bi-cash-coin\"></i>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Validade do Contrato</span>\n                <h3 id=\"statDiasRestantes\" class=\"fw-bold mb-0 text-primary\">0 dias</h3>\n                <small id=\"statStatusAssinatura\" class=\"badge badge-ativa\">ATIVA</small>\n              </div>\n              <div class=\"stat-icon bg-warning bg-opacity-10 text-warning\">\n                <i class=\"bi bi-shield-lock-fill\"></i>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Banner de Atalhos Rápidos da Instituição e Logótipo -->\n        <div class=\"card p-3 mb-4 border-0 shadow-sm bg-primary-subtle escola-admin-only\">\n          <div class=\"d-flex flex-wrap align-items-center justify-content-between gap-3\">\n            <div class=\"d-flex align-items-center gap-3\">\n              <div class=\"bg-primary text-white rounded p-2 fs-4\">\n                <i class=\"bi bi-image\"></i>\n              </div>\n              <div>\n                <h6 class=\"fw-bold mb-0 text-primary-emphasis\">Identidade Visual & Logótipo Oficial da Instituição</h6>\n                <small class=\"text-secondary\">Carregue o logótipo da escola ou active o Emblema Nacional para os cabeçalhos de pautas, cadernetas, boletins e certificados.</small>\n              </div>\n            </div>\n            <div>\n              <button class=\"btn btn-primary btn-sm fw-bold px-3 shadow-sm\" onclick=\"navegarPara('escola')\">\n                <i class=\"bi bi-gear-fill me-1\"></i> Carregar / Gerir Logótipo\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"row g-4\">\n          <div class=\"col-lg-8\">\n            <div class=\"card p-3\">\n              <h6 class=\"fw-bold mb-3\"><i class=\"bi bi-graph-up me-2 text-primary\"></i>Receitas Arrecadadas vs. Propinas Pendentes (MZN)</h6>\n              <canvas id=\"chartDashboardFaturamento\" height=\"120\"></canvas>\n            </div>\n          </div>\n          <div class=\"col-lg-4\">\n            <div class=\"card p-3\">\n              <h6 class=\"fw-bold mb-3\"><i class=\"bi bi-pie-chart-fill me-2 text-primary\"></i>Distribuição por Género</h6>\n              <canvas id=\"chartDashboardGenero\" height=\"240\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/desbloqueio": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Desbloqueio de Trimestre -->\n<!-- Página independente do módulo: desbloqueio.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-desbloqueio\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-4\">\n          <!-- CARD 1: CALENDÁRIO OFICIAL DE PRAZOS POR TRIMESTRE -->\n          <div class=\"col-lg-6\">\n            <div class=\"card p-4 h-100 shadow-sm border-0\">\n              <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                <h5 class=\"fw-bold mb-0 text-primary\"><i class=\"bi bi-calendar-week me-2\"></i>Calendário Oficial de Prazos de Lançamento</h5>\n                <span id=\"badgeModoAtivo\" class=\"badge bg-primary\">Modo: Manual</span>\n              </div>\n              <p class=\"text-muted small mb-3\">Defina as regras e datas limites de lançamento de notas. Professores que tentarem lançar notas fora destas datas serão bloqueados por atraso ou período futuro, excepto com autorização expressa.</p>\n\n              <form id=\"formPrazosTrimestrais\" class=\"row g-3\">\n                <!-- Seletor do Modo de Calendarização -->\n                <div class=\"col-12 p-3 bg-white rounded border border-primary border-opacity-25\">\n                  <label class=\"form-label small fw-bold text-dark\"><i class=\"bi bi-gear-fill text-primary me-1\"></i>Regra de Calendarização</label>\n                  <select id=\"prazoModoSelect\" class=\"form-select form-select-sm fw-semibold\" onchange=\"alternarModoCalendarizacaoUI(this.value)\">\n                    <option value=\"MANUAL\">1. Manual: Datas explícitas de Início e Fim por Trimestre</option>\n                    <option value=\"AUTOMATICO\">2. Automático: Duração em Dias, Semanas ou Meses (Campo Único)</option>\n                    <option value=\"SEMPRE\">3. Permitir Sempre: Sem bloqueio por calendário (Lançamento Livre)</option>\n                  </select>\n                </div>\n\n                <!-- Painel Exclusivo para o Modo Automático / Campo Único -->\n                <div id=\"painelCalendarizacaoAutomatica\" class=\"col-12 p-3 bg-light rounded border\" style=\"display: none;\">\n                  <span class=\"badge bg-success mb-2\"><i class=\"bi bi-lightning-charge me-1\"></i>Parâmetros de Cálculo Automático</span>\n                  <div class=\"row g-2\">\n                    <div class=\"col-md-6\">\n                      <label class=\"form-label small fw-semibold\">Data Base Inicial (A partir de)</label>\n                      <input type=\"date\" id=\"prazoDataBase\" class=\"form-control form-control-sm\">\n                      <small class=\"text-muted\" style=\"font-size: 0.72rem;\">Início do ano lectivo ou trimestre</small>\n                    </div>\n                    <div class=\"col-md-3\">\n                      <label class=\"form-label small fw-semibold\">Duração</label>\n                      <input type=\"number\" id=\"prazoValorDuracao\" class=\"form-control form-control-sm\" value=\"4\" min=\"1\" max=\"365\">\n                    </div>\n                    <div class=\"col-md-3\">\n                      <label class=\"form-label small fw-semibold\">Unidade</label>\n                      <select id=\"prazoTipoDuracao\" class=\"form-select form-select-sm\">\n                        <option value=\"DIAS\">Dias</option>\n                        <option value=\"SEMANAS\" selected>Semanas</option>\n                        <option value=\"MESES\">Meses</option>\n                      </select>\n                    </div>\n                    <div class=\"col-12 text-end mt-2\">\n                      <button type=\"button\" class=\"btn btn-outline-success btn-sm fw-semibold\" onclick=\"calcularPrazosAutomaticosUI()\">\n                        <i class=\"bi bi-calculator me-1\"></i> Calcular e Visualizar Prazos\n                      </button>\n                    </div>\n                  </div>\n                </div>\n\n                <!-- Painel Informativo para o Modo Permitir Sempre -->\n                <div id=\"painelCalendarizacaoSempre\" class=\"col-12 p-3 bg-success bg-opacity-10 rounded border border-success\" style=\"display: none;\">\n                  <div class=\"d-flex align-items-center gap-2 text-success\">\n                    <i class=\"bi bi-check-circle-fill fs-5\"></i>\n                    <div>\n                      <strong class=\"d-block small\">Modo \"Permitir Sempre\" Selecionado</strong>\n                      <span class=\"small text-muted\">Todos os docentes e secretarias poderão lançar e editar avaliações na caderneta livremente sem restrições de datas ou bloqueios automáticos.</span>\n                    </div>\n                  </div>\n                </div>\n\n                <!-- Bloco de Datas dos Trimestres (Visível em Manual e Automático) -->\n                <div id=\"painelTrimestresDatas\" class=\"col-12 p-0\">\n                  <div class=\"row g-3\">\n                    <!-- 1º Trimestre -->\n                    <div class=\"col-12 p-3 bg-light rounded border\">\n                      <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                        <span class=\"badge bg-primary\">1º Trimestre Lectivo</span>\n                        <div class=\"form-check form-switch small mb-0\">\n                          <input class=\"form-check-input\" type=\"checkbox\" id=\"prazoT1Sempre\">\n                          <label class=\"form-check-label fw-semibold\" for=\"prazoT1Sempre\">Permitir sempre</label>\n                        </div>\n                      </div>\n                      <div class=\"row g-2\">\n                        <div class=\"col-6\">\n                          <label class=\"form-label small fw-semibold\">Data de Início</label>\n                          <input type=\"date\" id=\"prazoT1Inicio\" class=\"form-control form-control-sm\">\n                        </div>\n                        <div class=\"col-6\">\n                          <label class=\"form-label small fw-semibold\">Data Limite (Fim)</label>\n                          <input type=\"date\" id=\"prazoT1Fim\" class=\"form-control form-control-sm\">\n                        </div>\n                        <div class=\"col-12\" id=\"statusT1Msg\"></div>\n                      </div>\n                    </div>\n\n                    <!-- 2º Trimestre -->\n                    <div class=\"col-12 p-3 bg-light rounded border\">\n                      <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                        <span class=\"badge bg-info text-dark\">2º Trimestre Lectivo</span>\n                        <div class=\"form-check form-switch small mb-0\">\n                          <input class=\"form-check-input\" type=\"checkbox\" id=\"prazoT2Sempre\">\n                          <label class=\"form-check-label fw-semibold\" for=\"prazoT2Sempre\">Permitir sempre</label>\n                        </div>\n                      </div>\n                      <div class=\"row g-2\">\n                        <div class=\"col-6\">\n                          <label class=\"form-label small fw-semibold\">Data de Início</label>\n                          <input type=\"date\" id=\"prazoT2Inicio\" class=\"form-control form-control-sm\">\n                        </div>\n                        <div class=\"col-6\">\n                          <label class=\"form-label small fw-semibold\">Data Limite (Fim)</label>\n                          <input type=\"date\" id=\"prazoT2Fim\" class=\"form-control form-control-sm\">\n                        </div>\n                        <div class=\"col-12\" id=\"statusT2Msg\"></div>\n                      </div>\n                    </div>\n\n                    <!-- 3º Trimestre -->\n                    <div class=\"col-12 p-3 bg-light rounded border\">\n                      <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                        <span class=\"badge bg-secondary\">3º Trimestre Lectivo</span>\n                        <div class=\"form-check form-switch small mb-0\">\n                          <input class=\"form-check-input\" type=\"checkbox\" id=\"prazoT3Sempre\">\n                          <label class=\"form-check-label fw-semibold\" for=\"prazoT3Sempre\">Permitir sempre</label>\n                        </div>\n                      </div>\n                      <div class=\"row g-2\">\n                        <div class=\"col-6\">\n                          <label class=\"form-label small fw-semibold\">Data de Início</label>\n                          <input type=\"date\" id=\"prazoT3Inicio\" class=\"form-control form-control-sm\">\n                        </div>\n                        <div class=\"col-6\">\n                          <label class=\"form-label small fw-semibold\">Data Limite (Fim)</label>\n                          <input type=\"date\" id=\"prazoT3Fim\" class=\"form-control form-control-sm\">\n                        </div>\n                        <div class=\"col-12\" id=\"statusT3Msg\"></div>\n                      </div>\n                    </div>\n                  </div>\n                </div>\n\n                <div class=\"col-12 text-end\">\n                  <button type=\"submit\" class=\"btn btn-primary fw-semibold btn-sm\">\n                    <i class=\"bi bi-save me-1\"></i> Guardar Calendário de Prazos\n                  </button>\n                </div>\n              </form>\n            </div>\n          </div>\n\n          <!-- CARD 2: JANELA DE AUTORIZAÇÃO / REDEFINIÇÃO DE PRAZO POR ATRASO -->\n          <div class=\"col-lg-6\">\n            <div class=\"card p-4 h-100 shadow-sm border-0\">\n              <h5 class=\"fw-bold mb-2 text-warning\"><i class=\"bi bi-unlock-fill me-2\"></i>Autorização / Redefinição de Prazo por Atraso</h5>\n              <p class=\"text-muted small mb-3\">Conceda uma janela de autorização temporária ou prorrogação de prazo para que docentes em atraso possam submeter avaliações.</p>\n              \n              <form id=\"formAutorizarDesbloqueio\" class=\"row g-3\">\n                <div class=\"col-12\">\n                  <label class=\"form-label small fw-semibold\">Turma Alvo</label>\n                  <select id=\"desbloqueioTurma\" class=\"form-select\" required></select>\n                </div>\n                <div class=\"col-12\">\n                  <label class=\"form-label small fw-semibold\">Docente Titular (Opcional - Em branco para toda a turma)</label>\n                  <select id=\"desbloqueioProfessor\" class=\"form-select\">\n                    <option value=\"\">(Todos os Docentes da Turma)</option>\n                  </select>\n                </div>\n                <div class=\"col-6\">\n                  <label class=\"form-label small fw-semibold\">Trimestre a Desbloquear</label>\n                  <select id=\"desbloqueioTrimestre\" class=\"form-select\">\n                    <option value=\"1_TRIMESTRE\">1º Trimestre</option>\n                    <option value=\"2_TRIMESTRE\">2º Trimestre</option>\n                    <option value=\"3_TRIMESTRE\">3º Trimestre</option>\n                  </select>\n                </div>\n                <div class=\"col-6\">\n                  <label class=\"form-label small fw-semibold\">Prazo de Validade (Horas)</label>\n                  <input type=\"number\" id=\"desbloqueioHoras\" class=\"form-control\" value=\"48\" min=\"1\" max=\"720\" required>\n                </div>\n                <div class=\"col-12\">\n                  <label class=\"form-label small fw-semibold\">Justificação Administrativa Oficial</label>\n                  <textarea id=\"desbloqueioMotivo\" class=\"form-control\" rows=\"3\" placeholder=\"Ex: Despacho da Direcção Pedagógica autorizando rectificação / lançamento com atraso fundamentado...\" required></textarea>\n                </div>\n                <div class=\"col-12\">\n                  <button type=\"submit\" class=\"btn btn-warning fw-semibold w-100\"><i class=\"bi bi-check2-circle me-1\"></i> Conceder Autorização de Desbloqueio</button>\n                </div>\n              </form>\n            </div>\n          </div>\n\n          <!-- CARD 3: TABELA DE AUTORIZAÇÕES ACTIVAS -->\n          <div class=\"col-12\">\n            <div class=\"card p-4 shadow-sm border-0\">\n              <div class=\"d-flex justify-content-between align-items-center mb-3\">\n                <h6 class=\"fw-bold mb-0\"><i class=\"bi bi-shield-check text-success me-2\"></i>Autorizações de Desbloqueio em Vigor</h6>\n                <button class=\"btn btn-outline-secondary btn-sm\" onclick=\"carregarAutorizacoesDesbloqueio()\"><i class=\"bi bi-arrow-clockwise me-1\"></i> Actualizar</button>\n              </div>\n              <div class=\"table-responsive\">\n                <table class=\"table table-hover align-middle small mb-0\">\n                  <thead class=\"table-light\">\n                    <tr>\n                      <th>Turma</th>\n                      <th>Docente Autorizado</th>\n                      <th>Trimestre</th>\n                      <th>Concedido Por</th>\n                      <th>Data de Concessão</th>\n                      <th>Motivo / Validade</th>\n                      <th>Estado</th>\n                      <th class=\"text-end\">Acção</th>\n                    </tr>\n                  </thead>\n                  <tbody id=\"tabelaAutorizacoesDesbloqueio\">\n                    <tr><td colspan=\"8\" class=\"text-center py-3 text-muted\">A carregar autorizações activas...</td></tr>\n                  </tbody>\n                </table>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/director-turma": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Painel Director de Turma -->\n<!-- Página independente do módulo: director-turma.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-director-turma\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4 no-print mb-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2\">\n            <div>\n              <h5 class=\"fw-bold mb-1\"><i class=\"bi bi-person-workspace text-warning me-2\"></i>Painel Oficial do Director de Turma</h5>\n              <p class=\"text-muted small mb-0\">Gestão académica e administrativa da sua turma atribuída: Pauta Geral e Acta Oficial do Conselho de Avaliação.</p>\n            </div>\n            <div class=\"d-flex align-items-center gap-2\">\n              <label class=\"form-label small fw-bold mb-0 text-nowrap\">Turma Atribuída:</label>\n              <select id=\"dtTurmaSelect\" class=\"form-select form-select-sm\" style=\"min-width: 260px;\" onchange=\"aoSelecionarTurmaDT(this.value)\"></select>\n            </div>\n          </div>\n\n          <!-- Parâmetros da Sessão do Conselho de Avaliação (Acordeão recolhível) -->\n          <div class=\"accordion mb-3\" id=\"accordionParamsConselho\">\n            <div class=\"accordion-item border rounded\">\n              <h2 class=\"accordion-header\" id=\"headingConselho\">\n                <button class=\"accordion-button collapsed py-2 small fw-semibold bg-light\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseConselho\">\n                  <i class=\"bi bi-pencil-square text-primary me-2\"></i> Configurar Dados da Sessão do Conselho de Avaliação (Presidente, Datas e Horários)\n                </button>\n              </h2>\n              <div id=\"collapseConselho\" class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionParamsConselho\">\n                <div class=\"accordion-body p-3 bg-white\">\n                  <form id=\"formParamsConselho\" onsubmit=\"event.preventDefault(); salvarParametrosSessaoDT();\">\n                    <div class=\"row g-3\">\n                      <!-- 1º Trimestre -->\n                      <div class=\"col-md-4 border-end\">\n                        <div class=\"fw-bold text-primary small mb-2\"><i class=\"bi bi-1-circle me-1\"></i> Iº Trimestre</div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Presidente do Conselho</label>\n                          <input type=\"text\" id=\"dtPresidenteT1\" class=\"form-control form-control-sm\" value=\"\" placeholder=\"Deixe em branco até à realização\">\n                        </div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Data da Realização</label>\n                          <input type=\"date\" id=\"dtDataT1\" class=\"form-control form-control-sm\" value=\"\">\n                        </div>\n                        <div class=\"row g-1\">\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Início (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHIni1\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMIni1\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Término (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHFim1\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMFim1\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n\n                      <!-- 2º Trimestre -->\n                      <div class=\"col-md-4 border-end\">\n                        <div class=\"fw-bold text-primary small mb-2\"><i class=\"bi bi-2-circle me-1\"></i> IIº Trimestre</div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Presidente do Conselho</label>\n                          <input type=\"text\" id=\"dtPresidenteT2\" class=\"form-control form-control-sm\" value=\"\" placeholder=\"Deixe em branco até à realização\">\n                        </div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Data da Realização</label>\n                          <input type=\"date\" id=\"dtDataT2\" class=\"form-control form-control-sm\" value=\"\">\n                        </div>\n                        <div class=\"row g-1\">\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Início (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHIni2\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMIni2\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Término (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHFim2\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMFim2\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n\n                      <!-- 3º Trimestre -->\n                      <div class=\"col-md-4\">\n                        <div class=\"fw-bold text-primary small mb-2\"><i class=\"bi bi-3-circle me-1\"></i> IIIº Trimestre</div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Presidente do Conselho</label>\n                          <input type=\"text\" id=\"dtPresidenteT3\" class=\"form-control form-control-sm\" value=\"\" placeholder=\"Deixe em branco até à realização\">\n                        </div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Data da Realização</label>\n                          <input type=\"date\" id=\"dtDataT3\" class=\"form-control form-control-sm\" value=\"\">\n                        </div>\n                        <div class=\"row g-1\">\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Início (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHIni3\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMIni3\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Término (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHFim3\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMFim3\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                    <div class=\"text-end mt-3\">\n                      <button type=\"button\" class=\"btn btn-sm btn-outline-secondary me-2\" onclick=\"limparParametrosSessaoDT()\">\n                        <i class=\"bi bi-eraser me-1\"></i> Limpar / Deixar em Branco\n                      </button>\n                      <button type=\"submit\" class=\"btn btn-sm btn-primary\">\n                        <i class=\"bi bi-save me-1\"></i> Gravar Parâmetros do Conselho\n                      </button>\n                    </div>\n                  </form>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Abas do Director de Turma: Pauta Geral vs Acta do Conselho -->\n          <ul class=\"nav nav-tabs mb-3\">\n            <li class=\"nav-item\">\n              <a class=\"nav-link fw-bold active\" id=\"dtTabPautaBtn\" href=\"#\" onclick=\"alternarAbaDT('pauta')\">\n                <i class=\"bi bi-table me-1\"></i> Pauta Geral da Turma\n              </a>\n            </li>\n            <li class=\"nav-item\">\n              <a class=\"nav-link fw-bold\" id=\"dtTabActaBtn\" href=\"#\" onclick=\"alternarAbaDT('acta')\">\n                <i class=\"bi bi-file-earmark-text me-1\"></i> Acta Oficial do Conselho de Avaliação\n              </a>\n            </li>\n          </ul>\n        </div>\n\n        <!-- Conteúdo do Documento Activo do Director de Turma -->\n        <div class=\"card p-4 printable-document bg-white\" id=\"dtDocumentoContainer\">\n          <div class=\"text-center py-4 text-muted\">Selecione uma turma para visualizar a pauta e acta.</div>\n        </div>\n      </section>\n",
  "painel-escola/disciplinas": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Disciplinas & Currículo -->\n<!-- Página independente do módulo: disciplinas.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-disciplinas\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-4 mb-4\">\n          <div class=\"col-lg-8\">\n            <div class=\"card p-4\">\n              <div class=\"d-flex justify-content-between align-items-center mb-3\">\n                <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-book me-2\"></i>Disciplinas do Plano Curricular Nacional</h5>\n                <div class=\"d-flex gap-2\">\n                  <button class=\"btn btn-outline-success btn-sm\" onclick=\"modalAdicionarNivelCurricular()\" title=\"Adicionar Níveis curriculares para instituições que usam Níveis\"><i class=\"bi bi-layers me-1\"></i> + Adicionar Nível</button>\n                  <button class=\"btn btn-primary btn-sm\" onclick=\"modalNovaDisciplina()\"><i class=\"bi bi-plus-lg me-1\"></i> Nova Disciplina</button>\n                </div>\n              </div>\n\n              <!-- Barra de Filtros Inteligente: Classe, Secção/Área de Estudo e Pesquisa -->\n              <div class=\"card bg-light border p-3 mb-3 shadow-none\">\n                <div class=\"row g-2 align-items-end\">\n                  <div class=\"col-md-4\">\n                    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                      <label class=\"form-label small fw-bold text-uppercase text-secondary mb-0\">\n                        <i class=\"bi bi-mortarboard me-1 text-primary\"></i> 1. Classe / Nível:\n                      </label>\n                      <button class=\"btn btn-link btn-sm p-0 text-success fw-semibold small text-decoration-none\" onclick=\"modalAdicionarNivelCurricular()\" title=\"Adicionar novo nível à instituição\">\n                        <i class=\"bi bi-plus-circle me-1\"></i> + Nível\n                      </button>\n                    </div>\n                    <select id=\"filtroDisciplinasClasseSelect\" class=\"form-select form-select-sm fw-semibold\" onchange=\"filtrarDisciplinasClasse(this.value)\">\n                      <option value=\"\">Todas as Classes / Níveis</option>\n                    </select>\n                  </div>\n                  <div class=\"col-md-5\">\n                    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                      <label class=\"form-label small fw-bold text-uppercase text-secondary mb-0\">\n                        <i class=\"bi bi-diagram-3 me-1 text-primary\"></i> 2. Secção ou Área de Estudo:\n                      </label>\n                      <button class=\"btn btn-link btn-sm p-0 text-primary fw-semibold small text-decoration-none\" onclick=\"modalNovaSeccaoArea()\" title=\"Cadastrar nova secção ou área para a classe selecionada\">\n                        <i class=\"bi bi-plus-circle me-1\"></i> + Nova Secção / Área\n                      </button>\n                    </div>\n                    <select id=\"filtroDisciplinasAreaSelect\" class=\"form-select form-select-sm fw-semibold\" onchange=\"filtrarDisciplinasArea(this.value)\">\n                      <option value=\"\">Todas as Áreas / Secções</option>\n                      <!-- Povoado automaticamente a cada cadastro de secção/área -->\n                    </select>\n                  </div>\n                  <div class=\"col-md-3\">\n                    <label class=\"form-label small fw-bold text-uppercase text-secondary mb-1\">\n                      <i class=\"bi bi-search me-1 text-primary\"></i> Pesquisar Disciplina:\n                    </label>\n                    <input type=\"search\" id=\"filtroDisciplinasBusca\" class=\"form-control form-control-sm\" placeholder=\"Nome ou código...\" oninput=\"filtrarDisciplinasTabelaTexto()\" onsearch=\"filtrarDisciplinasTabelaTexto()\">\n                  </div>\n                </div>\n              </div>\n\n              <div class=\"table-responsive\">\n                <table class=\"table table-hover align-middle\">\n                  <thead class=\"table-light\">\n                    <tr>\n                      <th>Código</th>\n                      <th>Disciplina</th>\n                      <th>Classe</th>\n                      <th>Área</th>\n                      <th>Carga Horária</th>\n                      <th>Ano Lectivo</th>\n                      <th class=\"text-end\">Ações</th>\n                    </tr>\n                  </thead>\n                  <tbody id=\"tabelaDisciplinas\">\n                    <tr><td colspan=\"7\" class=\"text-center py-4\">A carregar disciplinas...</td></tr>\n                  </tbody>\n                </table>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-lg-4\">\n            <div class=\"card p-3\">\n              <h6 class=\"fw-bold mb-3\"><i class=\"bi bi-exclamation-diamond text-danger me-2\"></i>Ranking de Negativas (%)</h6>\n              <canvas id=\"chartDisciplinasReprovacao\" height=\"240\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/escola": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Definições & Logótipo da Escola -->\n<!-- Página independente do módulo: escola.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-escola\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-4\">\n          <div class=\"col-lg-5\">\n            <div class=\"card p-4\">\n              <h5 class=\"fw-bold mb-3\"><i class=\"bi bi-sliders me-2\"></i>Dados da Instituição de Ensino</h5>\n              <form id=\"formEscolaInfo\">\n                <!-- Card de Código Único da Escola e Códigos dos Órgãos Institucionais -->\n                <div class=\"p-3 mb-3 rounded-3 border bg-primary-subtle border-primary-subtle shadow-sm\">\n                  <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                    <span class=\"small fw-bold text-primary text-uppercase\"><i class=\"bi bi-upc-scan me-1\"></i> Código Único Oficial da Escola</span>\n                    <span id=\"confEscolaCodigoBadge\" class=\"badge bg-primary font-monospace fs-6 px-3 py-1\">0101S0001</span>\n                  </div>\n                  <div class=\"row g-2 text-center mt-1\" style=\"font-size: 0.76rem;\">\n                    <div class=\"col-4\">\n                      <div class=\"p-1 bg-white rounded border\">\n                        <small class=\"text-muted d-block\">Gab. Director (GD)</small>\n                        <strong id=\"confCodigoGD\" class=\"font-monospace text-dark\">GD0101S0001</strong>\n                      </div>\n                    </div>\n                    <div class=\"col-4\">\n                      <div class=\"p-1 bg-white rounded border\">\n                        <small class=\"text-muted d-block\">Dir. Pedagógica (DP)</small>\n                        <strong id=\"confCodigoDP\" class=\"font-monospace text-primary\">DP0101S0001</strong>\n                      </div>\n                    </div>\n                    <div class=\"col-4\">\n                      <div class=\"p-1 bg-white rounded border\">\n                        <small class=\"text-muted d-block\">Secretaria (SECR)</small>\n                        <strong id=\"confCodigoSECR\" class=\"font-monospace text-success\">SECR0101S0001</strong>\n                      </div>\n                    </div>\n                  </div>\n                </div>\n\n                <div class=\"row g-2 mb-3\">\n                  <div class=\"col-8\">\n                    <label class=\"form-label small fw-semibold\">Nome da Instituição</label>\n                    <input type=\"text\" id=\"confEscolaNome\" class=\"form-control\" required>\n                  </div>\n                  <div class=\"col-4\">\n                    <label class=\"form-label small fw-semibold\">Nível de Ensino</label>\n                    <select id=\"confEscolaTipo\" class=\"form-select\" onchange=\"atualizarPreviewCodigoEscolaConfig()\">\n                      <option value=\"P\">P - Primária</option>\n                      <option value=\"B\">B - Básica</option>\n                      <option value=\"S\" selected>S - Secundária</option>\n                    </select>\n                  </div>\n                </div>\n                <div class=\"row g-2 mb-3\">\n                  <div class=\"col-6\">\n                    <label class=\"form-label small fw-semibold\">Ano Lectivo Activo</label>\n                    <input type=\"text\" id=\"confEscolaAnoLetivo\" class=\"form-control\" value=\"2026\" required>\n                  </div>\n                  <div class=\"col-6\">\n                    <label class=\"form-label small fw-semibold\">Trimestre Activo</label>\n                    <select id=\"confEscolaTrimestreAtivo\" class=\"form-select\">\n                      <option value=\"1_TRIMESTRE\">1º Trimestre</option>\n                      <option value=\"2_TRIMESTRE\">2º Trimestre</option>\n                      <option value=\"3_TRIMESTRE\">3º Trimestre</option>\n                    </select>\n                  </div>\n                </div>\n                <div class=\"mb-3\">\n                  <label class=\"form-label small fw-semibold\"><i class=\"bi bi-broadcast text-primary me-1\"></i>Publicação / Visualização das Notas dos Alunos</label>\n                  <select id=\"confEscolaPublicacaoNotas\" class=\"form-select form-select-sm\">\n                    <option value=\"TODOS\">Todos os Trimestres (I, II e III)</option>\n                    <option value=\"1_TRIMESTRE\">I Trimestre (Apenas 1º Trimestre)</option>\n                    <option value=\"2_TRIMESTRE\">II Trimestre (2º Trimestre)</option>\n                    <option value=\"3_TRIMESTRE\">III Trimestre (3º Trimestre)</option>\n                    <option value=\"NENHUM\">Ocultar / Suspender Notas no Portal</option>\n                  </select>\n                  <small class=\"text-muted\" style=\"font-size: 0.75rem;\">Controla quais trimestres estão homologados e visíveis para consulta pelos alunos no portal.</small>\n                </div>\n                <div class=\"row g-2 mb-3\">\n                  <div class=\"col-6\">\n                    <label class=\"form-label small fw-semibold\">Província</label>\n                    <select id=\"confEscolaProvincia\" class=\"form-select\" onchange=\"atualizarDistritosEscola(this.value); atualizarPreviewCodigoEscolaConfig();\"></select>\n                  </div>\n                  <div class=\"col-6\">\n                    <label class=\"form-label small fw-semibold\">Distrito</label>\n                    <select id=\"confEscolaDistrito\" class=\"form-select\" onchange=\"atualizarPreviewCodigoEscolaConfig()\"></select>\n                  </div>\n                </div>\n                <div class=\"mb-3\">\n                  <label class=\"form-label small fw-semibold\">Telefone (+258 Padrão)</label>\n                  <input type=\"text\" id=\"confEscolaTelefone\" class=\"form-control\" placeholder=\"+258 84 000 0000\">\n                </div>\n                <div class=\"mb-3\">\n                  <label class=\"form-label small fw-semibold\">E-mail da Secretaria</label>\n                  <input type=\"email\" id=\"confEscolaEmail\" class=\"form-control\" required>\n                </div>\n                <div class=\"mb-3\">\n                  <label class=\"form-label small fw-semibold\">Director da Escola <span class=\"badge bg-dark-subtle text-dark font-monospace ms-1\" id=\"labelBadgeGD\">GD</span></label>\n                  <input type=\"text\" id=\"confEscolaDirector\" class=\"form-control\" placeholder=\"Nome completo do Director\">\n                </div>\n                <div class=\"mb-3\">\n                  <label class=\"form-label small fw-semibold\">Director Adjunto Pedagógico (DAP) <span class=\"badge bg-primary-subtle text-primary font-monospace ms-1\" id=\"labelBadgeDP\">DP</span></label>\n                  <input type=\"text\" id=\"confEscolaDAP\" class=\"form-control\" placeholder=\"Nome do DAP\">\n                </div>\n                <div class=\"mb-3\">\n                  <label class=\"form-label small fw-semibold\">Chefe da Secretaria <span class=\"badge bg-success-subtle text-success font-monospace ms-1\" id=\"labelBadgeSECR\">SECR</span></label>\n                  <input type=\"text\" id=\"confEscolaChefeSec\" class=\"form-control\" placeholder=\"Nome do Chefe da Secretaria\">\n                </div>\n                <div class=\"form-check mb-3\">\n                  <input class=\"form-check-input\" type=\"checkbox\" id=\"confEscolaEmblema\" onchange=\"alternarEmblemaCheck(this.checked)\">\n                  <label class=\"form-check-label small fw-semibold\" for=\"confEscolaEmblema\">\n                    Usar Emblema Nacional Oficial nos cabeçalhos\n                  </label>\n                </div>\n\n                <!-- Secção de Logótipo da Escola (Catálogo de Logótipos & Permutação) -->\n                <div class=\"card border-primary border-opacity-25 bg-light p-3 mb-3 shadow-sm\">\n                  <div class=\"d-flex align-items-center justify-content-between mb-2\">\n                    <label class=\"form-label small fw-bold mb-0 text-primary\">\n                      <i class=\"bi bi-image-fill me-1\"></i> Logótipo Oficial da Instituição\n                    </label>\n                    <span class=\"badge bg-primary-subtle text-primary border border-primary-subtle\" style=\"font-size: 0.72rem;\">Identidade Visual</span>\n                  </div>\n                  <p class=\"x-small text-muted mb-3\" style=\"font-size: 0.8rem;\">\n                    O logótipo activo será automaticamente renderizado com precisão nos cabeçalhos de <strong>Pautas, Cadernetas, Boletins e Certificados</strong> desta escola.\n                  </p>\n\n                  <!-- Logótipo Activo em Uso -->\n                  <div class=\"d-flex align-items-center gap-3 mb-3 p-2 bg-white rounded border border-primary shadow-sm\">\n                    <div id=\"previewLogoContainer\" class=\"border rounded bg-light p-1 text-center d-flex align-items-center justify-content-center shadow-sm\" style=\"width: 76px; height: 76px; overflow: hidden; min-width: 76px;\">\n                      <img id=\"confEscolaLogoPreview\" src=\"img/emblema-mocambique.png\" alt=\"Logótipo\" style=\"max-width: 100%; max-height: 100%; object-fit: contain;\">\n                    </div>\n                    <div class=\"flex-grow-1\">\n                      <div class=\"d-flex align-items-center gap-2 mb-1\">\n                        <span class=\"badge bg-success\" style=\"font-size: 0.7rem;\"><i class=\"bi bi-check-circle-fill me-1\"></i>Activo em Uso</span>\n                        <div class=\"small fw-bold text-dark text-truncate\" id=\"confEscolaLogoStatus\" style=\"max-width: 220px;\">Emblema Nacional (Padrão Oficial)</div>\n                      </div>\n                      <small class=\"text-muted d-block mb-1\" style=\"font-size: 0.75rem;\">Para alternar, clique em qualquer logótipo da galeria abaixo.</small>\n                    </div>\n                  </div>\n\n                  <!-- Galeria / Catálogo de Logótipos Disponíveis -->\n                  <div class=\"mb-3\">\n                    <div class=\"d-flex align-items-center justify-content-between mb-2\">\n                      <span class=\"x-small fw-bold text-dark text-uppercase\" style=\"font-size: 0.75rem;\">\n                        <i class=\"bi bi-grid-fill text-primary me-1\"></i> Logótipos Disponíveis no Sistema:\n                      </span>\n                      <small class=\"text-muted fw-semibold\" id=\"contadorGaleriaLogos\">1 disponível</small>\n                    </div>\n                    <div class=\"alert alert-primary py-1 px-2 mb-2 d-flex align-items-center gap-2\" style=\"font-size: 0.75rem;\">\n                      <i class=\"bi bi-cursor-fill text-primary\"></i>\n                      <span><strong>Clique no logótipo desejado</strong> para trocar imediatamente ou permutar o uso.</span>\n                    </div>\n                    <div id=\"galeriaLogosContainer\" class=\"row g-2 mb-2\" style=\"max-height: 290px; overflow-y: auto;\">\n                      <!-- Itens gerados dinamicamente via JS -->\n                    </div>\n                  </div>\n\n                  <!-- Carregar Novo Logótipo para a Galeria -->\n                  <div class=\"p-2 rounded bg-white border\">\n                    <div class=\"fw-bold text-primary small mb-2 d-flex align-items-center justify-content-between\">\n                      <span><i class=\"bi bi-cloud-arrow-up-fill me-1\"></i> Carregar Novo Logótipo para a Galeria</span>\n                      <span class=\"badge bg-light text-muted border\" style=\"font-size: 0.65rem;\">PNG, JPG, WebP</span>\n                    </div>\n\n                    <!-- 1. Carregar Ficheiro de Imagem do Computador -->\n                    <div class=\"mb-2\">\n                      <label class=\"form-label x-small text-dark mb-1 fw-bold\" style=\"font-size: 0.76rem;\">1. Carregar do Computador</label>\n                      <input type=\"file\" id=\"confEscolaLogoFile\" accept=\"image/*\" class=\"form-control form-control-sm\" onchange=\"processarUploadLogoLocal(this)\">\n                    </div>\n\n                    <!-- 2. Ou Link / URL -->\n                    <div class=\"mb-1\">\n                      <label class=\"form-label x-small text-dark mb-1 fw-bold\" style=\"font-size: 0.76rem;\">2. Ou Insira o Link / URL da Imagem</label>\n                      <div class=\"input-group input-group-sm\">\n                        <input type=\"url\" id=\"confEscolaLogoUrl\" class=\"form-control\" placeholder=\"https://escola.edu.mz/logo.png\">\n                        <button type=\"button\" class=\"btn btn-outline-primary fw-semibold\" onclick=\"processarUrlLogo(document.getElementById('confEscolaLogoUrl').value)\">\n                          <i class=\"bi bi-plus-lg me-1\"></i> Adicionar\n                        </button>\n                      </div>\n                    </div>\n                  </div>\n                  <input type=\"hidden\" id=\"confEscolaLogoFinalValue\" value=\"\">\n                </div>\n\n                <!-- Secção de Tema de Cores da Instituição -->\n                <div class=\"card border-primary border-opacity-25 bg-light p-3 mb-3 shadow-sm\">\n                  <div class=\"d-flex align-items-center justify-content-between mb-2\">\n                    <label class=\"form-label small fw-bold mb-0 text-primary\">\n                      <i class=\"bi bi-palette-fill me-1\"></i> Tema de Cores da Instituição\n                    </label>\n                    <span class=\"badge bg-primary-subtle text-primary border border-primary-subtle\" style=\"font-size: 0.72rem;\">Cores Oficiais</span>\n                  </div>\n                  <p class=\"x-small text-muted mb-2\" style=\"font-size: 0.8rem;\">\n                    Personalize as cores dos botões, menus, cabeçalhos e painéis da sua escola conforme a identidade institucional desejada.\n                  </p>\n\n                  <!-- Grade de Temas Disponíveis -->\n                  <div class=\"row g-2 mb-3\" id=\"gradeTemasDisponiveis\">\n                    <!-- Gerado dinamicamente via JS (Azul SIGE, Índigo Save, Verde Esmeralda, Bordeaux, Âmbar, Grafite, etc.) -->\n                  </div>\n\n                  <!-- Painel de Cores Personalizadas (Expansível quando \"Personalizado\" é selecionado) -->\n                  <div id=\"painelCoresPersonalizadas\" class=\"p-2 rounded bg-white border mb-2\" style=\"display: none;\">\n                    <div class=\"fw-bold text-dark small mb-2 d-flex align-items-center justify-content-between\">\n                      <span><i class=\"bi bi-sliders me-1 text-primary\"></i> Cores Manuais Personalizadas</span>\n                      <small class=\"text-muted\">Formato Hexadecimal</small>\n                    </div>\n                    <div class=\"row g-2\">\n                      <div class=\"col-6\">\n                        <label class=\"form-label x-small text-dark mb-1 fw-bold\" style=\"font-size: 0.74rem;\">Cor Primária</label>\n                        <div class=\"input-group input-group-sm\">\n                          <input type=\"color\" id=\"confEscolaCorPrimaria\" class=\"form-control form-control-color w-25\" value=\"#1e3a8a\" onchange=\"aoMudarCorCustomizada()\">\n                          <input type=\"text\" id=\"confEscolaCorPrimariaHex\" class=\"form-control\" value=\"#1e3a8a\" onchange=\"aoMudarHexColor('confEscolaCorPrimaria', this.value)\">\n                        </div>\n                      </div>\n                      <div class=\"col-6\">\n                        <label class=\"form-label x-small text-dark mb-1 fw-bold\" style=\"font-size: 0.74rem;\">Cor da Barra Lateral</label>\n                        <div class=\"input-group input-group-sm\">\n                          <input type=\"color\" id=\"confEscolaCorSidebar\" class=\"form-control form-control-color w-25\" value=\"#0f172a\" onchange=\"aoMudarCorCustomizada()\">\n                          <input type=\"text\" id=\"confEscolaCorSidebarHex\" class=\"form-control\" value=\"#0f172a\" onchange=\"aoMudarHexColor('confEscolaCorSidebar', this.value)\">\n                        </div>\n                      </div>\n                      <div class=\"col-6\">\n                        <label class=\"form-label x-small text-dark mb-1 fw-bold\" style=\"font-size: 0.74rem;\">Cor de Destaque / Hover</label>\n                        <div class=\"input-group input-group-sm\">\n                          <input type=\"color\" id=\"confEscolaCorHover\" class=\"form-control form-control-color w-25\" value=\"#172554\" onchange=\"aoMudarCorCustomizada()\">\n                          <input type=\"text\" id=\"confEscolaCorHoverHex\" class=\"form-control\" value=\"#172554\" onchange=\"aoMudarHexColor('confEscolaCorHover', this.value)\">\n                        </div>\n                      </div>\n                      <div class=\"col-6\">\n                        <label class=\"form-label x-small text-dark mb-1 fw-bold\" style=\"font-size: 0.74rem;\">Item Activo do Menu</label>\n                        <div class=\"input-group input-group-sm\">\n                          <input type=\"color\" id=\"confEscolaCorSidebarAtiva\" class=\"form-control form-control-color w-25\" value=\"#38bdf8\" onchange=\"aoMudarCorCustomizada()\">\n                          <input type=\"text\" id=\"confEscolaCorSidebarAtivaHex\" class=\"form-control\" value=\"#38bdf8\" onchange=\"aoMudarHexColor('confEscolaCorSidebarAtiva', this.value)\">\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n\n                  <input type=\"hidden\" id=\"confEscolaTemaCodigo\" value=\"padrao_azul\">\n                </div>\n\n                <!-- Secção de Imagem de Fundo & Marca de Água -->\n                <div class=\"card border-primary border-opacity-25 bg-light p-3 mb-3 shadow-sm\">\n                  <div class=\"d-flex align-items-center justify-content-between mb-2\">\n                    <label class=\"form-label small fw-bold mb-0 text-primary\">\n                      <i class=\"bi bi-aspect-ratio-fill me-1\"></i> Imagem de Fundo & Marca de Água\n                    </label>\n                    <span class=\"badge bg-primary-subtle text-primary border border-primary-subtle\" style=\"font-size: 0.72rem;\">Fundo do Sistema</span>\n                  </div>\n                  <p class=\"x-small text-muted mb-3\" style=\"font-size: 0.8rem;\">\n                    Escolha a imagem ou marca de água oficial que deseja exibir no fundo do sistema para a sua instituição escolar.\n                  </p>\n\n                  <!-- Fundo Activo em Uso -->\n                  <div class=\"d-flex align-items-center gap-3 mb-3 p-2 bg-white rounded border border-primary shadow-sm\">\n                    <div id=\"previewFundoContainer\" class=\"border rounded bg-light p-1 text-center d-flex align-items-center justify-content-center shadow-sm\" style=\"width: 76px; height: 76px; overflow: hidden; min-width: 76px;\">\n                      <img id=\"confEscolaFundoPreview\" src=\"img/logo-sige.png\" alt=\"Fundo Activo\" style=\"max-width: 100%; max-height: 100%; object-fit: contain;\">\n                    </div>\n                    <div class=\"flex-grow-1\">\n                      <div class=\"d-flex align-items-center gap-2 mb-1\">\n                        <span class=\"badge bg-success\" style=\"font-size: 0.7rem;\"><i class=\"bi bi-check-circle-fill me-1\"></i>Fundo Activo</span>\n                        <div class=\"small fw-bold text-dark text-truncate\" id=\"confEscolaFundoStatus\" style=\"max-width: 220px;\">Marca d'Água Oficial</div>\n                      </div>\n                      <small class=\"text-muted d-block mb-1\" style=\"font-size: 0.75rem;\" id=\"confEscolaFundoModoTxt\">Modo: Marca de Água Central Sutil</small>\n                      <button type=\"button\" id=\"btnRemoverFundo\" class=\"btn btn-outline-danger btn-sm py-0 px-2\" style=\"font-size: 0.72rem;\" onclick=\"removerImagemFundoEscola()\">\n                        <i class=\"bi bi-x-circle me-1\"></i> Desactivar Imagem de Fundo\n                      </button>\n                    </div>\n                  </div>\n\n                  <!-- Galeria de Fundos Disponíveis -->\n                  <div class=\"mb-3\">\n                    <div class=\"d-flex align-items-center justify-content-between mb-2\">\n                      <span class=\"x-small fw-bold text-dark text-uppercase\" style=\"font-size: 0.75rem;\">\n                        <i class=\"bi bi-collection-fill text-primary me-1\"></i> Opções de Fundo Disponíveis:\n                      </span>\n                      <small class=\"text-muted fw-semibold\" id=\"contadorGaleriaFundos\">Carregando...</small>\n                    </div>\n                    <div id=\"galeriaFundosContainer\" class=\"row g-2 mb-2\" style=\"max-height: 240px; overflow-y: auto;\">\n                      <!-- Opções de fundo geradas dinamicamente via JS -->\n                    </div>\n                  </div>\n\n                  <!-- Modo de Exibição e Opacidade do Fundo -->\n                  <div class=\"p-2 rounded bg-white border mb-3\">\n                    <div class=\"row g-2 mb-2\">\n                      <div class=\"col-sm-6\">\n                        <label class=\"form-label x-small text-dark mb-1 fw-bold\" style=\"font-size: 0.76rem;\">Modo de Exibição do Fundo</label>\n                        <select id=\"confEscolaFundoModo\" class=\"form-select form-select-sm\" onchange=\"aoMudarModoFundo(this.value)\">\n                          <option value=\"marca_dagua\">1. Marca de Água Central Sutil</option>\n                          <option value=\"cobertura_total\">2. Papel de Parede Total (Wallpaper)</option>\n                          <option value=\"padrao_textura\">3. Padrão Textura Suave</option>\n                          <option value=\"nenhum\">4. Sem Imagem de Fundo (Apenas Cores)</option>\n                        </select>\n                      </div>\n                      <div class=\"col-sm-6\">\n                        <label class=\"form-label x-small text-dark mb-1 fw-bold d-flex justify-content-between\" style=\"font-size: 0.76rem;\">\n                          <span>Transparência / Opacidade</span>\n                          <strong id=\"lblFundoOpacidade\" class=\"text-primary\">15%</strong>\n                        </label>\n                        <input type=\"range\" id=\"confEscolaFundoOpacidade\" class=\"form-range mt-1\" min=\"5\" max=\"50\" step=\"1\" value=\"15\" oninput=\"atualizarLabelOpacidadeFundo(this.value)\">\n                        <small class=\"text-muted d-block\" style=\"font-size: 0.68rem;\">Recomendado: 10% a 20% para perfeita legibilidade.</small>\n                      </div>\n                    </div>\n\n                    <!-- Carregar Nova Imagem de Fundo -->\n                    <div class=\"border-top pt-2\">\n                      <div class=\"fw-bold text-primary small mb-2 d-flex align-items-center justify-content-between\">\n                        <span><i class=\"bi bi-cloud-arrow-up-fill me-1\"></i> Carregar Nova Imagem de Fundo</span>\n                        <span class=\"badge bg-light text-muted border\" style=\"font-size: 0.65rem;\">PNG, JPG, WebP</span>\n                      </div>\n                      <div class=\"mb-2\">\n                        <label class=\"form-label x-small text-dark mb-1 fw-bold\" style=\"font-size: 0.74rem;\">1. Carregar do Computador</label>\n                        <input type=\"file\" id=\"confEscolaFundoFile\" accept=\"image/*\" class=\"form-control form-control-sm\" onchange=\"processarUploadFundoLocal(this)\">\n                      </div>\n                      <div class=\"mb-1\">\n                        <label class=\"form-label x-small text-dark mb-1 fw-bold\" style=\"font-size: 0.74rem;\">2. Ou Link / URL da Imagem</label>\n                        <div class=\"input-group input-group-sm\">\n                          <input type=\"url\" id=\"confEscolaFundoUrl\" class=\"form-control\" placeholder=\"https://escola.edu.mz/fundo.jpg\">\n                          <button type=\"button\" class=\"btn btn-outline-primary fw-semibold\" onclick=\"processarUrlFundo(document.getElementById('confEscolaFundoUrl').value)\">\n                            <i class=\"bi bi-plus-lg me-1\"></i> Adicionar\n                          </button>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n\n                  <!-- Botões de Ação Imediata -->\n                  <div class=\"d-flex gap-2\">\n                    <button type=\"button\" class=\"btn btn-outline-primary btn-sm flex-grow-1 fw-semibold\" onclick=\"aplicarTemaEFundoAoVivo()\">\n                      <i class=\"bi bi-eye-fill me-1\"></i> Testar Visualização ao Vivo\n                    </button>\n                    <button type=\"button\" class=\"btn btn-outline-secondary btn-sm fw-semibold\" onclick=\"restaurarPadraoTemaEFundo()\" title=\"Restaurar o tema clássico azul e marca d'água padrão\">\n                      <i class=\"bi bi-arrow-counterclockwise me-1\"></i> Restaurar Padrão\n                    </button>\n                  </div>\n\n                  <input type=\"hidden\" id=\"confEscolaFundoFinalValue\" value=\"\">\n                </div>\n\n                <button type=\"submit\" class=\"btn btn-primary btn-sm w-100 fw-bold py-2 shadow-sm\">\n                  <i class=\"bi bi-check-circle-fill me-1\"></i> Salvar Definições, Tema & Fundo\n                </button>\n              </form>\n            </div>\n          </div>\n          <div class=\"col-lg-7\">\n            <div class=\"card p-4\">\n              <div class=\"d-flex justify-content-between align-items-center mb-3\">\n                <div>\n                  <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-diagram-3 me-2\"></i>Turmas & Direcção de Classe</h5>\n                  <small class=\"text-muted\">Defina a classe, turmas (1, 2, 3...), capacidade máxima e distribuição de alunos.</small>\n                </div>\n                <div class=\"d-flex flex-wrap gap-2\">\n                  <button class=\"btn btn-dark btn-sm shadow-sm\" onclick=\"navegarPara('turmas')\"><i class=\"bi bi-box-arrow-up-right me-1\"></i> Painel Dedicado</button>\n                  <button class=\"btn btn-outline-primary btn-sm\" onclick=\"modalCriarTurmasEmLote()\"><i class=\"bi bi-layers-fill me-1\"></i> Gerar Turmas (1, 2, 3...)</button>\n                  <button class=\"btn btn-success btn-sm shadow-sm\" onclick=\"modalDistribuirAlunosAutomatico()\"><i class=\"bi bi-magic me-1\"></i> Formação Automática</button>\n                  <button class=\"btn btn-primary btn-sm\" onclick=\"modalCriarTurma()\"><i class=\"bi bi-plus-lg me-1\"></i> Nova Turma</button>\n                  <button class=\"btn btn-outline-warning btn-sm\" onclick=\"corrigirNumeracaoTurmas()\" title=\"Renumera turmas de forma contínua por classe, eliminando sobreposições\"><i class=\"bi bi-sort-numeric-up me-1\"></i> Corrigir Numeração</button>\n                </div>\n              </div>\n              <div class=\"table-responsive\">\n                <table class=\"table table-hover align-middle\">\n                  <thead class=\"table-light\">\n                    <tr>\n                      <th>Turma</th>\n                      <th>Classe / Grau</th>\n                      <th>Turno</th>\n                      <th>Ocupação / Máx</th>\n                      <th>Dir. Turma</th>\n                      <th>Dir. Classe</th>\n                      <th class=\"text-end\">Ações</th>\n                    </tr>\n                  </thead>\n                  <tbody id=\"tabelaTurmas\">\n                    <tr><td colspan=\"7\" class=\"text-center py-4\">A carregar turmas...</td></tr>\n                  </tbody>\n                </table>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/estatisticas-aproveitamento": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Estatística de Aproveitamento -->\n<!-- Página independente do módulo: estatisticas-aproveitamento.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-estatisticas-aproveitamento\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4 no-print mb-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2\">\n            <div>\n              <h5 class=\"fw-bold mb-1\"><i class=\"bi bi-bar-chart-line-fill text-success me-2\"></i>Estatística do Aproveitamento Pedagógico Escolar</h5>\n              <p class=\"text-muted small mb-0\">Monitoramento oficial do rendimento escolar por Turma, por Classe (7ª a 12ª), Geral da Escola e por Disciplina.</p>\n            </div>\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\n              <div>\n                <label class=\"form-label very-small text-muted mb-0\">Ano Lectivo</label>\n                <div class=\"sige-seletor-ano-box d-flex align-items-center\">\n                  <select id=\"statAnoFiltro\" class=\"form-select form-select-sm sige-select-ano-lectivo\" onchange=\"carregarEstatisticasAproveitamento()\">\n                    <option value=\"\">-- Escolha ano Lectivo --</option>\n                  </select>\n                  <button type=\"button\" class=\"btn btn-sm btn-sige-buscar-ano\" onclick=\"carregarEstatisticasAproveitamento()\">\n                    Buscar <i class=\"bi bi-search ms-1\"></i>\n                  </button>\n                </div>\n              </div>\n              <div>\n                <label class=\"form-label very-small text-muted mb-0\">Período / Trimestre</label>\n                <select id=\"statPeriodoFiltro\" class=\"form-select form-select-sm\" onchange=\"carregarEstatisticasAproveitamento()\">\n                  <option value=\"GLOBAL\" selected>Anual / Global (MFD)</option>\n                  <option value=\"T1\">1º Trimestre</option>\n                  <option value=\"T2\">2º Trimestre</option>\n                  <option value=\"T3\">3º Trimestre</option>\n                </select>\n              </div>\n              <div class=\"d-flex gap-1 align-self-end\">\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"carregarEstatisticasAproveitamento()\" title=\"Atualizar dados\">\n                  <i class=\"bi bi-arrow-repeat me-1\"></i> Visualizar\n                </button>\n                <button class=\"btn btn-primary btn-sm\" onclick=\"window.print()\" title=\"Imprimir Relatório\">\n                  <i class=\"bi bi-printer me-1\"></i> Imprimir\n                </button>\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"descarregarEstatisticasPdf()\" title=\"Descarregar documento em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarEstatisticasExcel()\" title=\"Descarregar ficheiro Excel (XLSX)\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarEstatisticasWord()\" title=\"Descarregar documento em Word (DOCX)\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n            </div>\n          </div>\n\n          <!-- Indicadores Globais Rápidos (KPIs) -->\n          <div class=\"row g-3 mb-2\" id=\"kpiEstatisticasContainer\">\n            <div class=\"col-md-3\">\n              <div class=\"stat-card p-3 border rounded bg-light\">\n                <span class=\"text-muted very-small text-uppercase fw-semibold\">Taxa de Aprovação Global</span>\n                <h4 id=\"statKpiAprovacao\" class=\"fw-bold mb-0 text-success\">0%</h4>\n                <small class=\"text-muted\" id=\"statKpiAprovacaoSub\">0 Aprovados de 0 Avaliados</small>\n              </div>\n            </div>\n            <div class=\"col-md-3\">\n              <div class=\"stat-card p-3 border rounded bg-light\">\n                <span class=\"text-muted very-small text-uppercase fw-semibold\">Taxa de Reprovação</span>\n                <h4 id=\"statKpiReprovacao\" class=\"fw-bold mb-0 text-danger\">0%</h4>\n                <small class=\"text-muted\" id=\"statKpiReprovacaoSub\">0 Alunos não transitam</small>\n              </div>\n            </div>\n            <div class=\"col-md-3\">\n              <div class=\"stat-card p-3 border rounded bg-light\">\n                <span class=\"text-muted very-small text-uppercase fw-semibold\">Efectivo Avaliado</span>\n                <h4 id=\"statKpiAvaliados\" class=\"fw-bold mb-0 text-primary\">0</h4>\n                <small class=\"text-muted\" id=\"statKpiAvaliadosSub\">0 M | 0 F</small>\n              </div>\n            </div>\n            <div class=\"col-md-3\">\n              <div class=\"stat-card p-3 border rounded bg-light\">\n                <span class=\"text-muted very-small text-uppercase fw-semibold\">Total de Turmas Activas</span>\n                <h4 id=\"statKpiTurmas\" class=\"fw-bold mb-0 text-dark\">0</h4>\n                <small class=\"text-muted\" id=\"statKpiTurmasSub\">Classes do Ensino Secundário</small>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Documento Renderizado de Estatísticas (Para visualização e impressão) -->\n        <div class=\"card p-4 printable-document bg-white\" id=\"containerEstatisticasDocumento\">\n          <div class=\"text-center py-4\">\n            <div class=\"spinner-border text-primary\"></div>\n            <p class=\"small text-muted mt-2\">A carregar estatísticas pedagógicas da escola...</p>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/impressao": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Central de Impressão de Documentos -->\n<!-- Página independente do módulo: impressao.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-impressao\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4 no-print mb-4\">\n          <h5 class=\"fw-bold mb-2\"><i class=\"bi bi-printer me-2\"></i>Central de Impressão de Documentos Oficiais</h5>\n          <p class=\"text-muted small mb-3\">Emita Boletins, Declarações, Certificados, Recibos e Fichas com formato oficial A4. Seleccione a modalidade individual ou emissão em lote por Turma.</p>\n          \n          <div class=\"row g-3 align-items-end\">\n            <div class=\"col-md-3\">\n              <label class=\"form-label small fw-semibold\">Tipo de Documento</label>\n              <select id=\"printTipoDoc\" class=\"form-select\" onchange=\"alternarCamposImpressao(this.value)\">\n                <option value=\"BOLETIM\">Boletim Escolar</option>\n                <option value=\"DECLARACAO\">Declaração Escolar com Notas</option>\n                <option value=\"CERTIFICADO\">Certificado de Habilitações</option>\n                <option value=\"RECIBO\">Recibo de Propina</option>\n                <option value=\"FICHA\">Ficha Biográfica do Aluno</option>\n                <option value=\"PAUTA_TURMA\">Pauta Geral da Turma</option>\n                <option value=\"ACTA_CONSELHO\">Acta do Conselho de Avaliação</option>\n              </select>\n            </div>\n            <div class=\"col-md-3\">\n              <label class=\"form-label small fw-semibold\">Turma</label>\n              <select id=\"printSelectTurma\" class=\"form-select\" onchange=\"aoSelecionarTurmaImpressao()\">\n                <option value=\"\">Selecione uma turma...</option>\n              </select>\n            </div>\n            <div class=\"col-md-3\">\n              <label class=\"form-label small fw-semibold\">Destinatário (Todos / Individual)</label>\n              <select id=\"printSelectAluno\" class=\"form-select\">\n                <option value=\"TODOS\">-- Todos os Alunos (Lote) --</option>\n              </select>\n            </div>\n            <div class=\"col-md-3\">\n              <label class=\"form-label small fw-semibold\">Orientação da Página</label>\n              <select id=\"printOrientacaoSelect\" class=\"form-select\" onchange=\"atualizarOrientacaoDocumentoCentral(this.value)\">\n                <option value=\"auto\" selected>Automática (Pauta: Horizontal | Outros: Vertical)</option>\n                <option value=\"portrait\">Vertical (Retrato / Portrait)</option>\n                <option value=\"landscape\">Horizontal (Paisagem / Landscape)</option>\n              </select>\n            </div>\n            <div class=\"col-12 d-flex flex-wrap gap-2 justify-content-between align-items-center pt-2 border-top\">\n              <div class=\"d-flex align-items-center gap-2\">\n                <span class=\"small text-muted fw-semibold me-1\">Orientação Rápida:</span>\n                <div class=\"btn-group btn-group-sm\" role=\"group\" aria-label=\"Orientação\">\n                  <button type=\"button\" class=\"btn btn-primary\" id=\"btnOrientacaoAuto\" onclick=\"definirOrientacaoDocumentoCentral('auto')\" title=\"Automática: Pauta Horizontal, Restantes Vertical\">\n                    <i class=\"bi bi-magic me-1\"></i> Auto\n                  </button>\n                  <button type=\"button\" class=\"btn btn-outline-secondary\" id=\"btnOrientacaoPortrait\" onclick=\"definirOrientacaoDocumentoCentral('portrait')\" title=\"Forçar Orientação Vertical\">\n                    <i class=\"bi bi-file-earmark me-1\"></i> Vertical\n                  </button>\n                  <button type=\"button\" class=\"btn btn-outline-secondary\" id=\"btnOrientacaoLandscape\" onclick=\"definirOrientacaoDocumentoCentral('landscape')\" title=\"Forçar Orientação Horizontal\">\n                    <i class=\"bi bi-file-earmark-landscape me-1\"></i> Horizontal\n                  </button>\n                </div>\n              </div>\n              <div class=\"d-flex flex-wrap gap-2 justify-content-end\">\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"carregarVisualizacaoImpressao()\"><i class=\"bi bi-eye me-1\"></i> Visualizar</button>\n                <button class=\"btn btn-primary btn-sm\" onclick=\"imprimirDocumentoCentral()\"><i class=\"bi bi-printer me-1\"></i> Imprimir</button>\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"descarregarPdfCentral()\"><i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF (.pdf)</button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"descarregarDocxCentral()\"><i class=\"bi bi-file-earmark-word me-1\"></i> Word (.docx)</button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"descarregarXlsxCentral()\"><i class=\"bi bi-file-earmark-excel me-1\"></i> Excel (.xlsx)</button>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Área de Impressão Renderizada Oficial -->\n        <div id=\"printAreaPreview\" class=\"printable-document card p-5 bg-white mx-auto shadow-sm\" style=\"max-width: 860px; display: none;\">\n          <!-- Conteúdo dinâmico oficial renderizado via JavaScript -->\n        </div>\n      </section>\n",
  "painel-escola/material-escolar": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Material Escolar da Instituição -->\n<!-- Página independente do módulo: material-escolar.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-material-escolar\" class=\"modulo-view\" style=\"display: none;\">\n        <!-- Cabeçalho do Painel com Ações -->\n        <div class=\"card p-4 mb-4 border-0 shadow-sm text-white\" style=\"background: linear-gradient(135deg, #1e3a8a 0%, #2563eb 100%);\">\n          <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3\">\n            <div>\n              <h4 class=\"fw-bold mb-1\"><i class=\"bi bi-book-half me-2\"></i>Material Escolar & Recursos Didáticos</h4>\n              <p class=\"mb-0 text-white-50 small\">\n                Navegue pelas classes de 1ª a 12ª Classe, consulte, descarregue manuais oficiais ou carregue novos ficheiros e livros da instituição.\n              </p>\n            </div>\n            <div class=\"d-flex gap-2\">\n              <button class=\"btn btn-light fw-bold text-primary shadow-sm\" onclick=\"modalCarregarMaterialEscolar()\" id=\"btnCarregarMaterial\">\n                <i class=\"bi bi-cloud-arrow-up-fill me-1\"></i> Carregar / Importar Material\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- Barra Unificada de Filtros de Materiais Escolares (Sem excesso de botões) -->\n        <div class=\"card p-3 mb-4 shadow-sm border-0\">\n          <div class=\"row g-2 align-items-end\">\n            <div class=\"col-md-3 col-sm-6\">\n              <label class=\"form-label small fw-bold text-muted mb-1\">\n                <i class=\"bi bi-mortarboard-fill me-1 text-primary\"></i> 1. Classe / Grau:\n              </label>\n              <select id=\"filtroMaterialClasseSelect\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"selecionarClasseMaterial(this.value)\">\n                <option value=\"TODAS\">Todas as Classes / Níveis</option>\n              </select>\n            </div>\n            <div class=\"col-md-3 col-sm-6\">\n              <label class=\"form-label small fw-bold text-muted mb-1\">\n                <i class=\"bi bi-tag me-1 text-info\"></i> 2. Tipo de Material:\n              </label>\n              <select id=\"filtroMaterialTipo\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"filtrarMateriaisEscolares()\">\n                <option value=\"\">Todos os Tipos (Manuais, Fichas...)</option>\n                <option value=\"MANUAL\">Livros / Manuais Oficiais</option>\n                <option value=\"FICHA\">Fichas de Exercícios / Avaliação</option>\n                <option value=\"GUIA\">Guias de Correcção / Apoio</option>\n                <option value=\"APOSTILA\">Apostilas & Resumos</option>\n                <option value=\"OUTRO\">Outros Materiais</option>\n              </select>\n            </div>\n            <div class=\"col-md-4 col-sm-8\">\n              <label class=\"form-label small fw-bold text-muted mb-1\">\n                <i class=\"bi bi-search me-1 text-secondary\"></i> 3. Pesquisa:\n              </label>\n              <div class=\"input-group input-group-sm\">\n                <span class=\"input-group-text bg-white\"><i class=\"bi bi-search\"></i></span>\n                <input type=\"text\" id=\"filtroMaterialBusca\" class=\"form-control form-control-sm bg-white\" placeholder=\"Título, disciplina ou descrição...\" oninput=\"filtrarMateriaisEscolares()\">\n                <button class=\"btn btn-outline-secondary\" type=\"button\" onclick=\"document.getElementById('filtroMaterialBusca').value=''; filtrarMateriaisEscolares();\" title=\"Limpar pesquisa\">&times;</button>\n              </div>\n            </div>\n            <div class=\"col-md-2 col-sm-4 text-end\">\n              <div id=\"containerBotoesClassesMateriais\" style=\"display: none;\"></div>\n              <span class=\"badge bg-primary-subtle text-primary fw-semibold d-block text-truncate mb-1\" id=\"badgeClasseAtiva\">Todas as Classes</span>\n              <small class=\"text-muted d-block\" id=\"contadorMateriaisEncontrados\">0 materiais</small>\n            </div>\n          </div>\n        </div>\n\n        <!-- Lista / Grelha de Materiais da Classe -->\n        <div class=\"row g-4\" id=\"grelhaMateriaisEscolares\">\n          <div class=\"col-12 text-center py-5 text-muted\">\n            <i class=\"bi bi-folder2-open display-4 d-block mb-3 opacity-50\"></i>\n            A carregar materiais da classe...\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/pagamentos": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Mensalidades & Propinas -->\n<!-- Página independente do módulo: pagamentos.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-pagamentos\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-3 mb-4\">\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Faturamento Total</span>\n                <h4 id=\"finFaturadoCard\" class=\"fw-bold mb-0 text-success\">0 <span class=\"moeda-sufixo\">MZN</span></h4>\n              </div>\n              <div class=\"stat-icon bg-success bg-opacity-10 text-success\"><i class=\"bi bi-cash-stack\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Em Atraso</span>\n                <h4 id=\"finAtrasadoCard\" class=\"fw-bold mb-0 text-danger\">0 <span class=\"moeda-sufixo\">MZN</span></h4>\n              </div>\n              <div class=\"stat-icon bg-danger bg-opacity-10 text-danger\"><i class=\"bi bi-exclamation-circle-fill\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Inadimplência</span>\n                <h4 id=\"finInadimplenciaCard\" class=\"fw-bold mb-0 text-warning\">0%</h4>\n              </div>\n              <div class=\"stat-icon bg-warning bg-opacity-10 text-warning\"><i class=\"bi bi-pie-chart-fill\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Alunos em Dia</span>\n                <h4 id=\"finAdimplentesCard\" class=\"fw-bold mb-0 text-primary\">0%</h4>\n              </div>\n              <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\"><i class=\"bi bi-check-circle\"></i></div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card p-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3\">\n            <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-wallet2 me-2\"></i>Gestão de Propinas & Mensalidades (MZN)</h5>\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarPagamentosPdf()\" title=\"Exportar pagamentos em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarPagamentosExcel()\" title=\"Exportar pagamentos em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarPagamentosWord()\" title=\"Exportar pagamentos em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-outline-primary btn-sm\" onclick=\"modalGerarMensalidadesTurma()\"><i class=\"bi bi-calendar-plus me-1\"></i> Gerar em Lote para Turma</button>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"modalNovoPagamento()\"><i class=\"bi bi-plus-lg me-1\"></i> Nova Cobrança</button>\n            </div>\n          </div>\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Aluno</th>\n                  <th>Descrição</th>\n                  <th>Mês Ref.</th>\n                  <th>Valor (MZN)</th>\n                  <th>Vencimento</th>\n                  <th>Estado</th>\n                  <th class=\"text-end\">Liquidação & Recibo</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaPagamentos\">\n                <tr><td colspan=\"7\" class=\"text-center py-4\">A carregar pagamentos...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/pautas": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Pautas & Actas Oficiais -->\n<!-- Página independente do módulo: pautas.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-pautas\" class=\"modulo-view\" style=\"display: none;\">\n        <!-- Barra Superior de Controlo e Navegação entre Pauta e Acta -->\n        <div class=\"card p-4 mb-4 no-print\">\n          <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3\">\n            <div class=\"d-flex align-items-center gap-3\">\n              <div>\n                <label class=\"form-label small fw-semibold mb-1\">Classe</label>\n                <select id=\"pautaClasseFilter\" class=\"form-select form-select-sm\" style=\"min-width: 130px;\" onchange=\"filtrarTurmasPautaPorClasse()\">\n                  <option value=\"\">Todas as Classes / Níveis</option>\n                </select>\n              </div>\n              <div>\n                <label class=\"form-label small fw-semibold mb-1\">Turma</label>\n                <select id=\"pautaTurmaSelect\" class=\"form-select form-select-sm\" style=\"min-width: 230px;\" onchange=\"alternarVisualizacaoPautaTurma()\">\n                  <option value=\"\">A carregar turmas...</option>\n                </select>\n              </div>\n              <div>\n                <label class=\"form-label small fw-semibold mb-1\">Ano Lectivo</label>\n                <div class=\"sige-seletor-ano-box d-flex align-items-center\">\n                  <select id=\"pautaAnoSelect\" class=\"form-select form-select-sm sige-select-ano-lectivo\" onchange=\"aoClicarBuscarPautaAno()\">\n                    <option value=\"\">-- Escolha ano Lectivo --</option>\n                  </select>\n                  <button type=\"button\" class=\"btn btn-sm btn-sige-buscar-ano\" onclick=\"aoClicarBuscarPautaAno()\">\n                    Buscar <i class=\"bi bi-search ms-1\"></i>\n                  </button>\n                </div>\n              </div>\n              <div>\n                <label class=\"form-label small fw-semibold mb-1\">Orientação da Página</label>\n                <div class=\"input-group input-group-sm\">\n                  <select id=\"pautaOrientacaoSelect\" class=\"form-select form-select-sm\" style=\"min-width: 145px;\" onchange=\"aoMudarOrientacaoPauta(this.value)\">\n                    <option value=\"landscape\" selected>Horizontal (Oficial Pauta)</option>\n                    <option value=\"portrait\">Vertical (Retrato A4)</option>\n                  </select>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"d-flex gap-2\">\n              <div class=\"btn-group btn-group-sm\" role=\"group\">\n                <button type=\"button\" class=\"btn btn-outline-primary active\" id=\"btnAbaPauta\" onclick=\"mudarSubAbaPauta('pauta')\">\n                  <i class=\"bi bi-table me-1\"></i> Pauta Geral da Turma\n                </button>\n                <button type=\"button\" class=\"btn btn-outline-primary\" id=\"btnAbaActa\" onclick=\"mudarSubAbaPauta('acta')\">\n                  <i class=\"bi bi-journal-text me-1\"></i> Acta do Conselho de Avaliação\n                </button>\n              </div>\n              <button class=\"btn btn-outline-secondary btn-sm\" onclick=\"modalGerarPauta()\">\n                <i class=\"bi bi-plus-circle me-1\"></i> Consolidar\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- SUB-ABA 1: PAUTA GERAL DA TURMA (TODAS AS DISCIPLINAS LADO A LADO) (Imagem 3) -->\n        <div id=\"subViewPautaGeral\" class=\"card p-4 printable-document\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 border-bottom pb-3\">\n            <div>\n              <h5 class=\"fw-bold mb-0\" id=\"pautaGeralTitulo\">Pauta Oficial de Aproveitamento Pedagógico</h5>\n              <small class=\"text-muted\" id=\"pautaGeralSubtitulo\">Ano Lectivo: 2026 | Critério Oficial MEC Aplicado</small>\n            </div>\n            <div class=\"d-flex gap-2 no-print\">\n              <button class=\"btn btn-success btn-sm\" onclick=\"exportarPautaGeralExcel()\" title=\"Descarregar ficheiro XLSX (Excel)\">\n                <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel (.xlsx)\n              </button>\n              <button class=\"btn btn-danger btn-sm\" onclick=\"descarregarPautaGeralPdf()\" title=\"Descarregar documento em PDF\">\n                <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF (.pdf)\n              </button>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"imprimirPautaGeralOficial()\" title=\"Imprimir em A4 horizontal\">\n                <i class=\"bi bi-printer me-1\"></i> Imprimir\n              </button>\n            </div>\n          </div>\n\n          <!-- Grelha da Pauta Geral renderizada dinamicamente -->\n          <div class=\"table-responsive\" id=\"containerTabelaPautaGeral\">\n            <p class=\"text-center py-4 text-muted\">Selecione uma turma acima para gerar a pauta geral.</p>\n          </div>\n        </div>\n\n        <!-- SUB-ABA 2: ACTA DO CONSELHO DE AVALIAÇÃO / ESTATÍSTICA DA TURMA (Imagem 1) -->\n        <div id=\"subViewActaConselho\" class=\"card p-5 printable-document d-none\" style=\"background: #fff;\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 no-print\">\n            <div>\n              <button class=\"btn btn-outline-secondary btn-sm\" onclick=\"modalConfigurarSessaoActa()\">\n                <i class=\"bi bi-sliders me-1\"></i> Configurar Dados da Sessão do Conselho\n              </button>\n            </div>\n            <div class=\"d-flex gap-2\">\n              <button class=\"btn btn-success btn-sm\" onclick=\"exportarActaConselhoExcel()\" title=\"Descarregar ficheiro XLSX (Excel)\">\n                <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel (.xlsx)\n              </button>\n              <button class=\"btn btn-danger btn-sm\" onclick=\"descarregarActaConselhoPdf()\" title=\"Descarregar documento em PDF\">\n                <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF (.pdf)\n              </button>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"imprimirActaConselhoOficial()\" title=\"Imprimir em A4 horizontal\">\n                <i class=\"bi bi-printer me-1\"></i> Imprimir\n              </button>\n            </div>\n          </div>\n\n          <!-- Conteúdo da Acta renderizado fielmente à Imagem 1 -->\n          <div id=\"containerActaConselhoCorpo\">\n            <p class=\"text-center py-4 text-muted\">Selecione uma turma acima para gerar a acta do conselho.</p>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/professores": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Corpo Docente -->\n<!-- Página independente do módulo: professores.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-professores\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-3 mb-4\">\n          <div class=\"col-md-4\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Total Professores</span>\n                <h4 id=\"profTotalCard\" class=\"fw-bold mb-0\">0</h4>\n              </div>\n              <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\"><i class=\"bi bi-person-workspace\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-4\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Relação Aluno / Docente</span>\n                <h4 id=\"profRatioCard\" class=\"fw-bold mb-0 text-info\">0 : 1</h4>\n              </div>\n              <div class=\"stat-icon bg-info bg-opacity-10 text-info\"><i class=\"bi bi-arrows-angle-expand\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-4\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Aulas Ministradas / Mês</span>\n                <h4 id=\"profAulasMesCard\" class=\"fw-bold mb-0 text-success\">0</h4>\n              </div>\n              <div class=\"stat-icon bg-success bg-opacity-10 text-success\"><i class=\"bi bi-calendar2-check-fill\"></i></div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card p-4 mb-3 border-0 shadow-sm\">\n          <!-- Cabeçalho de Docentes -->\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3\">\n            <div>\n              <h5 class=\"fw-bold text-primary mb-1\"><i class=\"bi bi-mortarboard-fill me-2\"></i>Corpo Docente & Carreiras (MEC)</h5>\n              <p class=\"text-muted small mb-0\">Gestão e alocação sequencial: <strong>Classe</strong> &rarr; <strong>Turmas / Disciplinas</strong></p>\n            </div>\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarProfessoresPdf()\" title=\"Exportar lista de docentes em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarProfessoresExcel()\" title=\"Exportar lista de docentes em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarProfessoresWord()\" title=\"Exportar lista de docentes em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-outline-primary btn-sm\" onclick=\"carregarProfessores()\"><i class=\"bi bi-arrow-clockwise me-1\"></i> Actualizar</button>\n              <button class=\"btn btn-outline-primary btn-sm\" onclick=\"modalAlocarProfessor()\"><i class=\"bi bi-link-45deg me-1\"></i> Alocar a Turma/Disciplina</button>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"modalNovoProfessor()\"><i class=\"bi bi-plus-lg me-1\"></i> Cadastrar Docente</button>\n            </div>\n          </div>\n\n          <!-- Barra Unificada de Filtros do Corpo Docente (Sem excesso de botões) -->\n          <div class=\"p-3 bg-light rounded-3 border mb-3\">\n            <div class=\"row g-2 align-items-end\">\n              <!-- Filtro 1: Classe -->\n              <div class=\"col-md-4 col-sm-6\">\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\n                  <span><i class=\"bi bi-mortarboard-fill me-1 text-primary\"></i> 1. Classe / Grau:</span>\n                  <span id=\"contagemClassesProfessores\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\n                </label>\n                <select id=\"selectFiltroProfessorClasse\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"selecionarClasseProfessores(this.value)\">\n                  <!-- Opções geradas via JS -->\n                </select>\n              </div>\n\n              <!-- Filtro 2: Pesquisa Docente -->\n              <div class=\"col-md-8 col-sm-6\">\n                <label class=\"form-label small fw-bold text-muted mb-1\">\n                  <i class=\"bi bi-search me-1 text-secondary\"></i> 2. Pesquisar Docente:\n                </label>\n                <div class=\"input-group input-group-sm\">\n                  <input type=\"search\" id=\"pesquisaProfessores\" class=\"form-control form-control-sm bg-white\" placeholder=\"Nome, especialidade, e-mail, contacto...\" oninput=\"filtrarProfessoresTabela()\">\n                  <button class=\"btn btn-outline-secondary\" type=\"button\" onclick=\"document.getElementById('pesquisaProfessores').value=''; filtrarProfessoresTabela();\" title=\"Limpar pesquisa\">&times;</button>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Indicador de Selecção e Resumo -->\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 pt-2 border-top\">\n            <div class=\"d-flex align-items-center gap-2\">\n              <span class=\"badge bg-primary fs-6 px-3 py-2 shadow-sm\" id=\"badgeCaminhoProfessores\">\n                <i class=\"bi bi-people-fill me-1\"></i> Todos os Professores\n              </span>\n              <span id=\"contagemProfessoresExibidos\" class=\"text-muted small fw-semibold\"></span>\n            </div>\n            <div class=\"small text-muted d-flex align-items-center gap-2\">\n              <!-- Container oculto para retrocompatibilidade -->\n              <div id=\"containerBotoesClassesProfessores\" style=\"display: none;\"></div>\n              <button class=\"btn btn-link btn-sm text-decoration-none text-muted p-0\" onclick=\"limparFiltrosProfessores()\"><i class=\"bi bi-x-circle me-1\"></i> Repor Filtro</button>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card p-3 border-0 shadow-sm\">\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle mb-0\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Docente</th>\n                  <th>Contacto & E-mail</th>\n                  <th>Carreira Docente</th>\n                  <th>Província / Distrito</th>\n                  <th>Carga Horária</th>\n                  <th>Classes & Turmas Alocadas</th>\n                  <th class=\"text-end\" style=\"min-width: 220px;\">Ações</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaProfessores\">\n                <tr><td colspan=\"7\" class=\"text-center py-4 text-muted\">A carregar professores...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/turmas": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Turmas & Capacidade -->\n<!-- Página independente do módulo: turmas.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-turmas\" class=\"modulo-view\" style=\"display: none;\">\n        <!-- Cabeçalho Principal com Botões de Ação -->\n        <div class=\"card p-4 mb-4 border-0 shadow-sm\">\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-3\">\n            <div>\n              <div class=\"d-flex align-items-center gap-2 mb-1\">\n                <span class=\"badge bg-primary-subtle text-primary border border-primary-subtle px-2 py-1\"><i class=\"bi bi-diagram-3-fill me-1\"></i> Gestão de Turmas & Pedagógico</span>\n                <span class=\"badge bg-light text-muted border\">Capacidade Padrão: 50 Alunos</span>\n              </div>\n              <h4 class=\"fw-bold text-dark mb-1\">Painel de Turmas & Capacidade Máxima</h4>\n              <p class=\"text-muted small mb-0\">Controle de ocupação, criação em lote (Turmas 1, 2, 3...) e formação automática com critérios pedagógicos.</p>\n            </div>\n            <div class=\"d-flex flex-wrap gap-2 align-items-center\">\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarTurmasPdf()\" title=\"Exportar turmas em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarTurmasExcel()\" title=\"Exportar turmas em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarTurmasWord()\" title=\"Exportar turmas em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-outline-success btn-sm fw-semibold shadow-sm\" onclick=\"modalAdicionarNivelCurricular()\" title=\"Adicionar Níveis curriculares para instituições que usam Níveis\">\n                <i class=\"bi bi-layers me-1\"></i> + Adicionar Nível\n              </button>\n              <button class=\"btn btn-primary btn-sm fw-bold shadow-sm\" onclick=\"modalFormacaoAutomaticaTurmas()\">\n                <i class=\"bi bi-magic me-1\"></i> Formação Automática de Turmas (1, 2, 3...)\n              </button>\n              <button class=\"btn btn-outline-primary btn-sm fw-semibold shadow-sm\" onclick=\"modalCriarTurmasEmLote()\">\n                <i class=\"bi bi-layers-fill me-1\"></i> Gerar Turmas em Lote\n              </button>\n              <button class=\"btn btn-outline-secondary btn-sm fw-semibold shadow-sm\" onclick=\"modalCriarTurma()\">\n                <i class=\"bi bi-plus-lg me-1\"></i> Cadastrar Turma\n              </button>\n              <button class=\"btn btn-outline-warning btn-sm fw-semibold shadow-sm\" onclick=\"corrigirNumeracaoTurmas()\" title=\"Renumera turmas de forma contínua por classe, eliminando sobreposições e nomes como 'Turma 1 (1)'\">\n                <i class=\"bi bi-sort-numeric-up me-1\"></i> Corrigir Numeração\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- Indicadores & Métricas de Ocupação -->\n        <div class=\"row g-3 mb-4\">\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Total de Turmas</span>\n                <h3 id=\"statTurmasTotal\" class=\"fw-bold mb-0 text-dark\">0</h3>\n                <small class=\"text-muted\">Turmas ativas no ano lectivo</small>\n              </div>\n              <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\">\n                <i class=\"bi bi-diagram-3-fill\"></i>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Capacidade Total</span>\n                <h3 id=\"statTurmasCapacidade\" class=\"fw-bold mb-0 text-dark\">0</h3>\n                <small class=\"text-muted\">Vagas máximas autorizadas</small>\n              </div>\n              <div class=\"stat-icon bg-info bg-opacity-10 text-info\">\n                <i class=\"bi bi-person-workspace\"></i>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Alunos Enturmados</span>\n                <h3 id=\"statTurmasAlunos\" class=\"fw-bold mb-0 text-success\">0</h3>\n                <small class=\"text-success fw-medium\"><span id=\"statTurmasVagasLivres\">0</span> vagas livres</small>\n              </div>\n              <div class=\"stat-icon bg-success bg-opacity-10 text-success\">\n                <i class=\"bi bi-people-fill\"></i>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Taxa de Ocupação</span>\n                <h3 id=\"statTurmasTaxa\" class=\"fw-bold mb-0 text-primary\">0%</h3>\n                <small id=\"statTurmasStatus\" class=\"badge bg-light text-dark border\">Normal</small>\n              </div>\n              <div class=\"stat-icon bg-warning bg-opacity-10 text-warning\">\n                <i class=\"bi bi-speedometer2\"></i>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Filtros & Tabela de Turmas -->\n        <div class=\"card p-4 border-0 shadow-sm\">\n          <div class=\"row g-2 align-items-center mb-3\">\n            <div class=\"col-lg-3 col-md-6\">\n              <label class=\"form-label small fw-bold text-muted mb-1\"><i class=\"bi bi-calendar-event me-1 text-primary\"></i> Ano Lectivo</label>\n              <div class=\"sige-seletor-ano-box d-flex align-items-center w-100\">\n                <select id=\"filtroTurmasAno\" class=\"form-select form-select-sm sige-select-ano-lectivo flex-grow-1\" onchange=\"aplicarFiltroAnoTurmas()\">\n                  <option value=\"\">-- Escolha ano Lectivo --</option>\n                </select>\n                <button type=\"button\" class=\"btn btn-sm btn-sige-buscar-ano\" onclick=\"aplicarFiltroAnoTurmas()\">\n                  Buscar <i class=\"bi bi-search ms-1\"></i>\n                </button>\n              </div>\n            </div>\n            <div class=\"col-lg-2 col-md-6\">\n              <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                <label class=\"form-label small fw-bold text-muted mb-0\"><i class=\"bi bi-funnel me-1\"></i> Classe / Nível</label>\n                <button class=\"btn btn-link btn-sm p-0 text-success fw-semibold small text-decoration-none\" onclick=\"modalAdicionarNivelCurricular()\" title=\"Adicionar novo nível à instituição\">\n                  <i class=\"bi bi-plus-circle me-1\"></i> + Nível\n                </button>\n              </div>\n              <select id=\"filtroTurmasClasse\" class=\"form-select form-select-sm\" onchange=\"atualizarFiltroAreasTurmas(); aplicarFiltrosTurmas();\">\n                <option value=\"TODAS\">Todas as Classes / Níveis</option>\n              </select>\n            </div>\n            <div class=\"col-lg-2 col-md-4\">\n              <label class=\"form-label small fw-bold text-muted mb-1\"><i class=\"bi bi-tag me-1\"></i> Secção / Área</label>\n              <select id=\"filtroTurmasArea\" class=\"form-select form-select-sm\" onchange=\"aplicarFiltrosTurmas()\">\n                <option value=\"TODAS\">Todas as Secções / Áreas</option>\n              </select>\n            </div>\n            <div class=\"col-lg-2 col-md-4\">\n              <label class=\"form-label small fw-bold text-muted mb-1\"><i class=\"bi bi-sun me-1\"></i> Turno</label>\n              <select id=\"filtroTurmasTurno\" class=\"form-select form-select-sm\" onchange=\"aplicarFiltrosTurmas()\">\n                <option value=\"TODOS\">Todos os Turnos</option>\n                <option value=\"MANHA\">Manhã</option>\n                <option value=\"TARDE\">Tarde</option>\n                <option value=\"NOITE\">Noite</option>\n              </select>\n            </div>\n            <div class=\"col-lg-3 col-md-4\">\n              <label class=\"form-label small fw-bold text-muted mb-1\"><i class=\"bi bi-search me-1\"></i> Pesquisar</label>\n              <div class=\"input-group input-group-sm\">\n                <input type=\"search\" id=\"filtroTurmasBusca\" class=\"form-control\" placeholder=\"Buscar por turma, director ou sala...\" oninput=\"aplicarFiltrosTurmas()\">\n                <button class=\"btn btn-outline-secondary\" type=\"button\" onclick=\"document.getElementById('filtroTurmasBusca').value=''; aplicarFiltrosTurmas();\">&times;</button>\n              </div>\n            </div>\n          </div>\n\n          <!-- Legenda de Cores de Ocupação -->\n          <div class=\"d-flex flex-wrap align-items-center gap-3 p-2 mb-3 bg-light rounded border small\">\n            <strong class=\"text-secondary\"><i class=\"bi bi-info-circle me-1\"></i> Legenda da Ocupação / Máx:</strong>\n            <span class=\"d-inline-flex align-items-center gap-1\"><span class=\"badge bg-success\">&bull;</span> <strong>Verde:</strong> com vagas disponíveis (&lt; 80%)</span>\n            <span class=\"d-inline-flex align-items-center gap-1\"><span class=\"badge bg-warning text-dark\">&bull;</span> <strong>Amarelo:</strong> próxima do limite (&ge; 80%)</span>\n            <span class=\"d-inline-flex align-items-center gap-1\"><span class=\"badge bg-danger\">&bull;</span> <strong>Vermelho:</strong> capacidade atingida (100% ou lotada)</span>\n          </div>\n\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle mb-0\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Turma</th>\n                  <th>Classe / Grau</th>\n                  <th>Secção / Área</th>\n                  <th>Turno</th>\n                  <th>Sala</th>\n                  <th style=\"min-width: 170px;\">Ocupação / Máx</th>\n                  <th>Director de Turma</th>\n                  <th>Director de Classe</th>\n                  <th class=\"text-end\">Ações</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaTurmasView\">\n                <tr><td colspan=\"9\" class=\"text-center py-4\">A carregar turmas...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-escola/usuarios-senhas": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Cofre de Credenciais da Escola -->\n<!-- Página independente do módulo: usuarios-senhas.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-usuarios-senhas\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4\">\n          <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3 mb-3 border-bottom pb-3\">\n            <div>\n              <h5 class=\"fw-bold mb-0 text-warning text-dark\"><i class=\"bi bi-shield-lock-fill text-warning me-2\"></i>Cofre Restrito de Utilizadores e Palavras-passe</h5>\n              <small class=\"text-muted\">Acesso restrito à Direcção da Escola e SuperAdmin para gestão de códigos de acesso e credenciais</small>\n            </div>\n            <div class=\"d-flex gap-2\">\n              <input type=\"text\" id=\"filtroUsuarioCofre\" class=\"form-control form-control-sm\" placeholder=\"Pesquisar por código, nome ou e-mail...\" oninput=\"filtrarUsuariosCofre()\" style=\"width: 260px;\">\n              <select id=\"filtroRoleCofre\" class=\"form-select form-select-sm\" onchange=\"filtrarUsuariosCofre()\" style=\"width: 170px;\">\n                <option value=\"\">Todos os Perfis</option>\n                <option value=\"ADMIN_ESCOLA\">Gabinete do Director (GD)</option>\n                <option value=\"DIRECTOR_ESCOLA\">Director da Escola (GD)</option>\n                <option value=\"DAP\">Direcção Pedagógica (DP)</option>\n                <option value=\"CHEFE_SECRETARIA\">Secretaria (SECR)</option>\n                <option value=\"PROFESSOR\">Professores (PR)</option>\n                <option value=\"ALUNO\">Alunos</option>\n              </select>\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarUsuariosPdf()\" title=\"Exportar utilizadores em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarUsuariosExcel()\" title=\"Exportar utilizadores em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarUsuariosWord()\" title=\"Exportar utilizadores em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"carregarCofreUsuarios()\">\n                <i class=\"bi bi-arrow-clockwise me-1\"></i> Actualizar\n              </button>\n            </div>\n          </div>\n\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Código de Acesso</th>\n                  <th>Nome Completo</th>\n                  <th>E-mail de Acesso</th>\n                  <th>Perfil / Órgão</th>\n                  <th>Telefone</th>\n                  <th>Último Acesso</th>\n                  <th>Estado</th>\n                  <th class=\"text-end\">Acções</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaCofreUsuariosCorpo\">\n                <tr><td colspan=\"8\" class=\"text-center py-4\">A carregar utilizadores da escola...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-financeiro/dashboard": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-FINANCEIRO | Visão Geral Financeira -->\n<!-- Página independente do módulo: dashboard.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-dashboard\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-3 mb-4\">\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Total de Alunos</span>\n                <h3 id=\"statTotalAlunos\" class=\"fw-bold mb-0 text-dark\">0</h3>\n                <small class=\"text-success fw-medium\"><span id=\"statAlunosAtivos\">0</span> matriculados</small>\n              </div>\n              <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\">\n                <i class=\"bi bi-people-fill\"></i>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Corpo Docente</span>\n                <h3 id=\"statTotalProfessores\" class=\"fw-bold mb-0 text-dark\">0</h3>\n                <small class=\"text-muted\">Professores activos</small>\n              </div>\n              <div class=\"stat-icon bg-info bg-opacity-10 text-info\">\n                <i class=\"bi bi-person-badge-fill\"></i>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Receita Arrecadada</span>\n                <h3 id=\"statReceitaTotal\" class=\"fw-bold mb-0 text-success\">0 <span class=\"moeda-sufixo\">MZN</span></h3>\n                <small class=\"text-danger fw-medium\"><span id=\"statReceitaPendente\">0 <span class=\"moeda-sufixo\">MZN</span></span> pendente</small>\n              </div>\n              <div class=\"stat-icon bg-success bg-opacity-10 text-success\">\n                <i class=\"bi bi-cash-coin\"></i>\n              </div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Validade do Contrato</span>\n                <h3 id=\"statDiasRestantes\" class=\"fw-bold mb-0 text-primary\">0 dias</h3>\n                <small id=\"statStatusAssinatura\" class=\"badge badge-ativa\">ATIVA</small>\n              </div>\n              <div class=\"stat-icon bg-warning bg-opacity-10 text-warning\">\n                <i class=\"bi bi-shield-lock-fill\"></i>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Banner de Atalhos Rápidos da Instituição e Logótipo -->\n        <div class=\"card p-3 mb-4 border-0 shadow-sm bg-primary-subtle escola-admin-only\">\n          <div class=\"d-flex flex-wrap align-items-center justify-content-between gap-3\">\n            <div class=\"d-flex align-items-center gap-3\">\n              <div class=\"bg-primary text-white rounded p-2 fs-4\">\n                <i class=\"bi bi-image\"></i>\n              </div>\n              <div>\n                <h6 class=\"fw-bold mb-0 text-primary-emphasis\">Identidade Visual & Logótipo Oficial da Instituição</h6>\n                <small class=\"text-secondary\">Carregue o logótipo da escola ou active o Emblema Nacional para os cabeçalhos de pautas, cadernetas, boletins e certificados.</small>\n              </div>\n            </div>\n            <div>\n              <button class=\"btn btn-primary btn-sm fw-bold px-3 shadow-sm\" onclick=\"navegarPara('escola')\">\n                <i class=\"bi bi-gear-fill me-1\"></i> Carregar / Gerir Logótipo\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"row g-4\">\n          <div class=\"col-lg-8\">\n            <div class=\"card p-3\">\n              <h6 class=\"fw-bold mb-3\"><i class=\"bi bi-graph-up me-2 text-primary\"></i>Receitas Arrecadadas vs. Propinas Pendentes (MZN)</h6>\n              <canvas id=\"chartDashboardFaturamento\" height=\"120\"></canvas>\n            </div>\n          </div>\n          <div class=\"col-lg-4\">\n            <div class=\"card p-3\">\n              <h6 class=\"fw-bold mb-3\"><i class=\"bi bi-pie-chart-fill me-2 text-primary\"></i>Distribuição por Género</h6>\n              <canvas id=\"chartDashboardGenero\" height=\"240\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n",
  "painel-financeiro/impressao": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-FINANCEIRO | Central de Recibos & Impressão -->\n<!-- Página independente do módulo: impressao.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-impressao\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4 no-print mb-4\">\n          <h5 class=\"fw-bold mb-2\"><i class=\"bi bi-printer me-2\"></i>Central de Impressão de Documentos Oficiais</h5>\n          <p class=\"text-muted small mb-3\">Emita Boletins, Declarações, Certificados, Recibos e Fichas com formato oficial A4. Seleccione a modalidade individual ou emissão em lote por Turma.</p>\n          \n          <div class=\"row g-3 align-items-end\">\n            <div class=\"col-md-3\">\n              <label class=\"form-label small fw-semibold\">Tipo de Documento</label>\n              <select id=\"printTipoDoc\" class=\"form-select\" onchange=\"alternarCamposImpressao(this.value)\">\n                <option value=\"BOLETIM\">Boletim Escolar</option>\n                <option value=\"DECLARACAO\">Declaração Escolar com Notas</option>\n                <option value=\"CERTIFICADO\">Certificado de Habilitações</option>\n                <option value=\"RECIBO\">Recibo de Propina</option>\n                <option value=\"FICHA\">Ficha Biográfica do Aluno</option>\n                <option value=\"PAUTA_TURMA\">Pauta Geral da Turma</option>\n                <option value=\"ACTA_CONSELHO\">Acta do Conselho de Avaliação</option>\n              </select>\n            </div>\n            <div class=\"col-md-3\">\n              <label class=\"form-label small fw-semibold\">Turma</label>\n              <select id=\"printSelectTurma\" class=\"form-select\" onchange=\"aoSelecionarTurmaImpressao()\">\n                <option value=\"\">Selecione uma turma...</option>\n              </select>\n            </div>\n            <div class=\"col-md-3\">\n              <label class=\"form-label small fw-semibold\">Destinatário (Todos / Individual)</label>\n              <select id=\"printSelectAluno\" class=\"form-select\">\n                <option value=\"TODOS\">-- Todos os Alunos (Lote) --</option>\n              </select>\n            </div>\n            <div class=\"col-md-3\">\n              <label class=\"form-label small fw-semibold\">Orientação da Página</label>\n              <select id=\"printOrientacaoSelect\" class=\"form-select\" onchange=\"atualizarOrientacaoDocumentoCentral(this.value)\">\n                <option value=\"auto\" selected>Automática (Pauta: Horizontal | Outros: Vertical)</option>\n                <option value=\"portrait\">Vertical (Retrato / Portrait)</option>\n                <option value=\"landscape\">Horizontal (Paisagem / Landscape)</option>\n              </select>\n            </div>\n            <div class=\"col-12 d-flex flex-wrap gap-2 justify-content-between align-items-center pt-2 border-top\">\n              <div class=\"d-flex align-items-center gap-2\">\n                <span class=\"small text-muted fw-semibold me-1\">Orientação Rápida:</span>\n                <div class=\"btn-group btn-group-sm\" role=\"group\" aria-label=\"Orientação\">\n                  <button type=\"button\" class=\"btn btn-primary\" id=\"btnOrientacaoAuto\" onclick=\"definirOrientacaoDocumentoCentral('auto')\" title=\"Automática: Pauta Horizontal, Restantes Vertical\">\n                    <i class=\"bi bi-magic me-1\"></i> Auto\n                  </button>\n                  <button type=\"button\" class=\"btn btn-outline-secondary\" id=\"btnOrientacaoPortrait\" onclick=\"definirOrientacaoDocumentoCentral('portrait')\" title=\"Forçar Orientação Vertical\">\n                    <i class=\"bi bi-file-earmark me-1\"></i> Vertical\n                  </button>\n                  <button type=\"button\" class=\"btn btn-outline-secondary\" id=\"btnOrientacaoLandscape\" onclick=\"definirOrientacaoDocumentoCentral('landscape')\" title=\"Forçar Orientação Horizontal\">\n                    <i class=\"bi bi-file-earmark-landscape me-1\"></i> Horizontal\n                  </button>\n                </div>\n              </div>\n              <div class=\"d-flex flex-wrap gap-2 justify-content-end\">\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"carregarVisualizacaoImpressao()\"><i class=\"bi bi-eye me-1\"></i> Visualizar</button>\n                <button class=\"btn btn-primary btn-sm\" onclick=\"imprimirDocumentoCentral()\"><i class=\"bi bi-printer me-1\"></i> Imprimir</button>\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"descarregarPdfCentral()\"><i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF (.pdf)</button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"descarregarDocxCentral()\"><i class=\"bi bi-file-earmark-word me-1\"></i> Word (.docx)</button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"descarregarXlsxCentral()\"><i class=\"bi bi-file-earmark-excel me-1\"></i> Excel (.xlsx)</button>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Área de Impressão Renderizada Oficial -->\n        <div id=\"printAreaPreview\" class=\"printable-document card p-5 bg-white mx-auto shadow-sm\" style=\"max-width: 860px; display: none;\">\n          <!-- Conteúdo dinâmico oficial renderizado via JavaScript -->\n        </div>\n      </section>\n",
  "painel-financeiro/pagamentos": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-FINANCEIRO | Gestão de Mensalidades & Propinas -->\n<!-- Página independente do módulo: pagamentos.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-pagamentos\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-3 mb-4\">\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Faturamento Total</span>\n                <h4 id=\"finFaturadoCard\" class=\"fw-bold mb-0 text-success\">0 <span class=\"moeda-sufixo\">MZN</span></h4>\n              </div>\n              <div class=\"stat-icon bg-success bg-opacity-10 text-success\"><i class=\"bi bi-cash-stack\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Em Atraso</span>\n                <h4 id=\"finAtrasadoCard\" class=\"fw-bold mb-0 text-danger\">0 <span class=\"moeda-sufixo\">MZN</span></h4>\n              </div>\n              <div class=\"stat-icon bg-danger bg-opacity-10 text-danger\"><i class=\"bi bi-exclamation-circle-fill\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Inadimplência</span>\n                <h4 id=\"finInadimplenciaCard\" class=\"fw-bold mb-0 text-warning\">0%</h4>\n              </div>\n              <div class=\"stat-icon bg-warning bg-opacity-10 text-warning\"><i class=\"bi bi-pie-chart-fill\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Alunos em Dia</span>\n                <h4 id=\"finAdimplentesCard\" class=\"fw-bold mb-0 text-primary\">0%</h4>\n              </div>\n              <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\"><i class=\"bi bi-check-circle\"></i></div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card p-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3\">\n            <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-wallet2 me-2\"></i>Gestão de Propinas & Mensalidades (MZN)</h5>\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarPagamentosPdf()\" title=\"Exportar pagamentos em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarPagamentosExcel()\" title=\"Exportar pagamentos em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarPagamentosWord()\" title=\"Exportar pagamentos em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-outline-primary btn-sm\" onclick=\"modalGerarMensalidadesTurma()\"><i class=\"bi bi-calendar-plus me-1\"></i> Gerar em Lote para Turma</button>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"modalNovoPagamento()\"><i class=\"bi bi-plus-lg me-1\"></i> Nova Cobrança</button>\n            </div>\n          </div>\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Aluno</th>\n                  <th>Descrição</th>\n                  <th>Mês Ref.</th>\n                  <th>Valor (MZN)</th>\n                  <th>Vencimento</th>\n                  <th>Estado</th>\n                  <th class=\"text-end\">Liquidação & Recibo</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaPagamentos\">\n                <tr><td colspan=\"7\" class=\"text-center py-4\">A carregar pagamentos...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-professor/caderneta": "<!-- ===================================================================== -->\r\n<!-- SIGE - PAINEL-PROFESSOR | Caderneta Oficial de Notas -->\r\n<!-- Página independente do módulo: caderneta.html -->\r\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\r\n<!-- ===================================================================== -->\r\n      <section id=\"view-caderneta\" class=\"modulo-view\" style=\"display: none;\">\r\n        <!-- Card de Navegação Sequencial: Classe -> Secção/Área -> Caderneta -->\r\n        <div class=\"card p-4 mb-3 no-print border-0 shadow-sm\">\r\n          <!-- Cabeçalho com Título, Seletor de Professor (para Admins) e Botões de Exportação -->\r\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3\">\r\n            <div>\r\n              <div class=\"d-flex align-items-center gap-2 mb-1\">\r\n                <span class=\"badge bg-primary-subtle text-primary border border-primary-subtle px-2 py-1\"><i class=\"bi bi-journal-bookmark-fill me-1\"></i> Registo de Avaliações Oficiais</span>\r\n                <span id=\"cadernetaBadgePerfil\" class=\"badge bg-light text-dark border\">Caderneta Oficial MEC</span>\r\n              </div>\r\n              <h5 class=\"fw-bold text-dark mb-0\"><i class=\"bi bi-book-half me-2 text-primary\"></i>Caderneta Escolar & Mapa de Avaliação Contínua</h5>\r\n              <p class=\"text-muted small mb-0\">Navegue sequencialmente: <strong>Classe</strong> &rarr; <strong>Secção / Área</strong> &rarr; <strong>Turma da Secção</strong></p>\r\n            </div>\r\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\r\n              <!-- Filtro de Professor visível APENAS para Admins / Direcção -->\r\n              <div id=\"wrapperFiltroProfessorCaderneta\" style=\"display: none;\">\r\n                <div class=\"input-group input-group-sm\" style=\"width: 250px;\">\r\n                  <span class=\"input-group-text bg-light text-muted small\"><i class=\"bi bi-person-badge\"></i></span>\r\n                  <select id=\"cadernetaFiltroProfessor\" class=\"form-select form-select-sm\" onchange=\"aoMudarFiltroProfessorCaderneta(this.value)\">\r\n                    <option value=\"TODOS\">Todos os Professores</option>\r\n                  </select>\r\n                </div>\r\n              </div>\r\n              <button class=\"btn btn-primary btn-sm fw-bold shadow-sm\" onclick=\"modalSalvarNotaCaderneta()\" title=\"Lançar notas de alunos\">\r\n                <i class=\"bi bi-pencil-square me-1\"></i> Lançar Avaliações\r\n              </button>\r\n              <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarCadernetaExcel()\" title=\"Descarregar ficheiro XLSX\">\r\n                <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\r\n              </button>\r\n              <button class=\"btn btn-outline-danger btn-sm\" onclick=\"descarregarCadernetaPdf()\" title=\"Descarregar documento em PDF\">\r\n                <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\r\n              </button>\r\n              <button class=\"btn btn-outline-secondary btn-sm\" onclick=\"imprimirCadernetaOficial()\" title=\"Imprimir em A4 horizontal\">\r\n                <i class=\"bi bi-printer\"></i>\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Barra Unificada de Filtros Inteligentes da Caderneta (Sem excesso de botões) -->\r\n          <div class=\"p-3 bg-light rounded-3 border mb-3\">\r\n            <div class=\"row g-2 align-items-end\">\r\n              <!-- Filtro 1: Classe -->\r\n              <div class=\"col-lg-3 col-md-6\">\r\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\r\n                  <span><i class=\"bi bi-mortarboard-fill me-1 text-primary\"></i> 1. Classe / Grau:</span>\r\n                  <span id=\"contagemClassesCaderneta\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\r\n                </label>\r\n                <select id=\"selectCadernetaClasse\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"aoMudarSelectClasseCaderneta(this.value)\">\r\n                  <!-- Opções de Classes geradas via JS -->\r\n                </select>\r\n              </div>\r\n\r\n              <!-- Filtro 2: Secção / Área -->\r\n              <div class=\"col-lg-3 col-md-6\">\r\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\r\n                  <span><i class=\"bi bi-diagram-2-fill me-1\" style=\"color: #7c3aed;\"></i> 2. Secção / Área:</span>\r\n                  <span id=\"contagemAreasCaderneta\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\r\n                </label>\r\n                <select id=\"selectCadernetaArea\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"aoMudarSelectAreaCaderneta(this.value)\">\r\n                  <!-- Opções de Áreas geradas via JS -->\r\n                </select>\r\n              </div>\r\n\r\n              <!-- Filtro 3: Turma da Secção (Caderneta) -->\r\n              <div class=\"col-lg-3 col-md-6\">\r\n                <label class=\"form-label small fw-bold text-muted mb-1 d-flex justify-content-between\">\r\n                  <span><i class=\"bi bi-collection-fill me-1 text-success\"></i> 3. Turma da Secção:</span>\r\n                  <span id=\"contagemTurmasCaderneta\" class=\"text-muted fw-normal\" style=\"font-size: 0.72rem;\"></span>\r\n                </label>\r\n                <select id=\"selectCadernetaAlocacao\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"aoMudarSelectAlocacaoCaderneta(this.value)\">\r\n                  <!-- Opções de Turmas / Cadernetas geradas via JS -->\r\n                </select>\r\n              </div>\r\n\r\n              <!-- Filtro 4: Trimestre -->\r\n              <div class=\"col-lg-3 col-md-6\">\r\n                <label class=\"form-label small fw-bold text-muted mb-1\">\r\n                  <i class=\"bi bi-calendar3 me-1 text-secondary\"></i> 4. Trimestre:\r\n                </label>\r\n                <select id=\"cadernetaPeriodoSelect\" class=\"form-select form-select-sm bg-white fw-semibold shadow-sm\" onchange=\"destacarTrimestreTabelaCaderneta(this.value)\">\r\n                  <option value=\"TODOS\">Todos os 3 Trimestres</option>\r\n                  <option value=\"1_TRIMESTRE\">1º Trimestre</option>\r\n                  <option value=\"2_TRIMESTRE\">2º Trimestre</option>\r\n                  <option value=\"3_TRIMESTRE\">3º Trimestre</option>\r\n                </select>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Lista Visual de Turmas da Secção: turma por turma para abrir ou visualizar a caderneta ao clicar -->\r\n            <div id=\"containerBotoesTurmasCadernetaWrapper\" class=\"mt-2 pt-2 border-top d-flex align-items-center flex-wrap gap-2\" style=\"display: none !important;\">\r\n              <span class=\"small fw-bold text-muted me-1\"><i class=\"bi bi-collection-play me-1 text-primary\"></i>Turmas da Secção:</span>\r\n              <div id=\"containerBotoesTurmasCaderneta\" class=\"d-inline-flex flex-wrap gap-2\"></div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Barra de Pesquisa Rápida na Caderneta Aberta -->\r\n          <div class=\"row g-2 align-items-center pt-1 border-top\">\r\n            <div class=\"col-md-7\">\r\n              <div class=\"input-group input-group-sm\">\r\n                <span class=\"input-group-text py-1 px-2 bg-white\"><i class=\"bi bi-search\"></i></span>\r\n                <input type=\"search\" id=\"cadernetaPesquisaAluno\" class=\"form-control\" placeholder=\"Pesquisar aluno por nome ou número nesta caderneta...\" oninput=\"filtrarAlunosCaderneta()\">\r\n                <button class=\"btn btn-outline-secondary\" type=\"button\" onclick=\"document.getElementById('cadernetaPesquisaAluno').value=''; filtrarAlunosCaderneta();\">&times;</button>\r\n              </div>\r\n            </div>\r\n            <div class=\"col-md-5 text-end\">\r\n              <!-- Selectors e containers ocultos para retrocompatibilidade com scripts legados -->\r\n              <div id=\"containerCadernetaClasses\" style=\"display: none;\"></div>\r\n              <div id=\"seccaoAreasCaderneta\" style=\"display: none;\"><div id=\"containerCadernetaAreas\"></div><span id=\"cadernetaNomeClasseSelecionada\"></span></div>\r\n              <div id=\"seccaoCadernetasDisponiveis\" style=\"display: none;\"><div id=\"containerCadernetasBotoes\"></div><span id=\"cadernetaNomeAreaSelecionada\"></span></div>\r\n              <select id=\"cadernetaAlocacaoSelect\" style=\"display: none;\"></select>\r\n              <select id=\"cadernetaClasseFilter\" style=\"display: none;\"></select>\r\n              <small class=\"text-muted fw-semibold\" id=\"cadernetaInfoResumo\"></small>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Aviso de Bloqueio do Trimestre -->\r\n          <div id=\"avisoTrimestreBloqueado\" class=\"alert alert-warning mt-3 mb-0 d-none\" role=\"alert\">\r\n            <i class=\"bi bi-lock-fill me-2\"></i>\r\n            <strong>Trimestre Encerrado:</strong> Este trimestre lectivo encontra-se fechado para edição directa. Contacte a Direcção da Escola ou DAP para solicitar autorização de desbloqueio.\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"card p-4 printable-document\" id=\"cadernetaPrintContainer\">\r\n          <!-- Cabeçalho Institucional Oficial (Imagem 2) -->\r\n          <div class=\"border p-3 rounded mb-3 bg-white\" id=\"cadernetaCabecalhoOficial\">\r\n            <div class=\"text-center mb-3\">\r\n              <h6 class=\"fw-bold mb-0 text-uppercase\" id=\"cadHeaderEscola\">REPÚBLICA DE MOÇAMBIQUE</h6>\r\n              <small class=\"text-muted d-block\" id=\"cadHeaderSub\">PROVÍNCIA DE MAPUTO | DISTRITO DE CIDADE DE MAPUTO</small>\r\n              <h5 class=\"fw-bold text-primary mt-1 mb-0\">Mapa de Registo de Avaliações — <span id=\"cadHeaderAno\">2026</span></h5>\r\n            </div>\r\n            <div class=\"row g-2 text-center\" style=\"font-size: 0.8rem;\">\r\n              <div class=\"col-md-3\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Disciplina Lecionada</span>\r\n                  <strong id=\"cadBoxDisciplina\" class=\"text-primary\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-3\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Nome do Professor</span>\r\n                  <strong id=\"cadBoxProfessor\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-3\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Contacto(s) do Prof.</span>\r\n                  <strong id=\"cadBoxContacto\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-3\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Área de Formação</span>\r\n                  <strong id=\"cadBoxArea\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-4\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Turma & Director de Turma</span>\r\n                  <strong id=\"cadBoxTurmaDirector\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-4\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Classe & Turno</span>\r\n                  <strong id=\"cadBoxClasseTurno\">-</strong>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-md-4\">\r\n                <div class=\"p-2 border rounded bg-light\">\r\n                  <span class=\"d-block text-muted small fw-semibold\">Efectivo de Alunos</span>\r\n                  <strong id=\"cadBoxEfectivo\" class=\"text-success\">H: 0 | M: 0 | Total: 0</strong>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Tabela Completa da Caderneta com 3 Trimestres e Estatísticas por Coluna (Imagem 2) -->\r\n          <div class=\"table-responsive\">\r\n            <table class=\"table table-bordered table-hover align-middle text-center small caderneta-tabela\" style=\"min-width: 1300px;\">\r\n              <thead class=\"table-light\">\r\n                <tr>\r\n                  <th rowspan=\"2\" class=\"align-middle\" style=\"width: 35px;\">Nº</th>\r\n                  <th rowspan=\"2\" class=\"align-middle text-start\" style=\"min-width: 140px;\">Nome do Aluno</th>\r\n                  <th rowspan=\"2\" class=\"align-middle text-start\" style=\"min-width: 80px;\">Apelido</th>\r\n                  <th rowspan=\"2\" class=\"align-middle\" style=\"width: 35px;\">Gên</th>\r\n                  <th colspan=\"9\" class=\"bg-primary bg-opacity-10 text-primary fw-bold\">1º TRIMESTRE</th>\r\n                  <th colspan=\"9\" class=\"bg-info bg-opacity-10 text-info fw-bold\">2º TRIMESTRE</th>\r\n                  <th colspan=\"9\" class=\"bg-warning bg-opacity-10 text-dark fw-bold\">3º TRIMESTRE</th>\r\n                  <th rowspan=\"2\" class=\"align-middle bg-success bg-opacity-10 text-success fw-bold\" style=\"width: 55px;\">MFD</th>\r\n                </tr>\r\n                <tr>\r\n                  <!-- 1º Trimestre -->\r\n                  <th style=\"font-size: 0.68rem;\">1ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">2ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">3ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAP</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAS</th>\r\n                  <th style=\"font-size: 0.68rem;\">AT</th>\r\n                  <th style=\"font-size: 0.68rem;\" class=\"bg-light fw-bold\">MT</th>\r\n                  <th style=\"font-size: 0.68rem;\">COM</th>\r\n                  <th style=\"font-size: 0.68rem;\">Obs</th>\r\n                  <!-- 2º Trimestre -->\r\n                  <th style=\"font-size: 0.68rem;\">1ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">2ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">3ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAP</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAS</th>\r\n                  <th style=\"font-size: 0.68rem;\">AT</th>\r\n                  <th style=\"font-size: 0.68rem;\" class=\"bg-light fw-bold\">MT</th>\r\n                  <th style=\"font-size: 0.68rem;\">COM</th>\r\n                  <th style=\"font-size: 0.68rem;\">Obs</th>\r\n                  <!-- 3º Trimestre -->\r\n                  <th style=\"font-size: 0.68rem;\">1ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">2ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">3ª ACS</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAP</th>\r\n                  <th style=\"font-size: 0.68rem;\">MAS</th>\r\n                  <th style=\"font-size: 0.68rem;\">AT</th>\r\n                  <th style=\"font-size: 0.68rem;\" class=\"bg-light fw-bold\">MT</th>\r\n                  <th style=\"font-size: 0.68rem;\">COM</th>\r\n                  <th style=\"font-size: 0.68rem;\">Obs</th>\r\n                </tr>\r\n              </thead>\r\n              <tbody id=\"tabelaCadernetaCorpo\">\r\n                <tr><td colspan=\"32\" class=\"text-center py-4\">Selecione uma turma e disciplina para visualizar a Caderneta Oficial.</td></tr>\r\n              </tbody>\r\n              <tfoot id=\"tabelaCadernetaRodape\" class=\"table-light fw-semibold\" style=\"font-size: 0.72rem;\">\r\n                <!-- Linhas calculadas dinamicamente com estatística por coluna -->\r\n              </tfoot>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </section>\r\n",
  "painel-professor/director-turma": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-PROFESSOR | Conselho de Avaliação / DT -->\n<!-- Página independente do módulo: director-turma.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-director-turma\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4 no-print mb-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2\">\n            <div>\n              <h5 class=\"fw-bold mb-1\"><i class=\"bi bi-person-workspace text-warning me-2\"></i>Painel Oficial do Director de Turma</h5>\n              <p class=\"text-muted small mb-0\">Gestão académica e administrativa da sua turma atribuída: Pauta Geral e Acta Oficial do Conselho de Avaliação.</p>\n            </div>\n            <div class=\"d-flex align-items-center gap-2\">\n              <label class=\"form-label small fw-bold mb-0 text-nowrap\">Turma Atribuída:</label>\n              <select id=\"dtTurmaSelect\" class=\"form-select form-select-sm\" style=\"min-width: 260px;\" onchange=\"aoSelecionarTurmaDT(this.value)\"></select>\n            </div>\n          </div>\n\n          <!-- Parâmetros da Sessão do Conselho de Avaliação (Acordeão recolhível) -->\n          <div class=\"accordion mb-3\" id=\"accordionParamsConselho\">\n            <div class=\"accordion-item border rounded\">\n              <h2 class=\"accordion-header\" id=\"headingConselho\">\n                <button class=\"accordion-button collapsed py-2 small fw-semibold bg-light\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseConselho\">\n                  <i class=\"bi bi-pencil-square text-primary me-2\"></i> Configurar Dados da Sessão do Conselho de Avaliação (Presidente, Datas e Horários)\n                </button>\n              </h2>\n              <div id=\"collapseConselho\" class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionParamsConselho\">\n                <div class=\"accordion-body p-3 bg-white\">\n                  <form id=\"formParamsConselho\" onsubmit=\"event.preventDefault(); salvarParametrosSessaoDT();\">\n                    <div class=\"row g-3\">\n                      <!-- 1º Trimestre -->\n                      <div class=\"col-md-4 border-end\">\n                        <div class=\"fw-bold text-primary small mb-2\"><i class=\"bi bi-1-circle me-1\"></i> Iº Trimestre</div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Presidente do Conselho</label>\n                          <input type=\"text\" id=\"dtPresidenteT1\" class=\"form-control form-control-sm\" value=\"\" placeholder=\"Deixe em branco até à realização\">\n                        </div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Data da Realização</label>\n                          <input type=\"date\" id=\"dtDataT1\" class=\"form-control form-control-sm\" value=\"\">\n                        </div>\n                        <div class=\"row g-1\">\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Início (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHIni1\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMIni1\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Término (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHFim1\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMFim1\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n\n                      <!-- 2º Trimestre -->\n                      <div class=\"col-md-4 border-end\">\n                        <div class=\"fw-bold text-primary small mb-2\"><i class=\"bi bi-2-circle me-1\"></i> IIº Trimestre</div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Presidente do Conselho</label>\n                          <input type=\"text\" id=\"dtPresidenteT2\" class=\"form-control form-control-sm\" value=\"\" placeholder=\"Deixe em branco até à realização\">\n                        </div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Data da Realização</label>\n                          <input type=\"date\" id=\"dtDataT2\" class=\"form-control form-control-sm\" value=\"\">\n                        </div>\n                        <div class=\"row g-1\">\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Início (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHIni2\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMIni2\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Término (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHFim2\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMFim2\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n\n                      <!-- 3º Trimestre -->\n                      <div class=\"col-md-4\">\n                        <div class=\"fw-bold text-primary small mb-2\"><i class=\"bi bi-3-circle me-1\"></i> IIIº Trimestre</div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Presidente do Conselho</label>\n                          <input type=\"text\" id=\"dtPresidenteT3\" class=\"form-control form-control-sm\" value=\"\" placeholder=\"Deixe em branco até à realização\">\n                        </div>\n                        <div class=\"mb-2\">\n                          <label class=\"form-label very-small text-muted mb-0\">Data da Realização</label>\n                          <input type=\"date\" id=\"dtDataT3\" class=\"form-control form-control-sm\" value=\"\">\n                        </div>\n                        <div class=\"row g-1\">\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Início (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHIni3\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMIni3\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                          <div class=\"col-6\">\n                            <label class=\"form-label very-small text-muted mb-0\">Término (HH:MM)</label>\n                            <div class=\"d-flex gap-1\">\n                              <input type=\"text\" id=\"dtHFim3\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"HH\" maxlength=\"2\">\n                              <input type=\"text\" id=\"dtMFim3\" class=\"form-control form-control-sm text-center\" value=\"\" placeholder=\"MM\" maxlength=\"2\">\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                    <div class=\"text-end mt-3\">\n                      <button type=\"button\" class=\"btn btn-sm btn-outline-secondary me-2\" onclick=\"limparParametrosSessaoDT()\">\n                        <i class=\"bi bi-eraser me-1\"></i> Limpar / Deixar em Branco\n                      </button>\n                      <button type=\"submit\" class=\"btn btn-sm btn-primary\">\n                        <i class=\"bi bi-save me-1\"></i> Gravar Parâmetros do Conselho\n                      </button>\n                    </div>\n                  </form>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Abas do Director de Turma: Pauta Geral vs Acta do Conselho -->\n          <ul class=\"nav nav-tabs mb-3\">\n            <li class=\"nav-item\">\n              <a class=\"nav-link fw-bold active\" id=\"dtTabPautaBtn\" href=\"#\" onclick=\"alternarAbaDT('pauta')\">\n                <i class=\"bi bi-table me-1\"></i> Pauta Geral da Turma\n              </a>\n            </li>\n            <li class=\"nav-item\">\n              <a class=\"nav-link fw-bold\" id=\"dtTabActaBtn\" href=\"#\" onclick=\"alternarAbaDT('acta')\">\n                <i class=\"bi bi-file-earmark-text me-1\"></i> Acta Oficial do Conselho de Avaliação\n              </a>\n            </li>\n          </ul>\n        </div>\n\n        <!-- Conteúdo do Documento Activo do Director de Turma -->\n        <div class=\"card p-4 printable-document bg-white\" id=\"dtDocumentoContainer\">\n          <div class=\"text-center py-4 text-muted\">Selecione uma turma para visualizar a pauta e acta.</div>\n        </div>\n      </section>\n",
  "painel-professor/estatisticas-aproveitamento": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-PROFESSOR | Estatística das Minhas Turmas -->\n<!-- Página independente do módulo: estatisticas-aproveitamento.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-estatisticas-aproveitamento\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4 no-print mb-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2\">\n            <div>\n              <h5 class=\"fw-bold mb-1\"><i class=\"bi bi-bar-chart-line-fill text-success me-2\"></i>Estatística do Aproveitamento Pedagógico Escolar</h5>\n              <p class=\"text-muted small mb-0\">Monitoramento oficial do rendimento escolar por Turma, por Classe (7ª a 12ª), Geral da Escola e por Disciplina.</p>\n            </div>\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\n              <div>\n                <label class=\"form-label very-small text-muted mb-0\">Ano Lectivo</label>\n                <div class=\"sige-seletor-ano-box d-flex align-items-center\">\n                  <select id=\"statAnoFiltro\" class=\"form-select form-select-sm sige-select-ano-lectivo\" onchange=\"carregarEstatisticasAproveitamento()\">\n                    <option value=\"\">-- Escolha ano Lectivo --</option>\n                  </select>\n                  <button type=\"button\" class=\"btn btn-sm btn-sige-buscar-ano\" onclick=\"carregarEstatisticasAproveitamento()\">\n                    Buscar <i class=\"bi bi-search ms-1\"></i>\n                  </button>\n                </div>\n              </div>\n              <div>\n                <label class=\"form-label very-small text-muted mb-0\">Período / Trimestre</label>\n                <select id=\"statPeriodoFiltro\" class=\"form-select form-select-sm\" onchange=\"carregarEstatisticasAproveitamento()\">\n                  <option value=\"GLOBAL\" selected>Anual / Global (MFD)</option>\n                  <option value=\"T1\">1º Trimestre</option>\n                  <option value=\"T2\">2º Trimestre</option>\n                  <option value=\"T3\">3º Trimestre</option>\n                </select>\n              </div>\n              <div class=\"d-flex gap-1 align-self-end\">\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"carregarEstatisticasAproveitamento()\" title=\"Atualizar dados\">\n                  <i class=\"bi bi-arrow-repeat me-1\"></i> Visualizar\n                </button>\n                <button class=\"btn btn-primary btn-sm\" onclick=\"window.print()\" title=\"Imprimir Relatório\">\n                  <i class=\"bi bi-printer me-1\"></i> Imprimir\n                </button>\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"descarregarEstatisticasPdf()\" title=\"Descarregar documento em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarEstatisticasExcel()\" title=\"Descarregar ficheiro Excel (XLSX)\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarEstatisticasWord()\" title=\"Descarregar documento em Word (DOCX)\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n            </div>\n          </div>\n\n          <!-- Indicadores Globais Rápidos (KPIs) -->\n          <div class=\"row g-3 mb-2\" id=\"kpiEstatisticasContainer\">\n            <div class=\"col-md-3\">\n              <div class=\"stat-card p-3 border rounded bg-light\">\n                <span class=\"text-muted very-small text-uppercase fw-semibold\">Taxa de Aprovação Global</span>\n                <h4 id=\"statKpiAprovacao\" class=\"fw-bold mb-0 text-success\">0%</h4>\n                <small class=\"text-muted\" id=\"statKpiAprovacaoSub\">0 Aprovados de 0 Avaliados</small>\n              </div>\n            </div>\n            <div class=\"col-md-3\">\n              <div class=\"stat-card p-3 border rounded bg-light\">\n                <span class=\"text-muted very-small text-uppercase fw-semibold\">Taxa de Reprovação</span>\n                <h4 id=\"statKpiReprovacao\" class=\"fw-bold mb-0 text-danger\">0%</h4>\n                <small class=\"text-muted\" id=\"statKpiReprovacaoSub\">0 Alunos não transitam</small>\n              </div>\n            </div>\n            <div class=\"col-md-3\">\n              <div class=\"stat-card p-3 border rounded bg-light\">\n                <span class=\"text-muted very-small text-uppercase fw-semibold\">Efectivo Avaliado</span>\n                <h4 id=\"statKpiAvaliados\" class=\"fw-bold mb-0 text-primary\">0</h4>\n                <small class=\"text-muted\" id=\"statKpiAvaliadosSub\">0 M | 0 F</small>\n              </div>\n            </div>\n            <div class=\"col-md-3\">\n              <div class=\"stat-card p-3 border rounded bg-light\">\n                <span class=\"text-muted very-small text-uppercase fw-semibold\">Total de Turmas Activas</span>\n                <h4 id=\"statKpiTurmas\" class=\"fw-bold mb-0 text-dark\">0</h4>\n                <small class=\"text-muted\" id=\"statKpiTurmasSub\">Classes do Ensino Secundário</small>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Documento Renderizado de Estatísticas (Para visualização e impressão) -->\n        <div class=\"card p-4 printable-document bg-white\" id=\"containerEstatisticasDocumento\">\n          <div class=\"text-center py-4\">\n            <div class=\"spinner-border text-primary\"></div>\n            <p class=\"small text-muted mt-2\">A carregar estatísticas pedagógicas da escola...</p>\n          </div>\n        </div>\n      </section>\n",
  "painel-professor/material-escolar": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-PROFESSOR | Material Didático & Escolar -->\n<!-- Página independente do módulo: material-escolar.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-material-escolar\" class=\"modulo-view\" style=\"display: none;\">\n        <!-- Cabeçalho do Painel com Ações -->\n        <div class=\"card p-4 mb-4 border-0 shadow-sm text-white\" style=\"background: linear-gradient(135deg, #1e3a8a 0%, #2563eb 100%);\">\n          <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3\">\n            <div>\n              <h4 class=\"fw-bold mb-1\"><i class=\"bi bi-book-half me-2\"></i>Material Escolar & Recursos Didáticos</h4>\n              <p class=\"mb-0 text-white-50 small\">\n                Navegue pelas classes de 1ª a 12ª Classe, consulte, descarregue manuais oficiais ou carregue novos ficheiros e livros da instituição.\n              </p>\n            </div>\n            <div class=\"d-flex gap-2\">\n              <button class=\"btn btn-light fw-bold text-primary shadow-sm\" onclick=\"modalCarregarMaterialEscolar()\" id=\"btnCarregarMaterial\">\n                <i class=\"bi bi-cloud-arrow-up-fill me-1\"></i> Carregar / Importar Material\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- Barra Unificada de Filtros de Materiais Escolares (Sem excesso de botões) -->\n        <div class=\"card p-3 mb-4 shadow-sm border-0\">\n          <div class=\"row g-2 align-items-end\">\n            <div class=\"col-md-3 col-sm-6\">\n              <label class=\"form-label small fw-bold text-muted mb-1\">\n                <i class=\"bi bi-mortarboard-fill me-1 text-primary\"></i> 1. Classe / Grau:\n              </label>\n              <select id=\"filtroMaterialClasseSelect\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"selecionarClasseMaterial(this.value)\">\n                <option value=\"TODAS\">Todas as Classes / Níveis</option>\n              </select>\n            </div>\n            <div class=\"col-md-3 col-sm-6\">\n              <label class=\"form-label small fw-bold text-muted mb-1\">\n                <i class=\"bi bi-tag me-1 text-info\"></i> 2. Tipo de Material:\n              </label>\n              <select id=\"filtroMaterialTipo\" class=\"form-select form-select-sm fw-semibold bg-white shadow-sm\" onchange=\"filtrarMateriaisEscolares()\">\n                <option value=\"\">Todos os Tipos (Manuais, Fichas...)</option>\n                <option value=\"MANUAL\">Livros / Manuais Oficiais</option>\n                <option value=\"FICHA\">Fichas de Exercícios / Avaliação</option>\n                <option value=\"GUIA\">Guias de Correcção / Apoio</option>\n                <option value=\"APOSTILA\">Apostilas & Resumos</option>\n                <option value=\"OUTRO\">Outros Materiais</option>\n              </select>\n            </div>\n            <div class=\"col-md-4 col-sm-8\">\n              <label class=\"form-label small fw-bold text-muted mb-1\">\n                <i class=\"bi bi-search me-1 text-secondary\"></i> 3. Pesquisa:\n              </label>\n              <div class=\"input-group input-group-sm\">\n                <span class=\"input-group-text bg-white\"><i class=\"bi bi-search\"></i></span>\n                <input type=\"text\" id=\"filtroMaterialBusca\" class=\"form-control form-control-sm bg-white\" placeholder=\"Título, disciplina ou descrição...\" oninput=\"filtrarMateriaisEscolares()\">\n                <button class=\"btn btn-outline-secondary\" type=\"button\" onclick=\"document.getElementById('filtroMaterialBusca').value=''; filtrarMateriaisEscolares();\" title=\"Limpar pesquisa\">&times;</button>\n              </div>\n            </div>\n            <div class=\"col-md-2 col-sm-4 text-end\">\n              <div id=\"containerBotoesClassesMateriais\" style=\"display: none;\"></div>\n              <span class=\"badge bg-primary-subtle text-primary fw-semibold d-block text-truncate mb-1\" id=\"badgeClasseAtiva\">Todas as Classes</span>\n              <small class=\"text-muted d-block\" id=\"contadorMateriaisEncontrados\">0 materiais</small>\n            </div>\n          </div>\n        </div>\n\n        <!-- Lista / Grelha de Materiais da Classe -->\n        <div class=\"row g-4\" id=\"grelhaMateriaisEscolares\">\n          <div class=\"col-12 text-center py-5 text-muted\">\n            <i class=\"bi bi-folder2-open display-4 d-block mb-3 opacity-50\"></i>\n            A carregar materiais da classe...\n          </div>\n        </div>\n      </section>\n",
  "painel-professor/pautas": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-PROFESSOR | Pautas & Actas das Minhas Turmas -->\n<!-- Página independente do módulo: pautas.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-pautas\" class=\"modulo-view\" style=\"display: none;\">\n        <!-- Barra Superior de Controlo e Navegação entre Pauta e Acta -->\n        <div class=\"card p-4 mb-4 no-print\">\n          <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3\">\n            <div class=\"d-flex align-items-center gap-3\">\n              <div>\n                <label class=\"form-label small fw-semibold mb-1\">Classe</label>\n                <select id=\"pautaClasseFilter\" class=\"form-select form-select-sm\" style=\"min-width: 130px;\" onchange=\"filtrarTurmasPautaPorClasse()\">\n                  <option value=\"\">Todas as Classes / Níveis</option>\n                </select>\n              </div>\n              <div>\n                <label class=\"form-label small fw-semibold mb-1\">Turma</label>\n                <select id=\"pautaTurmaSelect\" class=\"form-select form-select-sm\" style=\"min-width: 230px;\" onchange=\"alternarVisualizacaoPautaTurma()\">\n                  <option value=\"\">A carregar turmas...</option>\n                </select>\n              </div>\n              <div>\n                <label class=\"form-label small fw-semibold mb-1\">Ano Lectivo</label>\n                <div class=\"sige-seletor-ano-box d-flex align-items-center\">\n                  <select id=\"pautaAnoSelect\" class=\"form-select form-select-sm sige-select-ano-lectivo\" onchange=\"aoClicarBuscarPautaAno()\">\n                    <option value=\"\">-- Escolha ano Lectivo --</option>\n                  </select>\n                  <button type=\"button\" class=\"btn btn-sm btn-sige-buscar-ano\" onclick=\"aoClicarBuscarPautaAno()\">\n                    Buscar <i class=\"bi bi-search ms-1\"></i>\n                  </button>\n                </div>\n              </div>\n              <div>\n                <label class=\"form-label small fw-semibold mb-1\">Orientação da Página</label>\n                <div class=\"input-group input-group-sm\">\n                  <select id=\"pautaOrientacaoSelect\" class=\"form-select form-select-sm\" style=\"min-width: 145px;\" onchange=\"aoMudarOrientacaoPauta(this.value)\">\n                    <option value=\"landscape\" selected>Horizontal (Oficial Pauta)</option>\n                    <option value=\"portrait\">Vertical (Retrato A4)</option>\n                  </select>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"d-flex gap-2\">\n              <div class=\"btn-group btn-group-sm\" role=\"group\">\n                <button type=\"button\" class=\"btn btn-outline-primary active\" id=\"btnAbaPauta\" onclick=\"mudarSubAbaPauta('pauta')\">\n                  <i class=\"bi bi-table me-1\"></i> Pauta Geral da Turma\n                </button>\n                <button type=\"button\" class=\"btn btn-outline-primary\" id=\"btnAbaActa\" onclick=\"mudarSubAbaPauta('acta')\">\n                  <i class=\"bi bi-journal-text me-1\"></i> Acta do Conselho de Avaliação\n                </button>\n              </div>\n              <button class=\"btn btn-outline-secondary btn-sm\" onclick=\"modalGerarPauta()\">\n                <i class=\"bi bi-plus-circle me-1\"></i> Consolidar\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- SUB-ABA 1: PAUTA GERAL DA TURMA (TODAS AS DISCIPLINAS LADO A LADO) (Imagem 3) -->\n        <div id=\"subViewPautaGeral\" class=\"card p-4 printable-document\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 border-bottom pb-3\">\n            <div>\n              <h5 class=\"fw-bold mb-0\" id=\"pautaGeralTitulo\">Pauta Oficial de Aproveitamento Pedagógico</h5>\n              <small class=\"text-muted\" id=\"pautaGeralSubtitulo\">Ano Lectivo: 2026 | Critério Oficial MEC Aplicado</small>\n            </div>\n            <div class=\"d-flex gap-2 no-print\">\n              <button class=\"btn btn-success btn-sm\" onclick=\"exportarPautaGeralExcel()\" title=\"Descarregar ficheiro XLSX (Excel)\">\n                <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel (.xlsx)\n              </button>\n              <button class=\"btn btn-danger btn-sm\" onclick=\"descarregarPautaGeralPdf()\" title=\"Descarregar documento em PDF\">\n                <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF (.pdf)\n              </button>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"imprimirPautaGeralOficial()\" title=\"Imprimir em A4 horizontal\">\n                <i class=\"bi bi-printer me-1\"></i> Imprimir\n              </button>\n            </div>\n          </div>\n\n          <!-- Grelha da Pauta Geral renderizada dinamicamente -->\n          <div class=\"table-responsive\" id=\"containerTabelaPautaGeral\">\n            <p class=\"text-center py-4 text-muted\">Selecione uma turma acima para gerar a pauta geral.</p>\n          </div>\n        </div>\n\n        <!-- SUB-ABA 2: ACTA DO CONSELHO DE AVALIAÇÃO / ESTATÍSTICA DA TURMA (Imagem 1) -->\n        <div id=\"subViewActaConselho\" class=\"card p-5 printable-document d-none\" style=\"background: #fff;\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 no-print\">\n            <div>\n              <button class=\"btn btn-outline-secondary btn-sm\" onclick=\"modalConfigurarSessaoActa()\">\n                <i class=\"bi bi-sliders me-1\"></i> Configurar Dados da Sessão do Conselho\n              </button>\n            </div>\n            <div class=\"d-flex gap-2\">\n              <button class=\"btn btn-success btn-sm\" onclick=\"exportarActaConselhoExcel()\" title=\"Descarregar ficheiro XLSX (Excel)\">\n                <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel (.xlsx)\n              </button>\n              <button class=\"btn btn-danger btn-sm\" onclick=\"descarregarActaConselhoPdf()\" title=\"Descarregar documento em PDF\">\n                <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF (.pdf)\n              </button>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"imprimirActaConselhoOficial()\" title=\"Imprimir em A4 horizontal\">\n                <i class=\"bi bi-printer me-1\"></i> Imprimir\n              </button>\n            </div>\n          </div>\n\n          <!-- Conteúdo da Acta renderizado fielmente à Imagem 1 -->\n          <div id=\"containerActaConselhoCorpo\">\n            <p class=\"text-center py-4 text-muted\">Selecione uma turma acima para gerar a acta do conselho.</p>\n          </div>\n        </div>\n      </section>\n",
  "painel-professor/professor-perfil": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-PROFESSOR | Meu Perfil Docente -->\n<!-- Página independente do módulo: professor-perfil.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-professor-perfil\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4 mb-4\">\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3 border-bottom pb-3\">\n            <div>\n              <h5 class=\"fw-bold mb-0 text-primary\"><i class=\"bi bi-person-badge-fill me-2\"></i>Perfil Individual do Docente</h5>\n              <small class=\"text-muted\">Consulte os seus dados cadastrais, turmas, disciplinas lecionadas e altere a sua palavra-passe</small>\n            </div>\n            <div class=\"d-flex gap-2\">\n              <button class=\"btn btn-primary btn-sm fw-semibold\" onclick=\"modalRedefinirMinhaSenha()\">\n                <i class=\"bi bi-key-fill me-1\"></i> Alterar a Minha Senha\n              </button>\n              <button class=\"btn btn-outline-primary btn-sm\" onclick=\"carregarPerfilDocenteIndividual()\">\n                <i class=\"bi bi-arrow-clockwise me-1\"></i> Actualizar\n              </button>\n            </div>\n          </div>\n\n          <div class=\"row g-4\" id=\"perfilDocenteConteudo\">\n            <div class=\"col-12 text-center py-4\">\n              <div class=\"spinner-border text-primary\"></div>\n              <p class=\"small text-muted mt-2\">A carregar o seu perfil...</p>\n            </div>\n          </div>\n        </div>\n      </section>\n",
  "painel-superadmin/acessos": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-SUPERADMIN | Auditoria de Acessos SaaS -->\n<!-- Página independente do módulo: acessos.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-acessos\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2\">\n            <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-shield-check me-2\"></i>Auditoria de Acessos e Logs de Segurança</h5>\n            <div class=\"btn-group btn-group-sm\">\n              <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarAcessosPdf()\" title=\"Exportar logs em PDF\">\n                <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n              </button>\n              <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarAcessosExcel()\" title=\"Exportar logs em Excel\">\n                <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n              </button>\n              <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarAcessosWord()\" title=\"Exportar logs em Word\">\n                <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n              </button>\n            </div>\n          </div>\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Data/Hora</th>\n                  <th>Utilizador</th>\n                  <th>Endereço IP</th>\n                  <th>Navegador / Dispositivo</th>\n                  <th>Evento de Segurança</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaLogsAcesso\">\n                <tr><td colspan=\"5\" class=\"text-center py-4\">A carregar logs...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-superadmin/saas": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-SUPERADMIN | Gestão de Escolas & Planos SaaS -->\n<!-- Página independente do módulo: saas.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-saas\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"row g-3 mb-4\">\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">MRR (Mensal Recorrente)</span>\n                <h3 id=\"saasMRR\" class=\"fw-bold mb-0 text-success\">0 <span class=\"moeda-sufixo\">MZN</span></h3>\n                <small class=\"text-muted\">Valor contratado mensal</small>\n              </div>\n              <div class=\"stat-icon bg-success bg-opacity-10 text-success\"><i class=\"bi bi-cash-stack\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">ARR (Anual Projetado)</span>\n                <h3 id=\"saasARR\" class=\"fw-bold mb-0 text-primary\">0 <span class=\"moeda-sufixo\">MZN</span></h3>\n                <small class=\"text-muted\">Projeção anual de receita</small>\n              </div>\n              <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\"><i class=\"bi bi-graph-up-arrow\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Taxa de Churn</span>\n                <h3 id=\"saasChurn\" class=\"fw-bold mb-0 text-danger\">0%</h3>\n                <small class=\"text-muted\">Escolas suspensas/expiradas</small>\n              </div>\n              <div class=\"stat-icon bg-danger bg-opacity-10 text-danger\"><i class=\"bi bi-person-x-fill\"></i></div>\n            </div>\n          </div>\n          <div class=\"col-md-3\">\n            <div class=\"stat-card\">\n              <div>\n                <span class=\"text-muted small text-uppercase fw-semibold\">Instituições de Ensino</span>\n                <h3 id=\"saasTotalEscolas\" class=\"fw-bold mb-0 text-dark\">0</h3>\n                <small class=\"text-success\"><span id=\"saasEscolasAtivas\">0</span> ativas</small> | \n                <small class=\"text-danger\"><span id=\"saasEscolasExpiradas\">0</span> expiradas</small>\n              </div>\n              <div class=\"stat-icon bg-warning bg-opacity-10 text-warning\"><i class=\"bi bi-buildings\"></i></div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Tabela de Escolas Cadastradas -->\n        <div class=\"card p-4 mb-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3\">\n            <div>\n              <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-buildings me-2\"></i>Gestão de Escolas (Tenants)</h5>\n              <small class=\"text-muted\">Cadastre, edite prazos, active ou desactive instituições de ensino.</small>\n            </div>\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarRelatorioSaasPdf()\" title=\"Exportar relatório SaaS em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarRelatorioSaasExcel()\" title=\"Exportar relatório SaaS em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarRelatorioSaasWord()\" title=\"Exportar relatório SaaS em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"modalCadastrarEscolaSuperAdmin()\">\n                <i class=\"bi bi-plus-lg me-1\"></i> Cadastrar Nova Escola\n              </button>\n              <button class=\"btn btn-outline-secondary btn-sm\" onclick=\"executarCronVerificacaoManual()\">\n                <i class=\"bi bi-arrow-repeat me-1\"></i> Rodar Verificação de Expiração\n              </button>\n            </div>\n          </div>\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Escola</th>\n                  <th>Província / Distrito</th>\n                  <th>NUIT</th>\n                  <th>Plano & Contrato</th>\n                  <th>Validade</th>\n                  <th>Estado</th>\n                  <th>Alunos/Profs</th>\n                  <th class=\"text-end\">Acções</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaSaasEscolas\">\n                <tr><td colspan=\"8\" class=\"text-center py-4\">A carregar escolas...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- Tabela de Gestão de Preços dos Planos de Assinatura -->\n        <div class=\"card p-4\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3\">\n            <div>\n              <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-tags-fill me-2 text-warning\"></i>Planos de Assinatura & Preços (MZN)</h5>\n              <small class=\"text-muted\">Altere o valor do contrato para novos períodos de adesão (Mensal, Trimestral, Semestral e Anual).</small>\n            </div>\n          </div>\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Plano</th>\n                  <th>Duração (Dias)</th>\n                  <th>Preço Vigente (MZN)</th>\n                  <th>Descrição Oficial</th>\n                  <th class=\"text-end\">Editar Valor</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaSaasPlanos\">\n                <tr><td colspan=\"5\" class=\"text-center py-4\">A carregar planos...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n",
  "painel-superadmin/usuarios-senhas": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-SUPERADMIN | Cofre de Credenciais Master -->\n<!-- Página independente do módulo: usuarios-senhas.html -->\n<!-- Isolamento estrito de nível: Acesso restrito a este painel -->\n<!-- ===================================================================== -->\n      <section id=\"view-usuarios-senhas\" class=\"modulo-view\" style=\"display: none;\">\n        <div class=\"card p-4\">\n          <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3 mb-3 border-bottom pb-3\">\n            <div>\n              <h5 class=\"fw-bold mb-0 text-warning text-dark\"><i class=\"bi bi-shield-lock-fill text-warning me-2\"></i>Cofre Restrito de Utilizadores e Palavras-passe</h5>\n              <small class=\"text-muted\">Acesso restrito à Direcção da Escola e SuperAdmin para gestão de códigos de acesso e credenciais</small>\n            </div>\n            <div class=\"d-flex gap-2\">\n              <input type=\"text\" id=\"filtroUsuarioCofre\" class=\"form-control form-control-sm\" placeholder=\"Pesquisar por código, nome ou e-mail...\" oninput=\"filtrarUsuariosCofre()\" style=\"width: 260px;\">\n              <select id=\"filtroRoleCofre\" class=\"form-select form-select-sm\" onchange=\"filtrarUsuariosCofre()\" style=\"width: 170px;\">\n                <option value=\"\">Todos os Perfis</option>\n                <option value=\"ADMIN_ESCOLA\">Gabinete do Director (GD)</option>\n                <option value=\"DIRECTOR_ESCOLA\">Director da Escola (GD)</option>\n                <option value=\"DAP\">Direcção Pedagógica (DP)</option>\n                <option value=\"CHEFE_SECRETARIA\">Secretaria (SECR)</option>\n                <option value=\"PROFESSOR\">Professores (PR)</option>\n                <option value=\"ALUNO\">Alunos</option>\n              </select>\n              <div class=\"btn-group btn-group-sm\">\n                <button class=\"btn btn-outline-danger btn-sm\" onclick=\"exportarUsuariosPdf()\" title=\"Exportar utilizadores em PDF\">\n                  <i class=\"bi bi-file-earmark-pdf me-1\"></i> PDF\n                </button>\n                <button class=\"btn btn-outline-success btn-sm\" onclick=\"exportarUsuariosExcel()\" title=\"Exportar utilizadores em Excel\">\n                  <i class=\"bi bi-file-earmark-excel me-1\"></i> Excel\n                </button>\n                <button class=\"btn btn-outline-primary btn-sm\" onclick=\"exportarUsuariosWord()\" title=\"Exportar utilizadores em Word\">\n                  <i class=\"bi bi-file-earmark-word me-1\"></i> Word\n                </button>\n              </div>\n              <button class=\"btn btn-primary btn-sm\" onclick=\"carregarCofreUsuarios()\">\n                <i class=\"bi bi-arrow-clockwise me-1\"></i> Actualizar\n              </button>\n            </div>\n          </div>\n\n          <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle\">\n              <thead class=\"table-light\">\n                <tr>\n                  <th>Código de Acesso</th>\n                  <th>Nome Completo</th>\n                  <th>E-mail de Acesso</th>\n                  <th>Perfil / Órgão</th>\n                  <th>Telefone</th>\n                  <th>Último Acesso</th>\n                  <th>Estado</th>\n                  <th class=\"text-end\">Acções</th>\n                </tr>\n              </thead>\n              <tbody id=\"tabelaCofreUsuariosCorpo\">\n                <tr><td colspan=\"8\" class=\"text-center py-4\">A carregar utilizadores da escola...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n"
,
  "painel-superadmin/pagamentos-saas": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-SUPERADMIN | Controlo de Assinaturas & Pagamentos SaaS -->\n<!-- Página independente do módulo: pagamentos-saas.html -->\n<!-- Moeda Oficial: MZN (Metical) | Fuso Horário: Africa/Maputo -->\n<!-- ===================================================================== -->\n<section id=\"view-pagamentos-saas\" class=\"modulo-view\" style=\"display: none;\">\n  <!-- KPIs e Resumo Geral -->\n  <div class=\"row g-3 mb-4\">\n    <div class=\"col-md-3\">\n      <div class=\"stat-card\">\n        <div>\n          <span class=\"text-muted small text-uppercase fw-semibold\">Valor em Dívida</span>\n          <h3 id=\"saasValorDivida\" class=\"fw-bold mb-0 text-danger\">0 <span class=\"moeda-sufixo\">MZN</span></h3>\n          <small class=\"text-muted\">Faturas pendentes e em atraso</small>\n        </div>\n        <div class=\"stat-icon bg-danger bg-opacity-10 text-danger\"><i class=\"bi bi-cash-stack\"></i></div>\n      </div>\n    </div>\n    <div class=\"col-md-3\">\n      <div class=\"stat-card\">\n        <div>\n          <span class=\"text-muted small text-uppercase fw-semibold\">Receita do Mês</span>\n          <h3 id=\"saasReceitaMes\" class=\"fw-bold mb-0 text-success\">0 <span class=\"moeda-sufixo\">MZN</span></h3>\n          <small class=\"text-muted\">Pagamentos liquidados no mês</small>\n        </div>\n        <div class=\"stat-icon bg-success bg-opacity-10 text-success\"><i class=\"bi bi-graph-up-arrow\"></i></div>\n      </div>\n    </div>\n    <div class=\"col-md-3\">\n      <div class=\"stat-card\">\n        <div>\n          <span class=\"text-muted small text-uppercase fw-semibold\">Comprovativos por Validar</span>\n          <h3 id=\"saasComprovativosPendentes\" class=\"fw-bold mb-0 text-warning\">0</h3>\n          <small class=\"text-muted\">Aguardam validação na fila</small>\n        </div>\n        <div class=\"stat-icon bg-warning bg-opacity-10 text-warning\"><i class=\"bi bi-receipt\"></i></div>\n      </div>\n    </div>\n    <div class=\"col-md-3\">\n      <div class=\"stat-card\">\n        <div>\n          <span class=\"text-muted small text-uppercase fw-semibold\">Instituições Monitorizadas</span>\n          <h3 id=\"saasTotalInstituicoes\" class=\"fw-bold mb-0 text-dark\">0</h3>\n          <small class=\"text-muted\" id=\"saasResumoEstados\">0 Activas | 0 Atraso | 0 Suspensas</small>\n        </div>\n        <div class=\"stat-icon bg-primary bg-opacity-10 text-primary\"><i class=\"bi bi-buildings\"></i></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Fila de Validação de Pagamentos Pendentes -->\n  <div class=\"card p-4 mb-4 border-warning shadow-sm\" id=\"cardFilaComprovativos\" style=\"display: none;\">\n    <div class=\"d-flex justify-content-between align-items-center mb-3\">\n      <div>\n        <h5 class=\"fw-bold mb-0 text-warning\"><i class=\"bi bi-hourglass-split me-2\"></i>Fila de Comprovativos Enviados pelas Instituições</h5>\n        <small class=\"text-muted\">Valide ou rejeite os pagamentos submetidos para reactivação e liquidação das faturas.</small>\n      </div>\n    </div>\n    <div class=\"table-responsive\">\n      <table class=\"table table-hover align-middle\">\n        <thead class=\"table-light\">\n          <tr>\n            <th>Instituição</th>\n            <th>Fatura / Período</th>\n            <th>Método</th>\n            <th>Referência</th>\n            <th>Valor (MZN)</th>\n            <th>Data de Envio</th>\n            <th>Comprovativo</th>\n            <th class=\"text-end\">Decisão</th>\n          </tr>\n        </thead>\n        <tbody id=\"tabelaPagamentosPendentes\">\n          <tr><td colspan=\"8\" class=\"text-center py-3\">A carregar fila de comprovativos...</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- Gestão de Assinaturas de Todas as Instituições -->\n  <div class=\"card p-4 mb-4\">\n    <div class=\"d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2\">\n      <div>\n        <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-shield-check me-2\"></i>Controlo de Assinaturas e Prazos SaaS</h5>\n        <small class=\"text-muted\">Acompanhe estados, configure regras de corte, tolerâncias e efectue prorrogações justificadas.</small>\n      </div>\n      <div class=\"d-flex gap-2 align-items-center flex-wrap\">\n        <button class=\"btn btn-outline-secondary btn-sm\" onclick=\"executarCicloDiarioManual()\" title=\"Executar rotina diária de verificação e faturação\">\n          <i class=\"bi bi-arrow-repeat me-1\"></i> Executar Ciclo Diário\n        </button>\n      </div>\n    </div>\n\n    <!-- Barra de Filtros e Pesquisa -->\n    <div class=\"row g-2 mb-3\">\n      <div class=\"col-md-5\">\n        <div class=\"input-group input-group-sm\">\n          <span class=\"input-group-text bg-white\"><i class=\"bi bi-search\"></i></span>\n          <input type=\"text\" id=\"filtroSaasBusca\" class=\"form-control\" placeholder=\"Pesquisar por escola, código oficial ou NUIT...\" oninput=\"filtrarTabelaAssinaturas()\">\n        </div>\n      </div>\n      <div class=\"col-md-3\">\n        <select id=\"filtroSaasEstado\" class=\"form-select form-select-sm\" onchange=\"carregarAssinaturasSuperAdmin()\">\n          <option value=\"\">Todos os Estados</option>\n          <option value=\"activa\">Activa</option>\n          <option value=\"fatura_pendente\">Fatura Pendente</option>\n          <option value=\"em_atraso\">Em Atraso (Faixa de Aviso)</option>\n          <option value=\"restrita\">Restrita (Apenas Leitura)</option>\n          <option value=\"suspensa\">Suspensa (Bloqueio Total)</option>\n          <option value=\"cancelada\">Cancelada</option>\n          <option value=\"teste\">Período de Teste</option>\n        </select>\n      </div>\n      <div class=\"col-md-2\">\n        <select id=\"filtroSaasPeriodicidade\" class=\"form-select form-select-sm\" onchange=\"carregarAssinaturasSuperAdmin()\">\n          <option value=\"\">Periodicidade</option>\n          <option value=\"mensal\">Mensal</option>\n          <option value=\"trimestral\">Trimestral</option>\n          <option value=\"semestral\">Semestral</option>\n          <option value=\"anual\">Anual</option>\n        </select>\n      </div>\n      <div class=\"col-md-2 text-end\">\n        <button class=\"btn btn-outline-primary btn-sm w-100\" onclick=\"carregarAssinaturasSuperAdmin()\">\n          <i class=\"bi bi-funnel me-1\"></i> Actualizar\n        </button>\n      </div>\n    </div>\n\n    <!-- Tabela Principal de Assinaturas -->\n    <div class=\"table-responsive\">\n      <table class=\"table table-hover align-middle\">\n        <thead class=\"table-light\">\n          <tr>\n            <th>Instituição</th>\n            <th>Plano</th>\n            <th>Periodicidade</th>\n            <th>Modo Data-Limite</th>\n            <th>Próxima Fatura</th>\n            <th>Tolerância / Suspensão</th>\n            <th>Estado</th>\n            <th class=\"text-end\">Operações</th>\n          </tr>\n        </thead>\n        <tbody id=\"tabelaSaasAssinaturas\">\n          <tr><td colspan=\"8\" class=\"text-center py-4\">A carregar assinaturas SaaS...</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n<!-- MODAL: FICHA DA INSTITUIÇÃO & HISTÓRICO COMPLETO -->\n<div class=\"modal fade\" id=\"modalFichaInstituicao\" tabindex=\"-1\" aria-hidden=\"true\">\n  <div class=\"modal-dialog modal-xl modal-dialog-scrollable\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header bg-dark text-white\">\n        <h5 class=\"modal-title fw-bold\" id=\"modalFichaInstituicaoTitulo\">Ficha da Instituição & Faturação SaaS</h5>\n        <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\"></button>\n      </div>\n      <div class=\"modal-body p-4\">\n        <!-- Detalhes do Contrato e Configuração -->\n        <div class=\"row mb-4\">\n          <div class=\"col-md-6\">\n            <div class=\"card p-3 h-100 bg-light\">\n              <h6 class=\"fw-bold border-bottom pb-2 mb-3 text-primary\"><i class=\"bi bi-info-circle me-1\"></i> Dados da Instituição</h6>\n              <p class=\"mb-1\"><strong>Nome:</strong> <span id=\"fichaEscolaNome\">-</span></p>\n              <p class=\"mb-1\"><strong>Código Oficial:</strong> <span id=\"fichaEscolaCodigo\">-</span></p>\n              <p class=\"mb-1\"><strong>NUIT:</strong> <span id=\"fichaEscolaNuit\">-</span></p>\n              <p class=\"mb-1\"><strong>Província / Distrito:</strong> <span id=\"fichaEscolaProvincia\">-</span></p>\n              <p class=\"mb-0\"><strong>Estado Geral:</strong> <span id=\"fichaEscolaEstadoBadge\" class=\"badge bg-secondary\">-</span></p>\n            </div>\n          </div>\n          <div class=\"col-md-6\">\n            <div class=\"card p-3 h-100 bg-light\">\n              <div class=\"d-flex justify-content-between align-items-center border-bottom pb-2 mb-3\">\n                <h6 class=\"fw-bold mb-0 text-primary\"><i class=\"bi bi-sliders me-1\"></i> Parâmetros da Assinatura</h6>\n                <button class=\"btn btn-sm btn-outline-primary\" onclick=\"abrirModalConfigurarAssinatura()\">\n                  <i class=\"bi bi-pencil-square me-1\"></i> Alterar Regras\n                </button>\n              </div>\n              <p class=\"mb-1\"><strong>Plano:</strong> <span id=\"fichaPlanoNome\">-</span> (<span id=\"fichaPlanoPreco\">-</span> MZN/mês)</p>\n              <p class=\"mb-1\"><strong>Periodicidade:</strong> <span id=\"fichaPeriodicidade\">-</span></p>\n              <p class=\"mb-1\"><strong>Modo Data-Limite:</strong> <span id=\"fichaModoDataLimite\">-</span></p>\n              <p class=\"mb-1\"><strong>Tolerância / Corte:</strong> <span id=\"fichaToleranciaInfo\">-</span></p>\n              <p class=\"mb-0\"><strong>Multa Configurada:</strong> <span id=\"fichaMultaInfo\">-</span></p>\n            </div>\n          </div>\n        </div>\n\n        <!-- Abas de Faturas, Pagamentos e Auditoria -->\n        <ul class=\"nav nav-tabs mb-3\" id=\"abasFicha\" role=\"tablist\">\n          <li class=\"nav-item\">\n            <button class=\"nav-link active\" data-bs-toggle=\"tab\" data-bs-target=\"#tabFaturas\"><i class=\"bi bi-receipt me-1\"></i> Histórico de Faturas</button>\n          </li>\n          <li class=\"nav-item\">\n            <button class=\"nav-link\" data-bs-toggle=\"tab\" data-bs-target=\"#tabPagamentos\"><i class=\"bi bi-cash-stack me-1\"></i> Pagamentos Registados</button>\n          </li>\n          <li class=\"nav-item\">\n            <button class=\"nav-link\" data-bs-toggle=\"tab\" data-bs-target=\"#tabAuditoria\"><i class=\"bi bi-journal-text me-1\"></i> Registo de Auditoria Imutável</button>\n          </li>\n        </ul>\n\n        <div class=\"tab-content\">\n          <div class=\"tab-pane fade show active\" id=\"tabFaturas\">\n            <div class=\"table-responsive\">\n              <table class=\"table table-sm table-hover align-middle\">\n                <thead class=\"table-light\">\n                  <tr>\n                    <th>Nº Fatura</th>\n                    <th>Período</th>\n                    <th>Valor Base</th>\n                    <th>Multa</th>\n                    <th>Valor Pago</th>\n                    <th>Data-Limite Efectiva</th>\n                    <th>Estado</th>\n                    <th class=\"text-end\">Ações</th>\n                  </tr>\n                </thead>\n                <tbody id=\"tabelaFichaFaturas\"></tbody>\n              </table>\n            </div>\n          </div>\n          <div class=\"tab-pane fade\" id=\"tabPagamentos\">\n            <div class=\"table-responsive\">\n              <table class=\"table table-sm table-hover align-middle\">\n                <thead class=\"table-light\">\n                  <tr>\n                    <th>Data</th>\n                    <th>Método</th>\n                    <th>Referência</th>\n                    <th>Valor (MZN)</th>\n                    <th>Estado</th>\n                    <th>Validado Por</th>\n                    <th class=\"text-end\">Comprovativo</th>\n                  </tr>\n                </thead>\n                <tbody id=\"tabelaFichaPagamentos\"></tbody>\n              </table>\n            </div>\n          </div>\n          <div class=\"tab-pane fade\" id=\"tabAuditoria\">\n            <div class=\"table-responsive\">\n              <table class=\"table table-sm table-hover align-middle\">\n                <thead class=\"table-light\">\n                  <tr>\n                    <th>Data / Hora</th>\n                    <th>Ação</th>\n                    <th>Estado Anterior ➔ Novo</th>\n                    <th>Responsável</th>\n                    <th>Motivo / Justificação</th>\n                  </tr>\n                </thead>\n                <tbody id=\"tabelaFichaAuditoria\"></tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer bg-light\">\n        <button type=\"button\" class=\"btn btn-outline-danger btn-sm\" onclick=\"modalSuspenderManualInstituicao()\">\n          <i class=\"bi bi-slash-circle me-1\"></i> Suspender Manualmente\n        </button>\n        <button type=\"button\" class=\"btn btn-outline-success btn-sm\" onclick=\"modalReactivarManualInstituicao()\">\n          <i class=\"bi bi-arrow-clockwise me-1\"></i> Reactivar Manualmente\n        </button>\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\" data-bs-dismiss=\"modal\">Fechar</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- MODAL: CONFIGURAÇÃO DE ASSINATURA -->\n<div class=\"modal fade\" id=\"modalConfigurarAssinatura\" tabindex=\"-1\" aria-hidden=\"true\">\n  <div class=\"modal-dialog modal-lg\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header bg-primary text-white\">\n        <h5 class=\"modal-title fw-bold\">Configurar Parâmetros da Assinatura</h5>\n        <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\"></button>\n      </div>\n      <form id=\"formConfigurarAssinatura\" onsubmit=\"salvarConfiguracaoAssinatura(event)\">\n        <div class=\"modal-body p-4\">\n          <input type=\"hidden\" id=\"cfgAssinaturaId\">\n          <div class=\"row g-3\">\n            <div class=\"col-md-6\">\n              <label class=\"form-label fw-semibold\">Periodicidade de Cobrança</label>\n              <select id=\"cfgPeriodicidade\" class=\"form-select\" required onchange=\"aoMudarPeriodicidadeConfig()\">\n                <option value=\"mensal\">Mensal (Preço regular)</option>\n                <option value=\"trimestral\">Trimestral (5% de desconto)</option>\n                <option value=\"semestral\">Semestral (10% de desconto)</option>\n                <option value=\"anual\">Anual (15% de desconto)</option>\n              </select>\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label fw-semibold\">Modo da Data-Limite</label>\n              <select id=\"cfgModoDataLimite\" class=\"form-select\" required onchange=\"aoMudarModoDataLimite()\">\n                <option value=\"automatico\">Automático (Predefinição da Periodicidade)</option>\n                <option value=\"dia_fixo\">Dia Fixo (Ex: dia 5 ou dia 25 de cada mês)</option>\n                <option value=\"manual\">Manual (Definido por fatura)</option>\n              </select>\n            </div>\n            <div class=\"col-md-6\" id=\"boxDiaFixo\" style=\"display: none;\">\n              <label class=\"form-label fw-semibold\">Dia Fixo de Vencimento (1 a 31)</label>\n              <input type=\"number\" id=\"cfgDiaLimite\" class=\"form-control\" min=\"1\" max=\"31\" placeholder=\"Ex: 10\">\n              <small class=\"text-muted\">Se o mês tiver menos dias, o último dia do mês será usado automaticamente.</small>\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label fw-semibold\">Dias de Tolerância</label>\n              <input type=\"number\" id=\"cfgDiasTolerancia\" class=\"form-control\" min=\"0\" value=\"5\" required>\n              <small class=\"text-muted\">Após o limite, o sistema sinaliza atraso. Acesso total mantido.</small>\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label fw-semibold\">Dias até Suspensão (Corte)</label>\n              <input type=\"number\" id=\"cfgDiasAteSuspensao\" class=\"form-control\" min=\"0\" value=\"15\" required>\n              <small class=\"text-muted\">Após a tolerância, o sistema fica em modo 'restrita' (só leitura). Depois suspende.</small>\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label fw-semibold\">Data de Bloqueio Manual (Opcional)</label>\n              <input type=\"date\" id=\"cfgDataBloqueioManual\" class=\"form-control\">\n              <small class=\"text-muted\">Sobrescreve a suspensão e bloqueia na data especificada.</small>\n            </div>\n\n            <!-- SECÇÃO DE MULTA: DEFINIDA EM FUNÇÃO DA PERCENTAGEM COM PROCESSAMENTO AUTOMÁTICO DO VALOR -->\n            <div class=\"col-12 mt-2\">\n              <div class=\"card p-3 bg-light border\">\n                <div class=\"row g-3 align-items-center\">\n                  <div class=\"col-md-4\">\n                    <label class=\"form-label fw-semibold mb-1\">Tipo de Multa por Atraso</label>\n                    <select id=\"cfgMultaTipo\" class=\"form-select\" onchange=\"aoMudarTipoMulta()\">\n                      <option value=\"percentagem\">Percentagem sobre Valor Base (%)</option>\n                      <option value=\"nenhuma\">Nenhuma Multa</option>\n                      <option value=\"fixo\">Valor Fixo Manual (MZN)</option>\n                    </select>\n                  </div>\n                  <div class=\"col-md-4\" id=\"boxMultaPercentagem\">\n                    <label class=\"form-label fw-semibold mb-1\" id=\"lblMultaEntrada\">Percentagem da Multa (%)</label>\n                    <div class=\"input-group\">\n                      <input type=\"number\" step=\"0.1\" min=\"0\" max=\"100\" id=\"cfgMultaPercentagem\" class=\"form-control\" value=\"10.0\" oninput=\"calcularMultaAutomatica()\" placeholder=\"Ex: 10\">\n                      <span class=\"input-group-text fw-bold\" id=\"sufixoMultaEntrada\">%</span>\n                    </div>\n                    <small class=\"text-muted\" id=\"ajudaMultaEntrada\">Taxa percentual aplicada à fatura.</small>\n                  </div>\n                  <div class=\"col-md-4\" id=\"boxMultaValorProcessado\">\n                    <label class=\"form-label fw-semibold mb-1\">Valor da Multa Processado</label>\n                    <div class=\"input-group\">\n                      <input type=\"text\" id=\"cfgMultaValorCalculado\" class=\"form-control bg-white fw-bold text-danger border\" readonly value=\"0,00\">\n                      <span class=\"input-group-text bg-light fw-bold\">MZN</span>\n                    </div>\n                    <small class=\"text-muted d-block text-truncate\" id=\"cfgMultaBaseInfo\">Calculado sobre o valor base: 0,00 MZN</small>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <input type=\"hidden\" id=\"cfgMultaValor\" value=\"0.00\">\n          </div>\n        </div>\n        <div class=\"modal-footer bg-light\">\n          <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancelar</button>\n          <button type=\"submit\" class=\"btn btn-primary fw-bold\">Guardar Configuração</button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n<!-- MODAL: PRORROGAR DATA LIMITE DE FATURA -->\n<div class=\"modal fade\" id=\"modalProrrogarFatura\" tabindex=\"-1\" aria-hidden=\"true\">\n  <div class=\"modal-dialog\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header bg-info text-dark\">\n        <h5 class=\"modal-title fw-bold\"><i class=\"bi bi-calendar-plus me-1\"></i> Prorrogar Data-Limite de Fatura</h5>\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button>\n      </div>\n      <form id=\"formProrrogarFatura\" onsubmit=\"salvarProrrogacaoFatura(event)\">\n        <div class=\"modal-body p-4\">\n          <input type=\"hidden\" id=\"prorrogarFaturaId\">\n          <div class=\"mb-3\">\n            <label class=\"form-label fw-semibold\">Fatura Selecionada</label>\n            <input type=\"text\" id=\"prorrogarFaturaNumero\" class=\"form-control bg-light\" readonly>\n          </div>\n          <div class=\"mb-3\">\n            <label class=\"form-label fw-semibold\">Nova Data-Limite Efectiva</label>\n            <input type=\"date\" id=\"prorrogarNovaData\" class=\"form-control\" required>\n            <small class=\"text-muted\">A nova data deve ser posterior à data de início do período da fatura.</small>\n          </div>\n          <div class=\"mb-3\">\n            <label class=\"form-label fw-semibold\">Justificação Obrigatória</label>\n            <textarea id=\"prorrogarMotivo\" class=\"form-control\" rows=\"3\" required placeholder=\"Indique o motivo formal da prorrogação (ex: ciclo orçamental de instituição pública, solicitação formal da direcção, etc.).\"></textarea>\n          </div>\n        </div>\n        <div class=\"modal-footer bg-light\">\n          <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancelar</button>\n          <button type=\"submit\" class=\"btn btn-info fw-bold\">Confirmar Prorrogação</button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n<!-- MODAL: REJEITAR PAGAMENTO -->\n<div class=\"modal fade\" id=\"modalRejeitarPagamento\" tabindex=\"-1\" aria-hidden=\"true\">\n  <div class=\"modal-dialog\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header bg-danger text-white\">\n        <h5 class=\"modal-title fw-bold\"><i class=\"bi bi-x-circle me-1\"></i> Rejeitar Comprovativo de Pagamento</h5>\n        <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\"></button>\n      </div>\n      <form id=\"formRejeitarPagamento\" onsubmit=\"salvarRejeicaoPagamento(event)\">\n        <div class=\"modal-body p-4\">\n          <input type=\"hidden\" id=\"rejeitarPagamentoId\">\n          <p class=\"text-muted\">Indique a justificação da rejeição. A instituição será notificada e poderá submeter um novo comprovativo válido.</p>\n          <div class=\"mb-3\">\n            <label class=\"form-label fw-semibold\">Motivo da Rejeição (Obrigatório)</label>\n            <textarea id=\"rejeitarMotivo\" class=\"form-control\" rows=\"3\" required placeholder=\"Ex: Comprovativo ilegível, valor divergente do total devido, referência inexistente nos extractos bancários...\"></textarea>\n          </div>\n        </div>\n        <div class=\"modal-footer bg-light\">\n          <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancelar</button>\n          <button type=\"submit\" class=\"btn btn-danger fw-bold\">Rejeitar Pagamento</button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n<!-- MODAL: SUSPENDER / REACTIVAR MANUAL -->\n<div class=\"modal fade\" id=\"modalAcaoManualInstituicao\" tabindex=\"-1\" aria-hidden=\"true\">\n  <div class=\"modal-dialog\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header\" id=\"modalAcaoManualHeader\">\n        <h5 class=\"modal-title fw-bold\" id=\"modalAcaoManualTitulo\">Operação Manual</h5>\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button>\n      </div>\n      <form id=\"formAcaoManualInstituicao\" onsubmit=\"salvarAcaoManualInstituicao(event)\">\n        <div class=\"modal-body p-4\">\n          <input type=\"hidden\" id=\"acaoManualTipo\">\n          <input type=\"hidden\" id=\"acaoManualInstituicaoId\">\n          <div class=\"alert alert-warning\" id=\"acaoManualAviso\"></div>\n          <div class=\"mb-3\">\n            <label class=\"form-label fw-semibold\">Justificação Obrigatória</label>\n            <textarea id=\"acaoManualMotivo\" class=\"form-control\" rows=\"3\" required placeholder=\"A justificação é registada para efeitos de auditoria jurídica e operacional.\"></textarea>\n          </div>\n        </div>\n        <div class=\"modal-footer bg-light\">\n          <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancelar</button>\n          <button type=\"submit\" class=\"btn fw-bold\" id=\"btnAcaoManualSubmit\">Confirmar Operação</button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n</section>\n",
  "painel-escola/assinatura-escola": "<!-- ===================================================================== -->\n<!-- SIGE - PAINEL-ESCOLA | Assinatura do Sistema & Pagamentos SaaS -->\n<!-- Página independente do módulo: assinatura-escola.html -->\n<!-- Moeda Oficial: MZN (Metical) | Fuso Horário: Africa/Maputo -->\n<!-- ===================================================================== -->\n<section id=\"view-assinatura-escola\" class=\"modulo-view\" style=\"display: none;\">\n  <!-- Alerta de Estado da Assinatura -->\n  <div id=\"bannerAlertaAssinaturaEscola\" class=\"alert d-none mb-4 shadow-sm\" role=\"alert\"></div>\n\n  <!-- Resumo da Assinatura e Estado Atual -->\n  <div class=\"row g-3 mb-4\">\n    <div class=\"col-md-4\">\n      <div class=\"card p-4 h-100 shadow-sm border-primary\">\n        <span class=\"text-muted small text-uppercase fw-semibold\">Estado da Subscrição</span>\n        <div class=\"d-flex align-items-center justify-content-between my-2\">\n          <h3 id=\"escolaAssinaturaEstado\" class=\"fw-bold mb-0 text-success\">Activa</h3>\n          <span id=\"escolaAssinaturaBadge\" class=\"badge bg-success fs-6\">Acesso Pleno</span>\n        </div>\n        <p class=\"text-muted small mb-0\" id=\"escolaAssinaturaDescricao\">A sua instituição usufrui de todas as funcionalidades contratadas.</p>\n      </div>\n    </div>\n    <div class=\"col-md-4\">\n      <div class=\"card p-4 h-100 shadow-sm\">\n        <span class=\"text-muted small text-uppercase fw-semibold\">Plano Contratado</span>\n        <h4 id=\"escolaPlanoNome\" class=\"fw-bold mb-1 text-primary\">Plano Padrão</h4>\n        <h5 id=\"escolaPlanoPreco\" class=\"fw-bold text-dark mb-1\">0 <span class=\"moeda-sufixo\">MZN</span></h5>\n        <small class=\"text-muted\" id=\"escolaPlanoPeriodicidade\">Periodicidade Mensal</small>\n      </div>\n    </div>\n    <div class=\"col-md-4\">\n      <div class=\"card p-4 h-100 shadow-sm\">\n        <span class=\"text-muted small text-uppercase fw-semibold\">Próximo Vencimento</span>\n        <h3 id=\"escolaProximoVencimento\" class=\"fw-bold mb-1 text-dark\">-</h3>\n        <small class=\"text-muted\" id=\"escolaDiasRestantes\">Calculado pelo ciclo de faturação</small>\n        <div class=\"mt-2\">\n          <button class=\"btn btn-warning btn-sm fw-bold w-100\" onclick=\"abrirModalRegistarPagamentoEscola()\">\n            <i class=\"bi bi-wallet2 me-1\"></i> Registar Pagamento\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Coordenadas Bancárias & Métodos de Pagamento em Moçambique -->\n  <div class=\"card p-4 mb-4 bg-light border-0 shadow-sm\">\n    <h6 class=\"fw-bold mb-2 text-dark\"><i class=\"bi bi-credit-card-2-front me-2\"></i>Contas Oficiais e Carteiras Móveis para Pagamento de Assinaturas (Moçambique)</h6>\n    <div class=\"row g-3 text-secondary small\">\n      <div class=\"col-md-3\">\n        <div class=\"p-3 bg-white rounded border\">\n          <strong class=\"d-block text-danger\"><i class=\"bi bi-phone me-1\"></i> M-Pesa (Vodacom)</strong>\n          <span>Número: <strong>84 000 0000</strong></span><br>\n          <span>Titular: <strong>SIGE Moçambique</strong></span>\n        </div>\n      </div>\n      <div class=\"col-md-3\">\n        <div class=\"p-3 bg-white rounded border\">\n          <strong class=\"d-block text-warning\"><i class=\"bi bi-phone me-1\"></i> e-Mola (Movitel)</strong>\n          <span>Número: <strong>86 000 0000</strong></span><br>\n          <span>Titular: <strong>SIGE Moçambique</strong></span>\n        </div>\n      </div>\n      <div class=\"col-md-3\">\n        <div class=\"p-3 bg-white rounded border\">\n          <strong class=\"d-block text-primary\"><i class=\"bi bi-bank me-1\"></i> Millennium BIM</strong>\n          <span>Conta: <strong>123456789</strong></span><br>\n          <span>NIB: <strong>0001 0000 12345678901 23</strong></span>\n        </div>\n      </div>\n      <div class=\"col-md-3\">\n        <div class=\"p-3 bg-white rounded border\">\n          <strong class=\"d-block text-success\"><i class=\"bi bi-bank me-1\"></i> BCI / Standard Bank</strong>\n          <span>Conta: <strong>987654321</strong></span><br>\n          <span>NIB: <strong>0008 0000 98765432101 45</strong></span>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Tabela de Faturas Emitidas -->\n  <div class=\"card p-4 shadow-sm\">\n    <div class=\"d-flex justify-content-between align-items-center mb-3\">\n      <h5 class=\"fw-bold mb-0\"><i class=\"bi bi-receipt me-2\"></i>Histórico de Faturas da Instituição</h5>\n      <button class=\"btn btn-outline-primary btn-sm\" onclick=\"carregarMinhaAssinaturaEscola()\">\n        <i class=\"bi bi-arrow-repeat me-1\"></i> Actualizar\n      </button>\n    </div>\n    <div class=\"table-responsive\">\n      <table class=\"table table-hover align-middle\">\n        <thead class=\"table-light\">\n          <tr>\n            <th>Nº Fatura</th>\n            <th>Período Cobrado</th>\n            <th>Valor Base</th>\n            <th>Multa por Atraso</th>\n            <th>Valor Liquidado</th>\n            <th>Data-Limite de Pagamento</th>\n            <th>Estado</th>\n            <th class=\"text-end\">Operação</th>\n          </tr>\n        </thead>\n        <tbody id=\"tabelaMinhasFaturas\">\n          <tr><td colspan=\"8\" class=\"text-center py-4\">A carregar faturas da instituição...</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n<!-- MODAL: REGISTAR PAGAMENTO DA INSTITUIÇÃO -->\n<div class=\"modal fade\" id=\"modalRegistarPagamentoEscola\" tabindex=\"-1\" aria-hidden=\"true\">\n  <div class=\"modal-dialog modal-lg\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header bg-warning text-dark\">\n        <h5 class=\"modal-title fw-bold\"><i class=\"bi bi-wallet2 me-1\"></i> Submeter Comprovativo de Pagamento</h5>\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button>\n      </div>\n      <form id=\"formRegistarPagamentoEscola\" onsubmit=\"salvarPagamentoEscola(event)\">\n        <div class=\"modal-body p-4\">\n          <div class=\"row g-3\">\n            <div class=\"col-md-12\">\n              <label class=\"form-label fw-semibold\">Fatura a Liquidar</label>\n              <select id=\"escolaPagFaturaId\" class=\"form-select\" required onchange=\"aoMudarFaturaSelecionadaEscola()\">\n                <option value=\"\">-- Selecione a fatura correspondente --</option>\n              </select>\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label fw-semibold\">Método de Pagamento</label>\n              <select id=\"escolaPagMetodo\" class=\"form-select\" required>\n                <option value=\"M-Pesa\">M-Pesa (Vodacom)</option>\n                <option value=\"e-Mola\">e-Mola (Movitel)</option>\n                <option value=\"transferencia_bancaria\">Transferência Bancária / Depósito</option>\n                <option value=\"numerario\">Numerário (Na Secretaria / Representante)</option>\n              </select>\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label fw-semibold\">Código / Referência da Transacção</label>\n              <input type=\"text\" id=\"escolaPagReferencia\" class=\"form-control\" required placeholder=\"Ex: MP261017.1234.A56789 ou NIB / Talão\">\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label fw-semibold\">Valor Pago (MZN)</label>\n              <div class=\"input-group\">\n                <input type=\"number\" step=\"0.01\" min=\"0.01\" id=\"escolaPagValor\" class=\"form-control\" required placeholder=\"0.00\">\n                <span class=\"input-group-text\">MZN</span>\n              </div>\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label fw-semibold\">Anexar Comprovativo (PDF, JPG, PNG)</label>\n              <input type=\"file\" id=\"escolaPagComprovativo\" class=\"form-control\" accept=\".pdf,.jpg,.jpeg,.png\">\n              <small class=\"text-muted\">Limite de 10 MB. O comprovativo é guardado com segurança.</small>\n            </div>\n          </div>\n        </div>\n        <div class=\"modal-footer bg-light\">\n          <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancelar</button>\n          <button type=\"submit\" class=\"btn btn-warning fw-bold\" id=\"btnSubmeterPagamentoEscola\">\n            <i class=\"bi bi-send-check me-1\"></i> Enviar Comprovativo para Validação\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n</section>\n"
};
